(() => {
  "use strict";
  const catalog = {"My work on Iraq's oil dependence, government finances and economic outlook. A Python application and bachelor's thesis in progress.":{"ro":"Cercetarea mea despre dependența de petrol, finanțele publice și perspectivele economice ale Irakului. O aplicație Python și o lucrare de licență în dezvoltare.","ar":"بحثي حول اعتماد العراق على النفط وماليته العامة وآفاقه الاقتصادية. تطبيق بلغة Python ومشروع تخرج قيد التطوير."},"Iraq’s Economic Outlook | Nooruldeen’s thesis":{"ro":"Perspectivele economice ale Irakului | Lucrarea de licență a lui Nooruldeen","ar":"الآفاق الاقتصادية للعراق | مشروع تخرج نورالدين"},"Skip to my project":{"ro":"Sari la proiectul meu","ar":"انتقل إلى مشروعي"},"Back to my website":{"ro":"Înapoi la site-ul meu","ar":"العودة إلى موقعي"},"My portrait":{"ro":"Portretul meu","ar":"صورتي الشخصية"},"Al Sammarraie":{"ro":"Al Sammarraie","ar":"السامرائي"},"Noor":{"ro":"Noor","ar":"نور"},"uldeen":{"ro":"uldeen","ar":"الدين"},"MY THESIS / WORK IN PROGRESS":{"ro":"LUCRAREA MEA / ÎN DEZVOLTARE","ar":"مشروع تخرجي / قيد التطوير"},"PROJECT FILES":{"ro":"FIȘIERELE PROIECTULUI","ar":"ملفات المشروع"},"Main navigation":{"ro":"Navigare principală","ar":"التنقل الرئيسي"},"HOME":{"ro":"ACASĂ","ar":"الرئيسية"},"ABOUT":{"ro":"DESPRE","ar":"نبذة"},"WORK":{"ro":"LUCRĂRI","ar":"الأعمال"},"THESIS":{"ro":"LICENȚĂ","ar":"مشروع التخرج"},"CONTACT":{"ro":"CONTACT","ar":"تواصل"},"DATA":{"ro":"DATE","ar":"بيانات"},"AND CODE":{"ro":"ȘI COD","ar":"وبرمجة"},"IRAQ ECONOMIC OBSERVATORY":{"ro":"OBSERVATORUL ECONOMIC AL IRAKULUI","ar":"المرصد الاقتصادي العراقي"},"Iraq’s":{"ro":"Perspectivele","ar":"الآفاق"},"economic":{"ro":"economice","ar":"الاقتصادية"},"outlook":{"ro":"ale Irakului","ar":"للعراق"},"Iraq’s Economic Outlook: Building an Economic Analysis System with Iraq as a Case Study":{"ro":"Perspectivele economice ale Irakului: Construirea unui sistem de analiză economică, cu Irakul ca studiu de caz","ar":"الآفاق الاقتصادية للعراق: بناء نظام للتحليل الاقتصادي باستخدام العراق كدراسة حالة"},"I grew up in Iraq, and I want to understand how its oil wealth relates to pressure on public finances and the difficulty of building a more diverse economy. This is the Python application and research I am developing for my bachelor's thesis at ASE.":{"ro":"Am crescut în Irak și vreau să înțeleg legătura dintre bogăția sa petrolieră, presiunea asupra finanțelor publice și dificultatea construirii unei economii mai diversificate. Acestea sunt aplicația Python și cercetarea pe care le dezvolt pentru lucrarea mea de licență la ASE.","ar":"نشأت في العراق، وأريد أن أفهم علاقة ثروته النفطية بالضغوط على المالية العامة وصعوبة بناء اقتصاد أكثر تنوعًا. هذا هو تطبيق Python والبحث اللذان أعمل عليهما لمشروع تخرجي في أكاديمية بوخارست للدراسات الاقتصادية."},"Explore my prototype":{"ro":"Explorează prototipul meu","ar":"استكشف النموذج الأولي"},"Read my research plan":{"ro":"Citește planul meu de cercetare","ar":"اقرأ خطة بحثي"},"Economic Informatics · ASE Bucharest":{"ro":"Informatică Economică · ASE București","ar":"المعلوماتية الاقتصادية · أكاديمية بوخارست للدراسات الاقتصادية"},"My intended defence: July 2027":{"ro":"Susținerea planificată: iulie 2027","ar":"موعد المناقشة المخطط له: يوليو 2027"},"The Malwiya minaret in Samarra, Iraq, photographed by David Stanley":{"ro":"Minaretul Malwiya din Samarra, Irak, fotografiat de David Stanley","ar":"مئذنة الملوية في سامراء، العراق، بعدسة David Stanley"},"SAMARRA, IRAQ":{"ro":"SAMARRA, IRAK","ar":"سامراء، العراق"},"Photograph: David Stanley.":{"ro":"Fotografie: David Stanley.","ar":"تصوير: David Stanley."},"MY COUNTRY":{"ro":"ȚARA MEA","ar":"بلدي"},"MY QUESTIONS":{"ro":"ÎNTREBĂRILE MELE","ar":"أسئلتي"},"The foundations of my thesis":{"ro":"Fundamentele lucrării mele de licență","ar":"أسس مشروع تخرجي"},"A starting point":{"ro":"Un punct de pornire","ar":"نقطة البداية"},"Understanding Iraq’s economy in the years after 2003.":{"ro":"Înțelegerea economiei Irakului în anii de după 2003.","ar":"فهم اقتصاد العراق في السنوات التي تلت عام 2003."},"Economic analysis":{"ro":"Analiză economică","ar":"التحليل الاقتصادي"},"Reading the evidence, following the sources and asking better questions.":{"ro":"Examinarea dovezilor, urmărirea surselor și formularea unor întrebări mai bune.","ar":"قراءة الأدلة وتتبع المصادر وطرح أسئلة أفضل."},"A Python system":{"ro":"Un sistem Python","ar":"نظام بلغة Python"},"Bringing data, methods and an interactive application together.":{"ro":"Date, metode și o aplicație interactivă reunite într-un singur sistem.","ar":"جمع البيانات والأساليب والتطبيق التفاعلي في نظام واحد."},"Possible futures":{"ro":"Viitoruri posibile","ar":"آفاق محتملة"},"Exploring forecasts, uncertainty and clearly stated scenarios.":{"ro":"Explorarea prognozelor, a incertitudinii și a scenariilor cu ipoteze explicite.","ar":"استكشاف التنبؤات وعدم اليقين والسيناريوهات ذات الافتراضات الواضحة."},"Sections in my thesis project":{"ro":"Secțiunile proiectului meu de licență","ar":"أقسام مشروع تخرجي"},"THE QUESTIONS":{"ro":"ÎNTREBĂRILE","ar":"الأسئلة"},"TRY THE PREVIEW":{"ro":"ÎNCEARCĂ PREVIZUALIZAREA","ar":"جرّب المعاينة"},"DATA & SOURCES":{"ro":"DATE ȘI SURSE","ar":"البيانات والمصادر"},"WHAT'S NEXT":{"ro":"CE URMEAZĂ","ar":"الخطوات القادمة"},"02 / WHAT I WANT TO UNDERSTAND":{"ro":"02 / CE VREAU SĂ ÎNȚELEG","ar":"02 / ما أريد فهمه"},"DATA / ECONOMICS / CODE":{"ro":"DATE / ECONOMIE / COD","ar":"بيانات / اقتصاد / برمجة"},"I want to understand":{"ro":"Vreau să înțeleg","ar":"أريد أن أفهم"},"Iraq better.":{"ro":"Irakul mai bine.","ar":"العراق بشكل أفضل."},"What interests me is how Iraq has developed after the US-led invasion in 2003 and the fall of Saddam Hussein's regime. I want to understand why having valuable oil resources has not made development straightforward, look at the evidence carefully, and build a tool that helps me explore the questions.":{"ro":"Mă interesează cum s-a dezvoltat Irakul după invazia condusă de SUA în 2003 și căderea regimului lui Saddam Hussein. Vreau să înțeleg de ce resursele petroliere valoroase nu au făcut dezvoltarea simplă, să examinez atent dovezile și să construiesc un instrument care mă ajută să explorez aceste întrebări.","ar":"ما يهمني هو تطور العراق بعد الغزو الذي قادته الولايات المتحدة عام 2003 وسقوط نظام صدام حسين. أريد فهم سبب تعقّد التنمية رغم الموارد النفطية القيّمة، وقراءة الأدلة بعناية، وبناء أداة تساعدني على استكشاف هذه الأسئلة."},"MY PROVISIONAL THESIS TITLE":{"ro":"TITLUL MEU PROVIZORIU","ar":"عنوان مشروع تخرجي الحالي"},"I have chosen this title for now. Professor Uscatu has agreed to coordinate my thesis, and I will confirm the title and final scope with him.":{"ro":"Am ales acest titlu pentru moment. Profesorul Uscatu a acceptat să îmi coordoneze lucrarea, iar titlul și delimitarea finală vor fi confirmate împreună cu el.","ar":"اخترت هذا العنوان في الوقت الحالي. وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي، وسأؤكد معه العنوان والنطاق النهائيين."},"How has Iraq developed since 2003?":{"ro":"Cum s-a dezvoltat Irakul din 2003?","ar":"كيف تطور العراق منذ عام 2003؟"},"I chose 2003 because it marks the invasion and the fall of Saddam Hussein's regime. I want to follow the economy after that change, using growth, real GDP per person and manufacturing.":{"ro":"Am ales anul 2003 deoarece marchează invazia și căderea regimului lui Saddam Hussein. Vreau să urmăresc economia după această schimbare, folosind creșterea economică, PIB-ul real pe persoană și industria prelucrătoare.","ar":"اخترت عام 2003 لأنه يمثل الغزو وسقوط نظام صدام حسين. أريد تتبع الاقتصاد بعد هذا التغيير من خلال النمو والناتج المحلي الإجمالي الحقيقي للفرد والصناعة التحويلية."},"What puts pressure on the budget?":{"ro":"Ce pune presiune pe buget?","ar":"ما الذي يضغط على الموازنة؟"},"I am examining recorded revenue and spending month by month, while keeping oil-related income and accounting adjustments visible.":{"ro":"Examinez veniturile și cheltuielile înregistrate, lună de lună, păstrând vizibile veniturile legate de petrol și ajustările contabile.","ar":"أدرس الإيرادات والنفقات المسجلة شهرًا بشهر، مع إبقاء الدخل المرتبط بالنفط والتعديلات المحاسبية ظاهرين."},"Can a forecast improve on a simple baseline?":{"ro":"Poate o prognoză depăși un reper simplu?","ar":"هل يمكن لتنبؤ أن يتفوق على مرجع بسيط؟"},"I compare five methods on the same months and inspect their errors and uncertainty before choosing a final model.":{"ro":"Compar cinci metode pe aceleași luni și examinez erorile și incertitudinea înainte să aleg modelul final.","ar":"أقارن خمس طرق على الأشهر نفسها، وأراجع أخطاءها وعدم اليقين فيها قبل اختيار النموذج النهائي."},"How much do the assumptions change the outlook?":{"ro":"Cât de mult schimbă ipotezele perspectivele?","ar":"إلى أي مدى تغيّر الافتراضات الآفاق؟"},"I can change an oil-price or spending assumption and calculate the resulting pressure around a published annual baseline.":{"ro":"Pot schimba o ipoteză privind prețul petrolului sau cheltuielile și calcula presiunea rezultată în raport cu un scenariu anual de referință publicat.","ar":"يمكنني تغيير افتراض حول سعر النفط أو الإنفاق وحساب الضغط الناتج مقارنة بمسار سنوي مرجعي منشور."},"I want to understand what the evidence shows. A country comparison can help me spot a pattern, but it cannot prove what caused it.":{"ro":"Vreau să înțeleg ce arată dovezile. Compararea țărilor poate evidenția un tipar, dar nu poate demonstra cauza lui.","ar":"أريد فهم ما توضحه الأدلة. قد تساعد مقارنة البلدان على ملاحظة نمط، لكنها لا تثبت سببه."},"03 / THE APPLICATION I AM BUILDING":{"ro":"03 / APLICAȚIA PE CARE O CONSTRUIESC","ar":"03 / التطبيق الذي أبنيه"},"WORKING PROTOTYPE":{"ro":"PROTOTIP FUNCȚIONAL","ar":"نموذج أولي يعمل"},"Try the work":{"ro":"Încearcă proiectul","ar":"جرّب المشروع"},"for yourself.":{"ro":"chiar tu.","ar":"بنفسك."},"This is a browser preview of my saved results and the controls I have prepared. I am keeping the Python application in my private repository while I build it. I want to share it more widely when it is ready.":{"ro":"Aceasta este o previzualizare în browser a rezultatelor salvate și a comenzilor pe care le-am pregătit. Păstrez aplicația Python în depozitul meu privat cât timp o dezvolt. Vreau să o distribui mai larg când va fi pregătită.","ar":"هذه معاينة في المتصفح لنتائجي المحفوظة وأدوات التحكم التي أعددتها. أحتفظ بتطبيق Python في مستودعي الخاص أثناء تطويره، وأريد إتاحته بشكل أوسع عندما يصبح جاهزًا."},"MY RESEARCH WORKBENCH":{"ro":"ATELIERUL MEU DE CERCETARE","ar":"مساحة البحث التفاعلية"},"Saved source snapshots: October 2026":{"ro":"Date sursă salvate: octombrie 2026","ar":"نسخ المصادر المحفوظة: أكتوبر 2026"},"Loading the saved research preview…":{"ro":"Se încarcă previzualizarea rezultatelor salvate…","ar":"جارٍ تحميل معاينة البحث المحفوظة…"},"Enable JavaScript to explore the saved results. The research plan and presentation are available below.":{"ro":"Activează JavaScript pentru a explora rezultatele salvate. Planul de cercetare și informațiile despre prezentare sunt mai jos.","ar":"فعّل JavaScript لاستكشاف النتائج المحفوظة. ستجد خطة البحث ومعلومات العرض أدناه."},"Explore my project":{"ro":"Explorează proiectul meu","ar":"استكشف مشروعي"},"Iraq over time":{"ro":"Irakul în timp","ar":"العراق عبر الزمن"},"Monthly forecasts":{"ro":"Prognoze lunare","ar":"التنبؤات الشهرية"},"Budget scenarios":{"ro":"Scenarii bugetare","ar":"سيناريوهات الموازنة"},"Country comparisons":{"ro":"Comparații între țări","ar":"مقارنة البلدان"},"The longer economic picture":{"ro":"Imaginea economică pe termen lung","ar":"الصورة الاقتصادية على المدى الطويل"},"I keep the history from 2003 and compare the yearly figures as they were published.":{"ro":"Păstrez istoricul din 2003 și compar valorile anuale în forma publicată.","ar":"أحتفظ بالسجل منذ عام 2003 وأقارن البيانات السنوية كما نُشرت."},"How to read this view":{"ro":"Cum se citește această vizualizare","ar":"كيف تقرأ هذا العرض"},"Real GDP per person:":{"ro":"PIB real pe persoană:","ar":"الناتج المحلي الإجمالي الحقيقي للفرد:"},"economic output divided by population, adjusted to 2015 prices. It is not household income.":{"ro":"producția economică împărțită la populație, ajustată la prețurile din 2015. Nu reprezintă venitul gospodăriilor.","ar":"الناتج الاقتصادي مقسومًا على السكان، بأسعار عام 2015. ولا يمثل دخل الأسر."},"Real GDP growth:":{"ro":"Creșterea PIB-ului real:","ar":"نمو الناتج المحلي الإجمالي الحقيقي:"},"the annual percentage change in economic output after price changes.":{"ro":"variația procentuală anuală a producției economice, după ajustarea pentru schimbările de preț.","ar":"التغير السنوي في الناتج الاقتصادي كنسبة مئوية بعد تعديل تغيرات الأسعار."},"Manufacturing share:":{"ro":"Ponderea industriei prelucrătoare:","ar":"حصة الصناعة التحويلية:"},"manufacturing value added as a percentage of GDP.":{"ro":"valoarea adăugată a industriei prelucrătoare ca procent din PIB.","ar":"القيمة المضافة للصناعة التحويلية كنسبة من الناتج المحلي الإجمالي."},"Oil rents:":{"ro":"Rente petroliere:","ar":"الريع النفطي:"},"the estimated value of oil production after production costs, as a percentage of GDP. This is not government oil revenue.":{"ro":"valoarea estimată a producției petroliere după costurile de producție, ca procent din PIB. Nu reprezintă veniturile petroliere ale guvernului.","ar":"القيمة المقدرة لإنتاج النفط بعد تكاليف الإنتاج، كنسبة من الناتج المحلي الإجمالي. ولا تمثل الإيرادات النفطية الحكومية."},"Each point is a published annual observation. Missing years stay missing. Hover or tap a line to inspect the country, year and saved value.":{"ro":"Fiecare punct este o observație anuală publicată. Anii fără date rămân fără date. Treci cursorul peste o linie sau atinge-o pentru a vedea țara, anul și valoarea salvată.","ar":"كل نقطة تمثل مشاهدة سنوية منشورة. تبقى السنوات المفقودة بلا بيانات. مرّر المؤشر فوق الخط أو المسه لعرض البلد والسنة والقيمة المحفوظة."},"Indicator":{"ro":"Indicator","ar":"المؤشر"},"Real GDP per person":{"ro":"PIB real pe persoană","ar":"الناتج المحلي الإجمالي الحقيقي للفرد"},"Real GDP growth":{"ro":"Creșterea PIB-ului real","ar":"نمو الناتج المحلي الإجمالي الحقيقي"},"Manufacturing share":{"ro":"Ponderea industriei prelucrătoare","ar":"حصة الصناعة التحويلية"},"Oil rents":{"ro":"Rente petroliere","ar":"الريع النفطي"},"Iraq is highlighted. Every loaded comparison country stays visible in teal. Hover or tap a line for its period and precise value.":{"ro":"Irakul este evidențiat. Toate țările de comparație încărcate rămân vizibile în verde turcoaz. Treci cursorul peste o linie sau atinge-o pentru perioada și valoarea exactă.","ar":"العراق مميز بلون مختلف. تبقى جميع بلدان المقارنة المحمّلة ظاهرة باللون الفيروزي. مرّر المؤشر فوق الخط أو المسه لعرض الفترة والقيمة الدقيقة."},"Does a more complex model help?":{"ro":"Ajută un model mai complex?","ar":"هل يفيد نموذج أكثر تعقيدًا؟"},"I test five methods on the same 24 months, July 2024–June 2026. Each predicts one month ahead. MAE is the average size of the errors; RMSE gives bigger mistakes more weight. Both are in trillion Iraqi dinars.":{"ro":"Testez cinci metode pe aceleași 24 de luni, iulie 2024–iunie 2026. Fiecare prognozează cu o lună înainte. MAE este mărimea medie a erorilor; RMSE acordă greșelilor mari o pondere mai mare. Ambele sunt exprimate în trilioane de dinari irakieni.","ar":"أختبر خمس طرق على الأشهر الـ24 نفسها، من يوليو 2024 إلى يونيو 2026. تتنبأ كل طريقة بالشهر التالي. MAE هو متوسط حجم الأخطاء، بينما يمنح RMSE الأخطاء الكبيرة وزنًا أكبر. كلاهما مقاس بتريليون دينار عراقي."},"How to read the forecast comparison":{"ro":"Cum se citește comparația prognozelor","ar":"كيف تقرأ مقارنة التنبؤات"},"MAE:":{"ro":"MAE:","ar":"MAE:"},"average absolute prediction error. Lower is better.":{"ro":"eroarea absolută medie de prognoză. O valoare mai mică este mai bună.","ar":"متوسط الخطأ المطلق للتنبؤ. القيمة الأقل أفضل."},"RMSE:":{"ro":"RMSE:","ar":"RMSE:"},"prediction error with more weight given to large mistakes. Lower is better.":{"ro":"eroarea de prognoză care acordă mai multă greutate greșelilor mari. O valoare mai mică este mai bună.","ar":"مقياس لخطأ التنبؤ يعطي الأخطاء الكبيرة وزنًا أكبر. القيمة الأقل أفضل."},"Trillion IQD:":{"ro":"Trilioane IQD:","ar":"تريليون دينار عراقي:"},"one trillion Iraqi dinars, at the prices of that period.":{"ro":"un trilion de dinari irakieni, la prețurile perioadei respective.","ar":"تريليون دينار عراقي بأسعار الفترة المعنية."},"95% prediction interval:":{"ro":"Interval de predicție de 95%:","ar":"فاصل تنبؤ بنسبة 95%:"},"the model’s uncertainty range for a future observation, under its assumptions.":{"ro":"intervalul de incertitudine al modelului pentru o observație viitoare, în condițiile ipotezelor sale.","ar":"نطاق عدم اليقين في النموذج لمشاهدة مستقبلية، وفقًا لافتراضاته."},"The table compares all five methods on the same 24 historical months. The chart shows the selected model’s saved July–September 2026 predictions. It does not fit a new model when you change the selection.":{"ro":"Tabelul compară toate cele cinci metode pe aceleași 24 de luni istorice. Graficul arată prognozele salvate ale modelului selectat pentru iulie–septembrie 2026. Schimbarea selecției nu estimează un model nou.","ar":"يقارن الجدول الطرق الخمس على الأشهر التاريخية الـ24 نفسها. يعرض الرسم تنبؤات النموذج المختار المحفوظة ليوليو–سبتمبر 2026. لا تتم ملاءمة نموذج جديد عند تغيير الاختيار."},"My initial monthly revenue forecast comparison":{"ro":"Comparația mea inițială a prognozelor lunare de venituri","ar":"مقارنتي الأولية لتنبؤات الإيرادات الشهرية"},"Method":{"ro":"Metodă","ar":"الطريقة"},"MAE":{"ro":"MAE","ar":"MAE"},"RMSE":{"ro":"RMSE","ar":"RMSE"},"Targets":{"ro":"Luni evaluate","ar":"الأشهر المقيمة"},"Last month":{"ro":"Luna precedentă","ar":"الشهر السابق"},"Same month last year":{"ro":"Aceeași lună anul trecut","ar":"الشهر نفسه من العام السابق"},"AR(1)":{"ro":"AR(1)","ar":"AR(1)"},"LOWEST MAE":{"ro":"CEL MAI MIC MAE","ar":"أقل MAE"},"ARIMA(1,1,1)":{"ro":"ARIMA(1,1,1)","ar":"ARIMA(1,1,1)"},"LOWEST RMSE":{"ro":"CEL MAI MIC RMSE","ar":"أقل RMSE"},"SARIMA(1,0,0)(0,1,1)[12]":{"ro":"SARIMA(1,0,0)(0,1,1)[12]","ar":"SARIMA(1,0,0)(0,1,1)[12]"},"WHAT I FOUND SO FAR":{"ro":"CE AM AFLAT PÂNĂ ACUM","ar":"ما توصلت إليه حتى الآن"},"AR(1) has the lowest MAE. ARIMA(1,1,1) has the lowest RMSE. I still need to check the model assumptions and remaining patterns in the errors before making my final choice.":{"ro":"AR(1) are cel mai mic MAE. ARIMA(1,1,1) are cel mai mic RMSE. Încă trebuie să verific ipotezele modelelor și tiparele rămase în erori înainte de alegerea finală.","ar":"يحقق AR(1) أقل MAE، ويحقق ARIMA(1,1,1) أقل RMSE. ما زلت بحاجة إلى مراجعة افتراضات النماذج والأنماط المتبقية في الأخطاء قبل اختياري النهائي."},"Inspect a fitted method":{"ro":"Examinează o metodă estimată","ar":"افحص نموذجًا تمت ملاءمته"},"These saved predictions use data ending in June 2026 to look at July–September. They are not a fresh forecast made today. The shaded 95% band shows uncertainty under the model's assumptions. So far, I have tested accuracy one month ahead.":{"ro":"Aceste prognoze salvate folosesc date până în iunie 2026 pentru iulie–septembrie. Nu sunt prognoze noi făcute astăzi. Banda umbrită de 95% arată incertitudinea în condițiile ipotezelor modelului. Până acum am testat precizia la un orizont de o lună.","ar":"تستخدم هذه التنبؤات المحفوظة بيانات تنتهي في يونيو 2026 للنظر في يوليو–سبتمبر. وهي ليست تنبؤات جديدة أُعدت اليوم. يعرض الشريط المظلل بنسبة 95% عدم اليقين وفق افتراضات النموذج. اختبرت الدقة حتى الآن لشهر واحد إلى الأمام."},"What if oil prices fall?":{"ro":"Ce se întâmplă dacă scade prețul petrolului?","ar":"ماذا لو انخفضت أسعار النفط؟"},"I use the IMF's April 2026 yearly projections as a starting point. Change the assumptions to see how the budget balance changes.":{"ro":"Folosesc proiecțiile anuale ale FMI din aprilie 2026 ca punct de pornire. Schimbă ipotezele pentru a vedea cum se modifică soldul bugetar.","ar":"أستخدم التوقعات السنوية لصندوق النقد الدولي الصادرة في أبريل 2026 كنقطة بداية. غيّر الافتراضات لترى تغير رصيد الموازنة."},"How to read the budget scenario":{"ro":"Cum se citește scenariul bugetar","ar":"كيف تقرأ سيناريو الموازنة"},"Baseline:":{"ro":"Scenariu de referință:","ar":"المسار المرجعي:"},"the balance calculated from the IMF’s published annual revenue, spending and GDP projections.":{"ro":"soldul calculat din proiecțiile anuale publicate de FMI pentru venituri, cheltuieli și PIB.","ar":"الرصيد المحسوب من توقعات الإيرادات والنفقات والناتج المحلي الإجمالي السنوية المنشورة من صندوق النقد الدولي."},"Scenario:":{"ro":"Scenariu:","ar":"السيناريو:"},"the balance after your price assumption changes the selected share of revenue.":{"ro":"soldul după ce ipoteza ta de preț modifică ponderea selectată a veniturilor.","ar":"الرصيد بعد أن يغير افتراضك للسعر الحصة المحددة من الإيرادات."},"Balance as % of GDP:":{"ro":"Sold ca % din PIB:","ar":"الرصيد كنسبة من الناتج المحلي الإجمالي:"},"revenue minus spending, divided by fixed baseline GDP. Negative values show a deficit; positive values show a surplus.":{"ro":"venituri minus cheltuieli, împărțite la PIB-ul fix al scenariului de referință. Valorile negative indică un deficit; cele pozitive, un excedent.","ar":"الإيرادات ناقص النفقات، مقسومة على الناتج المحلي الإجمالي المرجعي الثابت. القيم السالبة تعني عجزًا والموجبة تعني فائضًا."},"Percentage points:":{"ro":"Puncte procentuale:","ar":"النقاط المئوية:"},"the difference between the two balance percentages, not a percentage change.":{"ro":"diferența dintre cele două procente ale soldului, nu o variație procentuală.","ar":"الفرق بين نسبتي الرصيد، وليس تغيرًا نسبيًا بالمئة."},"The price-sensitive revenue share is an assumption you choose. Spending, export quantities, other revenue, GDP and the exchange rate stay fixed in this calculation.":{"ro":"Ponderea veniturilor sensibile la preț este o ipoteză aleasă de tine. Cheltuielile, cantitățile exportate, alte venituri, PIB-ul și cursul de schimb rămân fixe în acest calcul.","ar":"حصة الإيرادات الحساسة للسعر افتراض تختاره أنت. تبقى النفقات وكميات التصدير والإيرادات الأخرى والناتج المحلي الإجمالي وسعر الصرف ثابتة في هذا الحساب."},"Oil-price change":{"ro":"Schimbarea prețului petrolului","ar":"تغير سعر النفط"},"A negative value assumes a fall in oil prices.":{"ro":"O valoare negativă presupune o scădere a prețului petrolului.","ar":"تفترض القيمة السالبة انخفاض أسعار النفط."},"Assumed price-sensitive revenue share":{"ro":"Pondere presupusă a veniturilor sensibile la preț","ar":"الحصة المفترضة للإيرادات الحساسة للسعر"},"The share of revenue assumed to respond to that price change.":{"ro":"Partea veniturilor presupusă a reacționa la acea schimbare de preț.","ar":"حصة الإيرادات التي نفترض استجابتها لذلك التغير في السعر."},"I keep spending, export quantities, other revenue, GDP and the exchange rate fixed here. I choose the share of revenue that responds to oil prices. This shows what happens under those assumptions; it does not say how likely the scenario is.":{"ro":"Păstrez aici fixe cheltuielile, cantitățile exportate, alte venituri, PIB-ul și cursul de schimb. Aleg ponderea veniturilor care reacționează la prețul petrolului. Calculul arată ce se întâmplă în aceste condiții, nu cât de probabil este scenariul.","ar":"أُبقي النفقات وكميات التصدير والإيرادات الأخرى والناتج المحلي الإجمالي وسعر الصرف ثابتة هنا. أختار حصة الإيرادات التي تتأثر بسعر النفط. يوضح الحساب ما يحدث وفق هذه الافتراضات، ولا يحدد احتمال وقوع السيناريو."},"Download this scenario and its assumptions":{"ro":"Descarcă acest scenariu și ipotezele lui","ar":"نزّل هذا السيناريو وافتراضاته"},"What makes a country comparable?":{"ro":"Ce face o țară comparabilă?","ar":"ما الذي يجعل بلدًا قابلًا للمقارنة؟"},"I compare countries using their 2003–2007 oil rents, real GDP per person and manufacturing. Change how much each feature matters to see how the ranking changes. My calculation uses log GDP per person to reduce the effect of very large income differences.":{"ro":"Compar țările pe baza rentelor petroliere, PIB-ului real pe persoană și industriei prelucrătoare din 2003–2007. Schimbă importanța fiecărei caracteristici pentru a vedea clasamentul. Calculul folosește logaritmul PIB-ului pe persoană pentru a reduce efectul diferențelor foarte mari de venit.","ar":"أقارن البلدان باستخدام الريع النفطي والناتج المحلي الإجمالي الحقيقي للفرد والصناعة التحويلية خلال 2003–2007. غيّر أهمية كل خاصية لترى تغير الترتيب. يستخدم الحساب لوغاريتم الناتج المحلي للفرد لتقليل أثر الفروق الكبيرة جدًا في الدخل."},"How to read the country comparison":{"ro":"Cum se citește comparația între țări","ar":"كيف تقرأ مقارنة البلدان"},"Iraq is the reference, with a distance of zero. Every loaded comparison country is listed. The features come from the 2003–2007 period.":{"ro":"Irakul este reperul, cu distanța zero. Toate țările de comparație încărcate sunt enumerate. Caracteristicile provin din perioada 2003–2007.","ar":"العراق هو البلد المرجعي بمسافة تساوي صفرًا. تُعرض جميع بلدان المقارنة المحمّلة. تأتي الخصائص من فترة 2003–2007."},"Weights:":{"ro":"Ponderi:","ar":"الأوزان:"},"how much each feature matters after the features are put on a common scale. Zero excludes that feature.":{"ro":"importanța fiecărei caracteristici după aducerea lor la o scară comună. Zero exclude acea caracteristică.","ar":"أهمية كل خاصية بعد وضع الخصائص على مقياس مشترك. الصفر يستبعد الخاصية."},"Income:":{"ro":"Venit:","ar":"الدخل:"},"log real GDP per person, which reduces the effect of very large income differences.":{"ro":"logaritmul PIB-ului real pe persoană, care reduce efectul diferențelor foarte mari de venit.","ar":"لوغاريتم الناتج المحلي الإجمالي الحقيقي للفرد، لتقليل أثر فروق الدخل الكبيرة جدًا."},"Distance:":{"ro":"Distanță:","ar":"المسافة:"},"a unitless similarity measure. A lower value means a closer match on the selected features.":{"ro":"o măsură de similaritate fără unitate. O valoare mai mică înseamnă o potrivire mai apropiată pe caracteristicile selectate.","ar":"مقياس تشابه بلا وحدة. تعني القيمة الأقل تشابهًا أكبر في الخصائص المختارة."},"The ranking describes similarity within this country set. It does not establish why economies developed differently.":{"ro":"Clasamentul descrie similaritatea în acest grup de țări. Nu stabilește de ce economiile s-au dezvoltat diferit.","ar":"يصف الترتيب التشابه ضمن هذه المجموعة من البلدان. ولا يحدد أسباب اختلاف تطور اقتصاداتها."},"Oil-rent weight":{"ro":"Ponderea rentelor petroliere","ar":"وزن الريع النفطي"},"Income weight":{"ro":"Ponderea venitului","ar":"وزن الدخل"},"Manufacturing weight":{"ro":"Ponderea industriei prelucrătoare","ar":"وزن الصناعة التحويلية"},"COUNTRY / REFERENCE":{"ro":"ȚARĂ / REPER","ar":"البلد / المرجع"},"DISTANCE · UNITLESS":{"ro":"DISTANȚĂ · FĂRĂ UNITATE","ar":"المسافة · بلا وحدة"},"A lower distance means a closer match on these features, among the countries I have loaded. This does not prove why their economies developed differently. I may add Bahrain after checking its data.":{"ro":"O distanță mai mică indică o potrivire mai apropiată pe aceste caracteristici, între țările încărcate. Nu demonstrează de ce economiile lor s-au dezvoltat diferit. Aș putea adăuga Bahrain după verificarea datelor sale.","ar":"تعني المسافة الأقل تشابهًا أكبر في هذه الخصائص بين البلدان المحمّلة. ولا تثبت سبب اختلاف تطور اقتصاداتها. قد أضيف البحرين بعد التحقق من بياناتها."},"Retry the preview ↻":{"ro":"Reîncearcă previzualizarea ↻","ar":"أعد تحميل المعاينة ↻"},"I use Python to check the inputs, prepare the observations and run the experiments. The interface helps me inspect the results and export their evidence.":{"ro":"Folosesc Python pentru a verifica datele de intrare, a pregăti observațiile și a rula experimentele. Interfața mă ajută să examinez rezultatele și să export dovezile lor.","ar":"أستخدم Python للتحقق من المدخلات وتجهيز المشاهدات وإجراء التجارب. تساعدني الواجهة على فحص النتائج وتصدير الأدلة المرتبطة بها."},"My Python project":{"ro":"Proiectul meu Python","ar":"مشروعي بلغة Python"},"Private repository · access required":{"ro":"Depozit privat · acces necesar","ar":"مستودع خاص · يلزم تصريح بالوصول"},"04 / REAL SOURCES AND CLEAR WINDOWS":{"ro":"04 / SURSE REALE ȘI PERIOADE CLARE","ar":"04 / مصادر موثقة وفترات واضحة"},"02 / REAL SOURCES AND CLEAR WINDOWS":{"ro":"02 / SURSE REALE ȘI PERIOADE CLARE","ar":"02 / مصادر موثقة وفترات واضحة"},"THE DATA COMES FIRST":{"ro":"DATELE VIN PRIMELE","ar":"البيانات أولًا"},"I start with":{"ro":"Încep cu","ar":"أبدأ بفهم"},"the":{"ro":"","ar":""},"new Iraq.":{"ro":"noul Irak.","ar":"العراق الجديد."},"2003 marks the US-led invasion and the fall of Saddam Hussein's regime. I chose this as the starting point for understanding Iraq's economy in the period that followed.":{"ro":"Anul 2003 marchează invazia condusă de SUA și căderea regimului lui Saddam Hussein. L-am ales ca punct de pornire pentru înțelegerea economiei Irakului în perioada care a urmat.","ar":"يمثل عام 2003 الغزو الذي قادته الولايات المتحدة وسقوط نظام صدام حسين. اخترته نقطة بداية لفهم اقتصاد العراق في الفترة التالية."},"01 / DEVELOPMENT":{"ro":"01 / DEZVOLTARE","ar":"01 / التنمية"},"Annual history":{"ro":"Istoric anual","ar":"السجل السنوي"},"Growth, real income per person and manufacturing run through 2025. Oil rents keep their available 2003–2021 window.":{"ro":"Creșterea, producția reală pe persoană și industria prelucrătoare acoperă perioada până în 2025. Rentele petroliere păstrează intervalul disponibil 2003–2021.","ar":"تمتد بيانات النمو والناتج الحقيقي للفرد والصناعة التحويلية حتى عام 2025. يحتفظ الريع النفطي بفترته المتاحة 2003–2021."},"World Bank WDI ↗":{"ro":"Indicatorii WDI ai Băncii Mondiale ↗","ar":"مؤشرات التنمية العالمية للبنك الدولي ↗"},"02 / GOVERNMENT ACCOUNTS":{"ro":"02 / CONTURI GUVERNAMENTALE","ar":"02 / الحسابات الحكومية"},"Monthly fiscal detail":{"ro":"Detalii fiscale lunare","ar":"التفاصيل المالية الشهرية"},"The continuous model uses 2016–June 2026. I preserve cumulative accounts, derive monthly increments and keep the earlier archive separate for review.":{"ro":"Modelul continuu folosește perioada 2016–iunie 2026. Păstrez conturile cumulative, calculez diferențele lunare și mențin separat arhiva anterioară pentru verificare.","ar":"يستخدم النموذج المتصل الفترة من 2016 إلى يونيو 2026. أحتفظ بالحسابات التراكمية وأستخرج الفروق الشهرية وأُبقي الأرشيف الأقدم منفصلًا للمراجعة."},"CBI statistical bulletins ↗":{"ro":"Buletinele statistice ale Băncii Centrale a Irakului ↗","ar":"النشرات الإحصائية للبنك المركزي العراقي ↗"},"03 / FUTURE SCENARIOS":{"ro":"03 / SCENARII VIITOARE","ar":"03 / السيناريوهات المستقبلية"},"A published annual outlook":{"ro":"Perspective anuale publicate","ar":"آفاق سنوية منشورة"},"The IMF April 2026 projections through 2031 provide a separate baseline for sensitivity calculations.":{"ro":"Proiecțiile FMI din aprilie 2026, până în 2031, oferă un scenariu de referință separat pentru calculele de sensibilitate.","ar":"توفر توقعات صندوق النقد الدولي الصادرة في أبريل 2026 حتى عام 2031 مسارًا مرجعيًا مستقلًا لحسابات الحساسية."},"IMF World Economic Outlook ↗":{"ro":"Perspectivele economice mondiale ale FMI ↗","ar":"آفاق الاقتصاد العالمي لصندوق النقد الدولي ↗"},"I keep each measurement at its original frequency. I do not repeat annual GDP twelve times to create monthly observations, and I do not treat a partial year as a completed year.":{"ro":"Păstrez fiecare măsură la frecvența sa originală. Nu repet PIB-ul anual de douăsprezece ori pentru a crea observații lunare și nu tratez un an parțial ca un an complet.","ar":"أحافظ على التواتر الأصلي لكل قياس. لا أكرر الناتج المحلي السنوي اثنتي عشرة مرة لإنشاء مشاهدات شهرية، ولا أتعامل مع السنة الجزئية على أنها سنة مكتملة."},"05 / WHAT I HAVE BUILT":{"ro":"05 / CE AM CONSTRUIT","ar":"05 / ما بنيته"},"A PROGRAM AND A RESEARCH PROCESS":{"ro":"UN PROGRAM ȘI UN PROCES DE CERCETARE","ar":"برنامج ومسار بحثي"},"The working Python application showing its 126-month fiscal dataset and the monthly revenue and spending chart":{"ro":"Aplicația Python funcțională cu setul fiscal de 126 de luni și graficul veniturilor și cheltuielilor lunare","ar":"تطبيق Python الذي يعمل، ويعرض بيانات مالية لـ126 شهرًا ورسم الإيرادات والنفقات الشهرية"},"My actual Streamlit prototype · captured October 2026":{"ro":"Prototipul meu real Streamlit · captură din octombrie 2026","ar":"نموذجي الأولي الفعلي باستخدام Streamlit · لقطة من أكتوبر 2026"},"More than":{"ro":"Mai mult decât","ar":"أكثر من"},"the final chart.":{"ro":"graficul final.","ar":"الرسم النهائي."},"I want to be able to follow a value from its source to the result on screen. That means preserving definitions, checking the calculations and making the analysis reproducible.":{"ro":"Vreau să pot urmări o valoare de la sursă până la rezultatul de pe ecran. Asta înseamnă păstrarea definițiilor, verificarea calculelor și o analiză care poate fi reprodusă.","ar":"أريد تتبع القيمة من مصدرها إلى النتيجة المعروضة. يتطلب ذلك الحفاظ على التعريفات والتحقق من الحسابات وجعل التحليل قابلًا لإعادة الإنتاج."},"A documented data pipeline":{"ro":"Un flux de date documentat","ar":"مسار بيانات موثق"},"Source snapshots, units, gaps, fingerprints and cumulative-to-monthly conversion.":{"ro":"Versiuni salvate ale surselor, unități, lipsuri, amprente digitale și conversie din valori cumulative în valori lunare.","ar":"نسخ محفوظة للمصادر ووحدات وفجوات وبصمات رقمية وتحويل القيم التراكمية إلى قيم شهرية."},"Explainable computations":{"ro":"Calcule explicabile","ar":"حسابات قابلة للتفسير"},"Country distances, chronological forecast tests, visible uncertainty and scenario assumptions.":{"ro":"Distanțe între țări, teste cronologice ale prognozelor, incertitudine vizibilă și ipoteze ale scenariilor.","ar":"مسافات بين البلدان واختبارات زمنية للتنبؤات وعدم يقين ظاهر وافتراضات السيناريوهات."},"A working interface":{"ro":"O interfață funcțională","ar":"واجهة تعمل"},"Controls, source-quality views and exportable results that I can demonstrate and improve.":{"ro":"Comenzi, vizualizări ale calității surselor și rezultate exportabile pe care le pot demonstra și îmbunătăți.","ar":"أدوات تحكم وعروض لجودة المصادر ونتائج قابلة للتصدير والعرض والتحسين."},"06 / LOOK THROUGH THE WORK":{"ro":"06 / DESCOPERĂ LUCRAREA","ar":"06 / تصفح المشروع"},"MY CURRENT MATERIALS":{"ro":"MATERIALELE MELE ACTUALE","ar":"موادي الحالية"},"The work is":{"ro":"Proiectul","ar":"المشروع"},"taking shape.":{"ro":"prinde contur.","ar":"يتبلور."},"01 / PRESENTATION":{"ro":"01 / PREZENTARE","ar":"01 / العرض"},"My thesis pitch":{"ro":"Prezentarea lucrării mele","ar":"عرض مشروع تخرجي"},"I will share the presentation pack when the project is finished.":{"ro":"Voi distribui pachetul de prezentare când proiectul va fi finalizat.","ar":"سأشارك حزمة العرض عندما يكتمل المشروع."},"DOWNLOAD COMING LATER":{"ro":"DESCĂRCARE DISPONIBILĂ ULTERIOR","ar":"التنزيل متاح لاحقًا"},"02 / RESEARCH":{"ro":"02 / CERCETARE","ar":"02 / البحث"},"The plan behind it":{"ro":"Planul din spatele proiectului","ar":"الخطة وراء المشروع"},"My question, data, proposed methods and the work I still need to complete.":{"ro":"Întrebarea mea, datele, metodele propuse și munca pe care mai trebuie să o închei.","ar":"سؤالي وبياناتي وأساليبي المقترحة والعمل الذي ما زلت بحاجة إلى إكماله."},"Read my research plan ↗":{"ro":"Citește planul meu de cercetare ↗","ar":"اقرأ خطة بحثي ↗"},"03 / PYTHON APPLICATION":{"ro":"03 / APLICAȚIE PYTHON","ar":"03 / تطبيق Python"},"The application I am building":{"ro":"Aplicația pe care o construiesc","ar":"التطبيق الذي أبنيه"},"My current Python program, data records, experiments and research notes in the project repository.":{"ro":"Programul meu Python actual, evidențele datelor, experimentele și notele de cercetare din depozitul proiectului.","ar":"برنامج Python الحالي وسجلات البيانات والتجارب والملاحظات البحثية في مستودع المشروع."},"Download the Python project from GitHub ↗":{"ro":"Descarcă proiectul Python de pe GitHub ↗","ar":"نزّل مشروع Python من GitHub ↗"},"The repository is private. GitHub sign-in and repository access are required.":{"ro":"Depozitul este privat. Sunt necesare autentificarea GitHub și accesul la depozit.","ar":"المستودع خاص. يلزم تسجيل الدخول إلى GitHub والحصول على صلاحية الوصول إليه."},"07 / KEEPING THE WORK MOVING":{"ro":"07 / CONTINUAREA PROIECTULUI","ar":"07 / مواصلة العمل"},"MY ROUTE TO July 2027":{"ro":"DRUMUL MEU SPRE IULIE 2027","ar":"طريقي إلى يوليو 2027"},"What I'm":{"ro":"La ce","ar":"ما"},"working on.":{"ro":"lucrez acum.","ar":"أعمل عليه."},"My coordinator and provisional title":{"ro":"Coordonatorul meu și titlul provizoriu","ar":"المشرف والعنوان الحالي"},"Professor Uscatu has agreed to coordinate my thesis. I have chosen a title that brings together my study of Iraq and the economic analysis system I want to keep developing. I will confirm the title and final scope with him.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Am ales un titlu care reunește studiul Irakului și sistemul de analiză economică pe care vreau să îl dezvolt în continuare. Voi confirma împreună cu el titlul și delimitarea finală.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. اخترت عنوانًا يجمع دراسة العراق ونظام التحليل الاقتصادي الذي أريد مواصلة تطويره. سأؤكد معه العنوان والنطاق النهائيين."},"A place to keep the work together":{"ro":"Un loc pentru întregul proiect","ar":"مكان يجمع العمل"},"I have organized the program, data, research and writing into one private repository, with this page as a way to share the project as it develops.":{"ro":"Am organizat programul, datele, cercetarea și redactarea într-un singur depozit privat. Această pagină îmi permite să prezint evoluția proiectului.","ar":"نظمت البرنامج والبيانات والبحث والكتابة في مستودع خاص واحد، وتتيح لي هذه الصفحة مشاركة المشروع أثناء تطوره."},"Moving the fiscal experiment to monthly data":{"ro":"Trecerea experimentului fiscal la date lunare","ar":"نقل التجربة المالية إلى البيانات الشهرية"},"After checking the archived CBI tables, I prepared a continuous 126-month fiscal core and tested five forecasting methods on 24 shared targets.":{"ro":"După verificarea tabelelor CBI arhivate, am pregătit un nucleu fiscal continuu de 126 de luni și am testat cinci metode de prognoză pe 24 de luni comune.","ar":"بعد التحقق من جداول البنك المركزي العراقي المؤرشفة، أعددت سلسلة مالية متصلة من 126 شهرًا واختبرت خمس طرق للتنبؤ على 24 شهرًا مشتركًا."},"Starting with evidence":{"ro":"Pornind de la dovezi","ar":"البداية بالأدلة"},"I checked the available datasets before choosing the direction, prepared the annual development history and started the first Python prototype.":{"ro":"Am verificat seturile de date disponibile înainte să aleg direcția, am pregătit istoricul anual al dezvoltării și am început primul prototip Python.","ar":"راجعت مجموعات البيانات المتاحة قبل اختيار الاتجاه، وجهزت السجل السنوي للتنمية وبدأت أول نموذج أولي بلغة Python."},"NEXT STEPS":{"ro":"PAȘII URMĂTORI","ar":"الخطوات التالية"},"There is still":{"ro":"Mai sunt","ar":"ما زال هناك"},"work to do.":{"ro":"lucruri de făcut.","ar":"عمل لإنجازه."},"Agree a focused thesis question and scope with my professors.":{"ro":"Să stabilesc cu profesorii o întrebare și o delimitare clară a lucrării.","ar":"الاتفاق مع أساتذتي على سؤال محدد ونطاق واضح لمشروع التخرج."},"Review the statistical diagnostics, source adjustments and final evaluation plan.":{"ro":"Să revizuiesc diagnosticele statistice, ajustările surselor și planul final de evaluare.","ar":"مراجعة الفحوص الإحصائية وتعديلات المصادر وخطة التقييم النهائية."},"Improve the fiscal database, experiment records and application performance.":{"ro":"Să îmbunătățesc baza de date fiscală, evidențele experimentelor și performanța aplicației.","ar":"تحسين قاعدة البيانات المالية وسجلات التجارب وأداء التطبيق."},"Investigate a comparable breakdown of executed spending where the data support it.":{"ro":"Să investighez o defalcare comparabilă a cheltuielilor executate, unde datele permit.","ar":"دراسة توزيع قابل للمقارنة للإنفاق المنفذ حيث تسمح البيانات."},"Write the thesis, evaluate the application and prepare my defence.":{"ro":"Să redactez lucrarea, să evaluez aplicația și să pregătesc susținerea.","ar":"كتابة البحث وتقييم التطبيق والتحضير للمناقشة."},"I will refine the question, methods and software contribution with my professors' advice.":{"ro":"Voi rafina întrebarea, metodele și contribuția software cu sfaturile profesorilor mei.","ar":"سأراجع السؤال والأساليب والإسهام البرمجي مستفيدًا من نصائح أساتذتي."},"WHERE I WANT TO TAKE IT":{"ro":"UNDE VREAU SĂ AJUNG","ar":"إلى أين أريد الوصول"},"I am starting with Iraq.":{"ro":"Încep cu Irakul.","ar":"أبدأ بالعراق."},"I want the program to go further.":{"ro":"Vreau ca programul să meargă mai departe.","ar":"وأريد للبرنامج أن يتوسع."},"Eventually, I want this program to be useful for any country, with a clear way to import different datasets. For now, I am building and testing it around the Iraqi data I understand and care about. Once that works well, I want to make the import process, country choices and analysis easier to adapt. Different datasets will still need their own checks and suitable methods; that wider version is something I want to develop after the core thesis.":{"ro":"În timp, vreau ca acest program să fie util pentru orice țară, cu o modalitate clară de a importa seturi de date diferite. Deocamdată îl construiesc și îl testez pe datele irakiene pe care le înțeleg și care contează pentru mine. După ce această parte funcționează bine, vreau să fac importul, alegerea țărilor și analiza mai ușor de adaptat. Fiecare set de date va avea în continuare nevoie de verificări proprii și metode potrivite; versiunea mai largă este un obiectiv pentru după nucleul lucrării de licență.","ar":"أريد في النهاية أن يكون هذا البرنامج مفيدًا لأي بلد، مع طريقة واضحة لاستيراد مجموعات بيانات مختلفة. أبنيه وأختبره الآن على البيانات العراقية التي أفهمها وأهتم بها. بعد أن يعمل ذلك جيدًا، أريد تسهيل تكييف الاستيراد واختيار البلدان والتحليل. ستظل كل مجموعة بيانات بحاجة إلى فحوصها وأساليبها المناسبة؛ وأريد تطوير هذه النسخة الأوسع بعد إكمال أساس مشروع التخرج."},"A boat and water buffalo in the Iraqi marshes, photographed by Taisir Mahdi":{"ro":"O barcă și bivoli de apă în mlaștinile irakiene, fotografiate de Taisir Mahdi","ar":"قارب وجواميس في الأهوار العراقية، بعدسة Taisir Mahdi"},"THE REASON I KEEP COMING BACK TO THIS":{"ro":"DE CE REVIN MEREU LA ACEST PROIECT","ar":"سبب عودتي إلى هذا المشروع"},"A place I know.":{"ro":"Un loc pe care îl cunosc.","ar":"مكان أعرفه."},"An economy I want":{"ro":"O economie pe care vreau","ar":"واقتصاد أريد"},"to understand.":{"ro":"să o înțeleg.","ar":"أن أفهمه."},"I want this project to help me ask better questions, become a better programmer and learn statistics I can keep building on.":{"ro":"Vreau ca acest proiect să mă ajute să pun întrebări mai bune, să devin un programator mai bun și să învăț statistică pe care pot continua să o dezvolt.","ar":"أريد أن يساعدني هذا المشروع على طرح أسئلة أفضل وتطوير مهاراتي البرمجية وتعلم إحصاء يمكنني البناء عليه."},"Talk to me about the project":{"ro":"Discută cu mine despre proiect","ar":"تحدث معي عن المشروع"},"NOORULDEEN AL SAMMARRAIE":{"ro":"NOORULDEEN AL SAMMARRAIE","ar":"نورالدين السامرائي"},"My thesis · work in progress":{"ro":"Lucrarea mea · în dezvoltare","ar":"مشروع تخرجي · قيد التطوير"},"Published 2026-10-13 · Monthly fiscal source window ends June 2026 · Source snapshots: 10 and 12 October 2026":{"ro":"Publicat la 2026-10-13 · Datele fiscale lunare se încheie în iunie 2026 · Surse salvate: 10 și 12 octombrie 2026","ar":"نُشر في 2026-10-13 · تنتهي بيانات المالية الشهرية في يونيو 2026 · نسخ المصادر: 10 و12 أكتوبر 2026"},"Sources and image credits":{"ro":"Surse și credite pentru imagini","ar":"المصادر وحقوق الصور"},"Development data: World Bank WDI, CC BY 4.0. Scenario baseline: IMF WEO, April 2026. Model results are my saved exploratory calculations using documented CBI accounts. Source snapshots remain labelled.":{"ro":"Date de dezvoltare: WDI, Banca Mondială, CC BY 4.0. Scenariu de referință: WEO, FMI, aprilie 2026. Rezultatele modelelor sunt calculele mele exploratorii salvate, folosind conturile CBI documentate. Versiunile surselor rămân etichetate.","ar":"بيانات التنمية: مؤشرات البنك الدولي، CC BY 4.0. المسار المرجعي: آفاق الاقتصاد العالمي لصندوق النقد الدولي، أبريل 2026. نتائج النماذج هي حساباتي الاستكشافية المحفوظة باستخدام حسابات موثقة للبنك المركزي العراقي. تبقى نسخ المصادر مؤرخة بوضوح."},"Historical starting point:":{"ro":"Punct de pornire istoric:","ar":"نقطة البداية التاريخية:"},"US Office of the Historian":{"ro":"Biroul Istoricului al SUA","ar":"مكتب المؤرخ الأمريكي"},"and":{"ro":"și","ar":"و"},"UN Secretary-General, December 2003":{"ro":"Secretarul General al ONU, decembrie 2003","ar":"الأمين العام للأمم المتحدة، ديسمبر 2003"},". My chosen period does not by itself establish the causes of later economic outcomes.":{"ro":". Perioada aleasă nu stabilește singură cauzele rezultatelor economice ulterioare.","ar":". لا تحدد الفترة التي اخترتها وحدها أسباب النتائج الاقتصادية اللاحقة."},"My Iraq illustration is a decorative drawing, not a data chart. Samarra:":{"ro":"Ilustrația Irakului este un desen decorativ, nu un grafic de date. Samarra:","ar":"رسم العراق توضيح زخرفي وليس رسمًا بيانيًا للبيانات. سامراء:"},"David Stanley":{"ro":"David Stanley","ar":"David Stanley"},"CC BY 2.0":{"ro":"CC BY 2.0","ar":"CC BY 2.0"},". Iraqi marshes:":{"ro":". Mlaștinile irakiene:","ar":". الأهوار العراقية:"},"Taisir Mahdi":{"ro":"Taisir Mahdi","ar":"Taisir Mahdi"},"CC BY-SA 4.0":{"ro":"CC BY-SA 4.0","ar":"CC BY-SA 4.0"},". Photos are displayed with proportional crops; original pixels are preserved.":{"ro":". Fotografiile sunt afișate cu decupaje proporționale; pixelii originali sunt păstrați.","ar":". تُعرض الصور بقص متناسب مع الحفاظ على البكسلات الأصلية."},"My thesis question, data, methods and next steps for the Iraq Economic Observatory.":{"ro":"Întrebarea, datele, metodele și pașii următori ai lucrării mele despre Observatorul Economic al Irakului.","ar":"سؤال مشروع تخرجي وبياناته وأساليبه وخطواته القادمة في المرصد الاقتصادي العراقي."},"My thesis research plan | Nooruldeen":{"ro":"Planul lucrării mele de licență | Nooruldeen","ar":"خطة بحث مشروع تخرجي | نورالدين"},"Skip to the research plan":{"ro":"Sari la planul de cercetare","ar":"انتقل إلى خطة البحث"},"Back to my project ↗":{"ro":"Înapoi la proiectul meu ↗","ar":"العودة إلى مشروعي ↗"},"MY THESIS / RESEARCH PLAN":{"ro":"LUCRAREA MEA / PLAN DE CERCETARE","ar":"مشروع تخرجي / خطة البحث"},"ON THIS PAGE":{"ro":"PE ACEASTĂ PAGINĂ","ar":"في هذه الصفحة"},"Research plan sections":{"ro":"Secțiunile planului de cercetare","ar":"أقسام خطة البحث"},"The questions behind the project":{"ro":"Întrebările din spatele proiectului","ar":"الأسئلة وراء المشروع"},"Why I start with Iraq after 2003":{"ro":"De ce încep cu Irakul de după 2003","ar":"لماذا أبدأ بالعراق بعد عام 2003"},"How I prepare the monthly figures":{"ro":"Cum pregătesc valorile lunare","ar":"كيف أجهز الأرقام الشهرية"},"What I have tested so far":{"ro":"Ce am testat până acum","ar":"ما اختبرته حتى الآن"},"What the budget scenarios mean":{"ro":"Ce înseamnă scenariile bugetare","ar":"ماذا تعني سيناريوهات الموازنة"},"What the application does":{"ro":"Ce face aplicația","ar":"ما يقدمه التطبيق"},"Where I want to take the program":{"ro":"Unde vreau să duc programul","ar":"إلى أين أريد تطوير البرنامج"},"Why I would value my professors' guidance":{"ro":"De ce apreciez îndrumarea profesorilor","ar":"لماذا أقدّر توجيه أساتذتي"},"What I want to improve next":{"ro":"Ce vreau să îmbunătățesc în continuare","ar":"ما أريد تحسينه لاحقًا"},"Where the evidence comes from":{"ro":"De unde provin dovezile","ar":"مصادر الأدلة"},"What I want to build and understand":{"ro":"Ce vreau să construiesc și să înțeleg","ar":"ما أريد بناءه وفهمه"},"I grew up in Iraq, and I have always wanted to understand its economy better. Iraq has valuable oil resources, but having those resources has not made development straightforward. I want to look at the numbers, understand what they can tell me, and build a Python application that helps me explore the questions properly.":{"ro":"Am crescut în Irak și mi-am dorit mereu să îi înțeleg mai bine economia. Irakul are resurse petroliere valoroase, dar acestea nu au făcut dezvoltarea simplă. Vreau să examinez cifrele, să înțeleg ce îmi pot spune și să construiesc o aplicație Python care mă ajută să explorez corect întrebările.","ar":"نشأت في العراق، وطالما أردت فهم اقتصاده بشكل أفضل. يمتلك العراق موارد نفطية قيّمة، لكنها لم تجعل التنمية بسيطة. أريد قراءة الأرقام وفهم ما يمكن أن تخبرني به وبناء تطبيق Python يساعدني على استكشاف الأسئلة بطريقة سليمة."},"My provisional thesis title is":{"ro":"Titlul meu provizoriu este","ar":"عنوان مشروع تخرجي الحالي هو"},". I have chosen this title for now and will confirm it with Professor Uscatu before treating it as official. I am studying Economic Informatics at ASE Bucharest, and I plan to defend in July 2027.":{"ro":". Am ales acest titlu pentru moment și îl voi confirma cu profesorul Uscatu înainte să îl consider oficial. Studiez Informatică Economică la ASE București și îmi propun să susțin lucrarea în iulie 2027.","ar":". اخترت هذا العنوان حاليًا وسأؤكده مع الأستاذ Uscatu قبل اعتباره رسميًا. أدرس المعلوماتية الاقتصادية في أكاديمية بوخارست للدراسات الاقتصادية، وأخطط للمناقشة في يوليو 2027."},"Professor Uscatu has agreed to coordinate my thesis. I will discuss the final question and scope with him. Iraq gives the study its personal purpose, while the analysis system is something I want to develop further and eventually adapt to other countries and suitable datasets.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Voi discuta cu el întrebarea și delimitarea finală. Irakul dă studiului sensul personal, iar sistemul de analiză este un proiect pe care vreau să îl dezvolt în continuare și, în timp, să îl adaptez altor țări și seturi de date potrivite.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. سأناقش معه السؤال والنطاق النهائيين. يمنح العراق الدراسة معناها الشخصي، بينما أريد مواصلة تطوير نظام التحليل وتكييفه لاحقًا لبلدان أخرى ومجموعات بيانات مناسبة."},"How has Iraq's economy changed since 2003? How much does the government rely on oil-related income? What happens when revenue falls but spending does not fall with it? Can monthly data help me make useful short-term forecasts?":{"ro":"Cum s-a schimbat economia Irakului din 2003? Cât de mult depinde guvernul de veniturile legate de petrol? Ce se întâmplă când veniturile scad, dar cheltuielile nu scad odată cu ele? Pot datele lunare să mă ajute să fac prognoze utile pe termen scurt?","ar":"كيف تغير اقتصاد العراق منذ عام 2003؟ إلى أي مدى تعتمد الحكومة على الدخل المرتبط بالنفط؟ ماذا يحدث عندما تنخفض الإيرادات ولا تنخفض معها النفقات؟ هل تساعدني البيانات الشهرية على إعداد تنبؤات مفيدة على المدى القصير؟"},"I also want to understand why Iraq's development has followed a different path from countries such as the UAE and Saudi Arabia. Where did public spending go, and how much helped build a more diverse economy? These are questions I want to investigate. A few charts or a country ranking cannot answer them on their own.":{"ro":"Vreau să înțeleg și de ce dezvoltarea Irakului a urmat un alt drum decât în țări precum Emiratele Arabe Unite și Arabia Saudită. Unde s-au dus cheltuielile publice și cât au ajutat la construirea unei economii mai diversificate? Sunt întrebări de investigat. Câteva grafice sau un clasament al țărilor nu le pot răspunde singure.","ar":"أريد أيضًا فهم سبب اختلاف مسار التنمية في العراق عن بلدان مثل الإمارات العربية المتحدة والسعودية. أين ذهب الإنفاق العام، وكم ساهم في بناء اقتصاد أكثر تنوعًا؟ هذه أسئلة أريد دراستها. لا تستطيع بعض الرسوم أو ترتيب البلدان الإجابة عنها بمفردها."},"I do not want to begin with a conclusion and then find numbers to support it. For example, Iraq's budget has not been in deficit every year. I need to check what happened, when it happened, and what the available evidence actually supports.":{"ro":"Nu vreau să pornesc de la o concluzie și apoi să caut cifre care să o susțină. De exemplu, bugetul Irakului nu a fost în deficit în fiecare an. Trebuie să verific ce s-a întâmplat, când și ce susțin de fapt dovezile disponibile.","ar":"لا أريد البدء باستنتاج ثم البحث عن أرقام تدعمه. فمثلًا، لم تكن موازنة العراق في عجز كل عام. أحتاج إلى التحقق مما حدث ومتى حدث وما تدعمه الأدلة المتاحة فعلًا."},"I chose 2003 because it marks the US-led invasion and the fall of Saddam Hussein's regime. I want to understand the economy in the period that followed, without assuming that one event explains every later outcome.":{"ro":"Am ales anul 2003 deoarece marchează invazia condusă de SUA și căderea regimului lui Saddam Hussein. Vreau să înțeleg economia în perioada următoare, fără să presupun că un singur eveniment explică toate rezultatele ulterioare.","ar":"اخترت عام 2003 لأنه يمثل الغزو الذي قادته الولايات المتحدة وسقوط نظام صدام حسين. أريد فهم الاقتصاد في الفترة التالية دون افتراض أن حدثًا واحدًا يفسر جميع النتائج اللاحقة."},"I use two parts of the data together. The yearly data gives me the longer development picture from 2003. The monthly government accounts let me look more closely at revenue, spending and short-term changes.":{"ro":"Folosesc împreună două părți ale datelor. Datele anuale oferă imaginea dezvoltării pe termen lung din 2003. Conturile guvernamentale lunare îmi permit să examinez mai atent veniturile, cheltuielile și schimbările pe termen scurt.","ar":"أستخدم جزأين من البيانات معًا. تمنحني البيانات السنوية صورة التنمية الأطول منذ عام 2003، وتتيح الحسابات الحكومية الشهرية فحص الإيرادات والنفقات والتغيرات القصيرة الأجل بتفصيل أكبر."},"The yearly figures for growth, real GDP per person and manufacturing run through 2025. Real GDP per person is a measure of economic output per person, adjusted for price changes. It is not the same as the income of a typical household. The oil-rent figures are available through 2021. They estimate the value of oil production after production costs; they are not government oil revenue.":{"ro":"Valorile anuale pentru creștere, PIB real pe persoană și industria prelucrătoare merg până în 2025. PIB-ul real pe persoană măsoară producția economică pe persoană, ajustată pentru schimbările de preț. Nu este venitul unei gospodării obișnuite. Datele privind rentele petroliere sunt disponibile până în 2021. Ele estimează valoarea producției petroliere după costurile de producție; nu sunt veniturile petroliere ale guvernului.","ar":"تمتد الأرقام السنوية للنمو والناتج المحلي الإجمالي الحقيقي للفرد والصناعة التحويلية حتى عام 2025. يقيس الناتج الحقيقي للفرد الإنتاج الاقتصادي للفرد بعد تعديل تغيرات الأسعار، وليس دخل الأسرة المعتادة. تتوفر بيانات الريع النفطي حتى عام 2021، وتقدر قيمة إنتاج النفط بعد تكاليف الإنتاج؛ ولا تمثل الإيرادات النفطية الحكومية."},"My consistent monthly forecasting dataset runs from January 2016 to June 2026: 126 months. I also have an earlier archive starting in 2008, but some years have changes in coverage or accounting adjustments that need more checking. That is why I am keeping the reliable modelling window separate for now.":{"ro":"Setul meu lunar consecvent pentru prognoză acoperă ianuarie 2016–iunie 2026: 126 de luni. Am și o arhivă mai veche, din 2008, dar unele perioade prezintă schimbări de acoperire sau ajustări contabile care trebuie verificate. De aceea păstrez deocamdată separat intervalul fiabil pentru modelare.","ar":"تغطي مجموعة التنبؤ الشهرية المتسقة يناير 2016–يونيو 2026، أي 126 شهرًا. لدي أيضًا أرشيف أقدم يبدأ في 2008، لكن بعض السنوات تتضمن تغيرات في التغطية أو تعديلات محاسبية تحتاج إلى مزيد من الفحص. لذلك أُبقي فترة النمذجة الموثوقة منفصلة حاليًا."},"Both frequencies can belong in the same thesis. I keep yearly figures yearly and monthly figures monthly. I do not turn one annual GDP value into twelve observations. I also keep January–June 2026 separate from a complete year.":{"ro":"Ambele frecvențe pot fi folosite în aceeași lucrare. Păstrez datele anuale anuale și pe cele lunare lunare. Nu transform o valoare anuală a PIB-ului în douăsprezece observații. Păstrez separat și ianuarie–iunie 2026 față de un an complet.","ar":"يمكن استخدام التواترين في مشروع واحد. أُبقي الأرقام السنوية سنوية والشهرية شهرية. لا أحول قيمة سنوية واحدة للناتج المحلي إلى اثنتي عشرة مشاهدة. وأميز كذلك يناير–يونيو 2026 عن سنة مكتملة."},"The Central Bank of Iraq tables report running totals within each year. A February value includes January and February together. To get February's own amount, I subtract January's total. For March, I subtract February's total, and so on. January starts a new year, so it uses its own reported amount.":{"ro":"Tabelele Băncii Centrale a Irakului raportează totaluri cumulative în fiecare an. Valoarea din februarie include ianuarie și februarie împreună. Pentru suma proprie lunii februarie scad totalul din ianuarie. Pentru martie scad totalul din februarie, și așa mai departe. Ianuarie începe un an nou, deci folosește suma sa raportată.","ar":"تُبلغ جداول البنك المركزي العراقي عن مجاميع تراكمية داخل كل سنة. تشمل قيمة فبراير شهري يناير وفبراير معًا. للحصول على مبلغ فبراير وحده، أطرح مجموع يناير. وفي مارس أطرح مجموع فبراير، وهكذا. يبدأ يناير سنة جديدة، لذلك تُستخدم قيمته المعلنة مباشرة."},"My code checks that these monthly amounts add back to the yearly total and that revenue minus spending equals the balance. It keeps the original values, source links, units and warnings so that I can trace a result back to its source.":{"ro":"Codul verifică dacă sumele lunare reconstruiesc totalul anual și dacă veniturile minus cheltuielile sunt egale cu soldul. Păstrează valorile originale, linkurile surselor, unitățile și avertismentele, astfel încât pot urmări un rezultat până la sursă.","ar":"يتحقق الكود من أن جمع المبالغ الشهرية يعيد المجموع السنوي، وأن الإيرادات ناقص النفقات تساوي الرصيد. ويحفظ القيم الأصلية وروابط المصادر والوحدات والتنبيهات لتتبع النتيجة إلى مصدرها."},"Some differences can reflect a correction to the accounts. I keep those visible. For example, one oil-and-mineral revenue difference in October 2019 is negative. I need to understand the accounting issue before treating it as ordinary economic behaviour.":{"ro":"Unele diferențe pot reflecta corecții ale conturilor. Le păstrez vizibile. De exemplu, o diferență a veniturilor din petrol și minerale în octombrie 2019 este negativă. Trebuie să înțeleg problema contabilă înainte să o tratez ca pe un comportament economic obișnuit.","ar":"قد تعكس بعض الفروق تصحيحًا للحسابات، وأُبقيها ظاهرة. مثلًا، أحد فروق إيرادات النفط والمعادن في أكتوبر 2019 سالب. أحتاج إلى فهم المشكلة المحاسبية قبل التعامل معها كسلوك اقتصادي عادي."},"My first forecasting experiment asks a focused question: can a model predict next month's reported government revenue better than a simple guess?":{"ro":"Primul experiment de prognoză pune o întrebare precisă: poate un model să anticipeze veniturile guvernamentale raportate pentru luna următoare mai bine decât o estimare simplă?","ar":"تطرح تجربتي الأولى للتنبؤ سؤالًا محددًا: هل يستطيع النموذج توقع الإيرادات الحكومية المعلنة للشهر التالي أفضل من تقدير بسيط؟"},"I start with two simple comparisons: use last month's revenue, or use revenue from the same month a year earlier. I then test AR(1), ARIMA and seasonal ARIMA. AR(1) uses the previous month's level; ARIMA can model changes and patterns in forecast errors; seasonal ARIMA also includes a yearly pattern in the monthly series. These are fixed starting models, not a final choice.":{"ro":"Încep cu două repere simple: veniturile lunii precedente sau cele din aceeași lună a anului anterior. Apoi testez AR(1), ARIMA și ARIMA sezonier. AR(1) folosește nivelul lunii precedente; ARIMA poate modela variații și tipare ale erorilor; ARIMA sezonier include și un tipar anual în seria lunară. Acestea sunt modele inițiale fixe, nu alegerea finală.","ar":"أبدأ بمرجعين بسيطين: إيرادات الشهر السابق أو إيرادات الشهر نفسه من السنة الماضية. ثم أختبر AR(1) وARIMA وARIMA الموسمي. يستخدم AR(1) مستوى الشهر السابق؛ ويمكن لـARIMA نمذجة التغيرات وأنماط أخطاء التنبؤ؛ ويضيف ARIMA الموسمي نمطًا سنويًا إلى السلسلة الشهرية. هذه نماذج أولية ثابتة وليست اختيارًا نهائيًا."},"All five methods predict the same 24 months, from July 2024 to June 2026. For each prediction, the model only gets the earlier fiscal observations. I start with 102 training months. The data comes from the saved, revised source tables, so this is a historical test rather than a reconstruction of exactly what someone knew at each publication date.":{"ro":"Toate cele cinci metode prognozează aceleași 24 de luni, iulie 2024–iunie 2026. Pentru fiecare prognoză, modelul primește doar observațiile fiscale anterioare. Încep cu 102 luni de antrenare. Datele provin din tabelele salvate și revizuite, deci acesta este un test istoric, nu o reconstrucție exactă a informațiilor cunoscute la fiecare dată de publicare.","ar":"تتنبأ الطرق الخمس بالأشهر الـ24 نفسها، من يوليو 2024 إلى يونيو 2026. يحصل النموذج في كل تنبؤ على المشاهدات المالية السابقة فقط. أبدأ بـ102 شهرًا للتدريب. تأتي البيانات من جداول محفوظة ومراجعة، لذا فهذا اختبار تاريخي وليس إعادة بناء دقيقة لما كان معروفًا في كل تاريخ نشر."},"I compare how far each prediction was from the reported result.":{"ro":"Compar distanța dintre fiecare prognoză și rezultatul raportat.","ar":"أقارن مقدار الفرق بين كل تنبؤ والنتيجة المعلنة."},"is the average size of the errors.":{"ro":"reprezintă mărimea medie a erorilor.","ar":"هو متوسط حجم الأخطاء."},"gives larger mistakes more weight. In this first test, AR(1) has the lowest MAE and ARIMA has the lowest RMSE. The seasonal model performs worse. A more complicated model has not automatically helped.":{"ro":"acordă greșelilor mari o pondere mai mare. În acest prim test, AR(1) are cel mai mic MAE, iar ARIMA cel mai mic RMSE. Modelul sezonier are rezultate mai slabe. Un model mai complex nu a ajutat automat.","ar":"يعطي الأخطاء الكبيرة وزنًا أكبر. في هذا الاختبار الأول، يحقق AR(1) أقل MAE ويحقق ARIMA أقل RMSE. أداء النموذج الموسمي أضعف. لم يؤدِ التعقيد الأكبر تلقائيًا إلى تحسن."},"I have not chosen the final model. I still need to check the remaining patterns in its errors, unusual months and changes in the series. The shaded 95% prediction band shows uncertainty under the model's assumptions. It is not a guarantee. The saved July–September 2026 predictions use data ending in June; they are not a fresh forecast made today.":{"ro":"Nu am ales modelul final. Mai trebuie să verific tiparele rămase în erori, lunile neobișnuite și schimbările din serie. Banda de predicție de 95% arată incertitudinea în condițiile ipotezelor modelului. Nu este o garanție. Prognozele salvate pentru iulie–septembrie 2026 folosesc date până în iunie; nu sunt prognoze noi făcute astăzi.","ar":"لم أختر النموذج النهائي. ما زلت بحاجة إلى فحص الأنماط المتبقية في الأخطاء والأشهر غير المعتادة وتغيرات السلسلة. يعرض شريط التنبؤ بنسبة 95% عدم اليقين وفق افتراضات النموذج، وليس ضمانًا. تستخدم تنبؤات يوليو–سبتمبر 2026 المحفوظة بيانات تنتهي في يونيو؛ وليست تنبؤات جديدة أُعدت اليوم."},"I use the IMF's April 2026 projections through 2031 as a separate yearly starting point. The application lets me change an assumption, such as a 10% fall in oil prices, and calculate how the budget balance changes.":{"ro":"Folosesc proiecțiile FMI din aprilie 2026, până în 2031, ca punct de pornire anual separat. Aplicația îmi permite să schimb o ipoteză, cum ar fi scăderea cu 10% a prețului petrolului, și să calculez modificarea soldului bugetar.","ar":"أستخدم توقعات صندوق النقد الدولي الصادرة في أبريل 2026 حتى عام 2031 كنقطة بداية سنوية مستقلة. يتيح لي التطبيق تغيير افتراض، مثل انخفاض سعر النفط بنسبة 10%، وحساب تغير رصيد الموازنة."},"This asks":{"ro":"Acest calcul întreabă","ar":"يسأل هذا الحساب"},"what would happen under these assumptions":{"ro":"ce s-ar întâmpla în aceste condiții","ar":"ما الذي سيحدث وفق هذه الافتراضات"},", rather than saying what will happen. In the simple price scenario, I keep spending, export quantities, other revenue, GDP and the exchange rate fixed. I choose how much revenue is assumed to respond to the price change. That share is visible and adjustable.":{"ro":", fără să afirme ce se va întâmpla. În scenariul simplu de preț păstrez fixe cheltuielile, cantitățile exportate, alte venituri, PIB-ul și cursul de schimb. Aleg cât din venituri se presupune că reacționează la preț. Ponderea este vizibilă și ajustabilă.","ar":"، دون الجزم بما سيحدث. في سيناريو السعر البسيط، أُبقي النفقات وكميات التصدير والإيرادات الأخرى والناتج المحلي الإجمالي وسعر الصرف ثابتة. أختار مقدار الإيرادات المفترض استجابتها لتغير السعر، وهذه الحصة ظاهرة وقابلة للتعديل."},"The result helps me see how sensitive the budget is to the assumptions. It does not include every government response or economic effect, and it does not assign a probability to the scenario.":{"ro":"Rezultatul mă ajută să văd sensibilitatea bugetului la ipoteze. Nu include toate reacțiile guvernului sau efectele economice și nu atribuie o probabilitate scenariului.","ar":"تساعدني النتيجة على رؤية حساسية الموازنة للافتراضات. لا تشمل كل الاستجابات الحكومية أو الآثار الاقتصادية، ولا تعطي احتمالًا للسيناريو."},"My Python application brings the sources, calculations and results together. I can explore the yearly history, inspect monthly accounts, compare forecast errors, see prediction uncertainty and export results. I can also compare countries using oil rents, real output per person and manufacturing, then change how much weight each feature gets.":{"ro":"Aplicația mea Python reunește sursele, calculele și rezultatele. Pot explora istoricul anual, inspecta conturile lunare, compara erorile prognozelor, vedea incertitudinea și exporta rezultatele. Pot și compara țările pe baza rentelor petroliere, producției reale pe persoană și industriei prelucrătoare, apoi schimba ponderea fiecărei caracteristici.","ar":"يجمع تطبيق Python المصادر والحسابات والنتائج. أستطيع استكشاف السجل السنوي وفحص الحسابات الشهرية ومقارنة أخطاء التنبؤ ورؤية عدم اليقين وتصدير النتائج. كما أستطيع مقارنة البلدان وفق الريع النفطي والناتج الحقيقي للفرد والصناعة التحويلية، ثم تغيير وزن كل خاصية."},"Those country comparisons show measured similarity within my selected set. They do not prove why one country developed differently from another. I want to use them as a starting point for better questions and a closer reading of the evidence.":{"ro":"Comparațiile arată similaritatea măsurată în grupul ales. Nu demonstrează de ce o țară s-a dezvoltat diferit de alta. Vreau să le folosesc ca punct de pornire pentru întrebări mai bune și o citire mai atentă a dovezilor.","ar":"توضح مقارنات البلدان التشابه المقاس ضمن المجموعة المختارة. ولا تثبت سبب اختلاف تطور بلد عن آخر. أريد استخدامها بداية لأسئلة أفضل وقراءة أعمق للأدلة."},"The website has a lighter browser preview of the saved results. It can redraw the charts, change comparison weights and recalculate the budget scenario. It does not run new Python model fits. The complete Streamlit application and its code stay in my private GitHub repository while I develop the project.":{"ro":"Site-ul are o previzualizare mai ușoară, în browser, a rezultatelor salvate. Poate redesena graficele, schimba ponderile de comparație și recalcula scenariul bugetar. Nu estimează noi modele Python. Aplicația completă Streamlit și codul său rămân în depozitul meu GitHub privat în timpul dezvoltării.","ar":"يقدم الموقع معاينة أخف للنتائج المحفوظة في المتصفح. يمكنها إعادة رسم المخططات وتغيير أوزان المقارنة وإعادة حساب سيناريو الموازنة. ولا تُجري ملاءمة جديدة لنماذج Python. يبقى تطبيق Streamlit الكامل وكوده في مستودع GitHub الخاص أثناء تطوير المشروع."},"I am keeping that broader aim separate from the minimum thesis. First, I need a reliable application for the questions and data I have already checked.":{"ro":"Păstrez acest obiectiv mai larg separat de nucleul lucrării. Mai întâi am nevoie de o aplicație fiabilă pentru întrebările și datele deja verificate.","ar":"أفصل هذا الطموح الأوسع عن الحد الأساسي لمشروع التخرج. أحتاج أولًا إلى تطبيق موثوق للأسئلة والبيانات التي تحققت منها."},"Professor Uscatu has agreed to coordinate my thesis. I would like his guidance on turning this into a well-designed Economic Informatics project: clear modules, sensible storage, reliable algorithms and an application that runs smoothly. I also want to understand the code well enough to explain and defend it myself.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Îmi doresc îndrumarea lui pentru un proiect de Informatică Economică bine conceput: module clare, stocare potrivită, algoritmi fiabili și o aplicație care funcționează fluent. Vreau și să înțeleg codul suficient pentru a-l explica și susține singur.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. أريد توجيهه لبناء مشروع جيد في المعلوماتية الاقتصادية، بوحدات واضحة وتخزين مناسب وخوارزميات موثوقة وتطبيق يعمل بسلاسة. وأريد فهم الكود بما يكفي لشرحه ومناقشته بنفسي."},"I would value Professor Davidescu's advice on what the data means, which statistical methods make sense and how to read the results without claiming more than they show. I especially want help reviewing the monthly models and their assumptions.":{"ro":"Aș aprecia sfaturile profesoarei Davidescu despre sensul datelor, metodele statistice potrivite și interpretarea rezultatelor fără afirmații care depășesc dovezile. Îmi doresc în special ajutor la revizuirea modelelor lunare și a ipotezelor lor.","ar":"سأقدّر نصائح الأستاذة Davidescu حول معنى البيانات والأساليب الإحصائية المناسبة وقراءة النتائج دون ادعاء أكثر مما تدعمه. وأرغب خصوصًا في مساعدة لمراجعة النماذج الشهرية وافتراضاتها."},"I will agree the final title and scope with Professor Uscatu. I will also discuss whether Professor Davidescu can offer methodological advice; her involvement is still subject to her agreement.":{"ro":"Voi stabili titlul și delimitarea finală cu profesorul Uscatu. Voi discuta și dacă profesoara Davidescu poate oferi sfaturi metodologice; implicarea ei depinde încă de acordul său.","ar":"سأتفق مع الأستاذ Uscatu على العنوان والنطاق النهائيين. وسأناقش أيضًا إمكانية تقديم الأستاذة Davidescu إرشادًا منهجيًا؛ وما زالت مشاركتها رهن موافقتها."},"The Python prototype currently passes 33 checks. I have enough verified data to build the core thesis: a checked data-processing system, monthly analysis and forecast comparison, yearly development context, clear scenarios and a working application.":{"ro":"Prototipul Python trece în prezent 33 de verificări. Am suficiente date verificate pentru nucleul lucrării: un sistem verificat de procesare a datelor, analiză lunară și comparație a prognozelor, context anual al dezvoltării, scenarii clare și o aplicație funcțională.","ar":"يجتاز نموذج Python الأولي حاليًا 33 فحصًا. لدي بيانات موثقة كافية لبناء أساس مشروع التخرج: نظام معالجة بيانات مُراجع، وتحليل شهري ومقارنة تنبؤات، وسياق سنوي للتنمية، وسيناريوهات واضحة، وتطبيق يعمل."},"Next, I want to review the data warnings and model checks, improve the database and application, and investigate spending categories where comparable records are available. I will keep the project focused enough to finish and understand it properly. A deeper explanation of development differences is something I can expand as the evidence and my professors' advice allow.":{"ro":"În continuare vreau să revizuiesc avertismentele privind datele și verificările modelelor, să îmbunătățesc baza de date și aplicația și să investighez categoriile de cheltuieli pentru care există evidențe comparabile. Voi păstra proiectul suficient de concentrat pentru a-l finaliza și înțelege bine. Pot extinde explicația diferențelor de dezvoltare pe măsură ce dovezile și sfaturile profesorilor permit.","ar":"أريد بعد ذلك مراجعة تنبيهات البيانات وفحوص النماذج وتحسين قاعدة البيانات والتطبيق ودراسة فئات الإنفاق التي تتوفر لها سجلات قابلة للمقارنة. سأحافظ على نطاق محدد يسمح بإكمال المشروع وفهمه جيدًا. ويمكنني توسيع تفسير اختلافات التنمية حين تسمح الأدلة ونصائح أساتذتي."},"My annual development data comes from":{"ro":"Datele mele anuale de dezvoltare provin din","ar":"تأتي بيانات التنمية السنوية من"},"World Bank World Development Indicators":{"ro":"Indicatorii de dezvoltare mondială ai Băncii Mondiale","ar":"مؤشرات التنمية العالمية للبنك الدولي"},". My monthly government accounts come from":{"ro":". Conturile guvernamentale lunare provin din","ar":". وتأتي الحسابات الحكومية الشهرية من"},"Central Bank of Iraq statistical bulletins":{"ro":"Buletinele statistice ale Băncii Centrale a Irakului","ar":"النشرات الإحصائية للبنك المركزي العراقي"},". My yearly outlook comes from the":{"ro":". Perspectivele anuale provin din","ar":". وتأتي الآفاق السنوية من"},"IMF World Economic Outlook":{"ro":"Perspectivele economice mondiale ale FMI","ar":"آفاق الاقتصاد العالمي لصندوق النقد الدولي"},", April 2026 edition. Exact file links, pages, units and source checks are kept in the project's data inventory.":{"ro":", ediția din aprilie 2026. Linkurile exacte ale fișierelor, paginile, unitățile și verificările surselor sunt păstrate în inventarul de date al proiectului.","ar":"، إصدار أبريل 2026. تُحفظ روابط الملفات الدقيقة والصفحات والوحدات وفحوص المصادر في جرد بيانات المشروع."},"For forecasting, I am using":{"ro":"Pentru prognoză folosesc","ar":"أستخدم للتنبؤ"},"Forecasting: Principles and Practice":{"ro":"Forecasting: Principles and Practice","ar":"Forecasting: Principles and Practice"},"and the":{"ro":"și","ar":"و"},"official statsmodels documentation":{"ro":"documentația oficială statsmodels","ar":"الوثائق الرسمية لـstatsmodels"},". The more detailed method notes remain in my private research folder.":{"ro":". Notele metodologice mai detaliate rămân în dosarul meu privat de cercetare.","ar":". تبقى الملاحظات المنهجية الأكثر تفصيلًا في مجلد البحث الخاص."},"For the 2003 starting point, I checked the":{"ro":"Pentru punctul de pornire din 2003 am consultat","ar":"راجعت لنقطة البداية عام 2003"},"UN Secretary-General’s December 2003 remarks":{"ro":"Declarațiile Secretarului General al ONU din decembrie 2003","ar":"تصريحات الأمين العام للأمم المتحدة في ديسمبر 2003"},"My research plan remains open to refinement with my professors.":{"ro":"Planul meu de cercetare rămâne deschis rafinării împreună cu profesorii.","ar":"تبقى خطة بحثي قابلة للمراجعة بالتعاون مع أساتذتي."},"No observations are available in this saved window.":{"ro":"Nu există observații în această perioadă salvată.","ar":"لا توجد مشاهدات متاحة في هذه الفترة المحفوظة."},"Saved research chart":{"ro":"Grafic al rezultatelor salvate","ar":"رسم للبحث المحفوظ"},"Month":{"ro":"Lună","ar":"الشهر"},"Year":{"ro":"An","ar":"السنة"},"Value":{"ro":"Valoare","ar":"القيمة"},"Period":{"ro":"Perioadă","ar":"الفترة"},"Horizontal axis: {period}. Vertical axis: {unit}. Exact observations are available in the chart data table below.":{"ro":"Axa orizontală: {period}. Axa verticală: {unit}. Observațiile exacte sunt disponibile în tabelul de date de sub grafic.","ar":"المحور الأفقي: {period}. المحور العمودي: {unit}. تتوفر المشاهدات الدقيقة في جدول البيانات أسفل الرسم."},"95% prediction interval":{"ro":"Interval de predicție de 95%","ar":"فاصل تنبؤ بنسبة 95%"},"95% lower":{"ro":"Limită inferioară 95%","ar":"الحد الأدنى 95%"},"95% upper":{"ro":"Limită superioară 95%","ar":"الحد الأعلى 95%"},"95% interval":{"ro":"Interval 95%","ar":"فاصل 95%"},"to":{"ro":"până la","ar":"إلى"},"Hover or tap a line for its saved value. With the chart focused, use left and right arrows for periods, up and down for series, and Escape to close the details.":{"ro":"Treci cursorul peste o linie sau atinge-o pentru valoarea salvată. Cu graficul focalizat, folosește săgețile stânga/dreapta pentru perioade, sus/jos pentru serii și Escape pentru a închide detaliile.","ar":"مرّر المؤشر فوق الخط أو المسه لعرض القيمة المحفوظة. بعد تركيز الرسم، استخدم سهمي اليمين واليسار للفترات والأعلى والأسفل للسلاسل وEscape لإغلاق التفاصيل."},"View chart values":{"ro":"Vezi valorile graficului","ar":"اعرض قيم الرسم"},"Real GDP per capita":{"ro":"PIB real pe persoană","ar":"الناتج المحلي الإجمالي الحقيقي للفرد"},"Manufacturing value added":{"ro":"Valoarea adăugată a industriei prelucrătoare","ar":"القيمة المضافة للصناعة التحويلية"},"% per year":{"ro":"% pe an","ar":"% سنويًا"},"% of GDP":{"ro":"% din PIB","ar":"% من الناتج المحلي الإجمالي"},"constant 2015 USD":{"ro":"USD la prețurile constante din 2015","ar":"دولار أمريكي بأسعار 2015 الثابتة"},"USD per person · 2015 prices":{"ro":"USD pe persoană · prețuri 2015","ar":"دولار أمريكي للفرد · أسعار 2015"},"Reported national accounts; may include estimates. Missing observations stay missing.":{"ro":"Conturi naționale raportate; pot include estimări. Observațiile lipsă rămân lipsă.","ar":"حسابات قومية معلنة قد تتضمن تقديرات. تبقى المشاهدات المفقودة مفقودة."},"World Bank staff-derived estimate; not oil GDP or fiscal revenue. Missing observations stay missing.":{"ro":"Estimare calculată de specialiștii Băncii Mondiale; nu reprezintă PIB-ul petrolier sau veniturile fiscale. Observațiile lipsă rămân lipsă.","ar":"تقدير أعده موظفو البنك الدولي؛ وليس الناتج النفطي أو الإيرادات المالية. تبقى المشاهدات المفقودة مفقودة."},"{label} in {units}":{"ro":"{label}, în {units}","ar":"{label}، بوحدة {units}"},"{label} · {units}. Iraq has {count} available annual values{window}. {note}":{"ro":"{label} · {units}. Irakul are {count} valori anuale disponibile{window}. {note}","ar":"{label} · {units}. للعراق {count} قيمة سنوية متاحة{window}. {note}"},"Saved monthly revenue forecast in nominal trillion IQD":{"ro":"Prognoza lunară salvată a veniturilor, în trilioane IQD nominale","ar":"التنبؤ المحفوظ للإيرادات الشهرية بتريليون دينار عراقي اسمي"},"nominal trillion IQD":{"ro":"trilioane IQD nominale","ar":"تريليون دينار عراقي اسمي"},"Revenue · trillion IQD":{"ro":"Venituri · trilioane IQD","ar":"الإيرادات · تريليون دينار عراقي"},"{year} baseline balance":{"ro":"Sold de referință {year}","ar":"الرصيد المرجعي {year}"},"{year} scenario balance":{"ro":"Sold în scenariu {year}","ar":"رصيد السيناريو {year}"},"of baseline GDP":{"ro":"din PIB-ul de referință","ar":"من الناتج المحلي الإجمالي المرجعي"},"of fixed baseline GDP":{"ro":"din PIB-ul fix de referință","ar":"من الناتج المحلي الإجمالي المرجعي الثابت"},"Change in balance":{"ro":"Schimbarea soldului","ar":"تغير الرصيد"},"percentage points":{"ro":"puncte procentuale","ar":"نقاط مئوية"},"IMF baseline":{"ro":"Scenariu de referință FMI","ar":"المسار المرجعي لصندوق النقد الدولي"},"My scenario":{"ro":"Scenariul meu","ar":"السيناريو الخاص بي"},"Conditional annual fiscal balance as percent of fixed GDP":{"ro":"Sold fiscal anual condiționat, ca procent din PIB-ul fix","ar":"الرصيد المالي السنوي المشروط كنسبة من الناتج المحلي الإجمالي الثابت"},"% of fixed baseline GDP":{"ro":"% din PIB-ul fix de referință","ar":"% من الناتج المحلي الإجمالي المرجعي الثابت"},"Budget balance · % of GDP":{"ro":"Sold bugetar · % din PIB","ar":"الرصيد · % من الناتج المحلي"},"I put the three features on a common scale so that their different units do not decide the ranking.":{"ro":"Aduc cele trei caracteristici la o scară comună, astfel încât unitățile diferite să nu determine clasamentul.","ar":"أضع الخصائص الثلاث على مقياس مشترك كي لا تحدد وحداتها المختلفة الترتيب."},"Choose at least one positive weight to calculate a ranking. All loaded countries are still listed below.":{"ro":"Alege cel puțin o pondere pozitivă pentru calcularea clasamentului. Toate țările încărcate rămân enumerate mai jos.","ar":"اختر وزنًا موجبًا واحدًا على الأقل لحساب الترتيب. تبقى جميع البلدان المحمّلة معروضة أدناه."},"REF":{"ro":"REF","ar":"مرجع"},"reference country":{"ro":"țară de referință","ar":"البلد المرجعي"},"The saved preview has an unexpected data format.":{"ro":"Previzualizarea salvată are un format de date neașteptat.","ar":"تنسيق بيانات المعاينة المحفوظة غير متوقع."},"The saved scenario contains an incomplete baseline.":{"ro":"Scenariul salvat conține un reper incomplet.","ar":"يحتوي السيناريو المحفوظ على مسار مرجعي غير مكتمل."},"The saved country comparisons are incomplete.":{"ro":"Comparațiile salvate între țări sunt incomplete.","ar":"مقارنات البلدان المحفوظة غير مكتملة."},"The saved preview could not load.":{"ro":"Previzualizarea salvată nu s-a putut încărca.","ar":"تعذر تحميل المعاينة المحفوظة."},"The saved preview took too long to load.":{"ro":"Încărcarea previzualizării salvate a durat prea mult.","ar":"استغرق تحميل المعاينة المحفوظة وقتًا أطول من اللازم."},"You can retry, or read the research plan below.":{"ro":"Poți reîncerca sau poți citi planul de cercetare de mai jos.","ar":"يمكنك إعادة المحاولة أو قراءة خطة البحث أدناه."},"Select language":{"ro":"Alege limba","ar":"اختر اللغة"},"English":{"ro":"Engleză","ar":"الإنجليزية"},"Romanian":{"ro":"Română","ar":"الرومانية"},"Arabic":{"ro":"Arabă","ar":"العربية"},"Iraq":{"ro":"Irak","ar":"العراق"},"Angola":{"ro":"Angola","ar":"أنغولا"},"United Arab Emirates":{"ro":"Emiratele Arabe Unite","ar":"الإمارات العربية المتحدة"},"Azerbaijan":{"ro":"Azerbaidjan","ar":"أذربيجان"},"Algeria":{"ro":"Algeria","ar":"الجزائر"},"Iran, Islamic Rep.":{"ro":"Iran","ar":"إيران"},"Kazakhstan":{"ro":"Kazahstan","ar":"كازاخستان"},"Kuwait":{"ro":"Kuweit","ar":"الكويت"},"Nigeria":{"ro":"Nigeria","ar":"نيجيريا"},"Oman":{"ro":"Oman","ar":"عُمان"},"Qatar":{"ro":"Qatar","ar":"قطر"},"Saudi Arabia":{"ro":"Arabia Saudită","ar":"السعودية"},"Country selection":{"ro":"Selecția țărilor","ar":"اختيار البلدان"},"Show selected only":{"ro":"Arată doar țările selectate","ar":"اعرض البلدان المحددة فقط"},"Show all countries":{"ro":"Arată toate țările","ar":"اعرض جميع البلدان"},"Select country lines to focus on them. Select several to compare, or show only your selection.":{"ro":"Selectează liniile țărilor pentru a le evidenția. Alege mai multe pentru comparație sau arată doar selecția ta.","ar":"حدد خطوط البلدان للتركيز عليها. اختر عدة بلدان للمقارنة أو اعرض البلدان المحددة فقط."},"All {count} countries are visible.":{"ro":"Toate cele {count} țări sunt vizibile.","ar":"جميع البلدان الـ{count} ظاهرة."},"Focused: {countries}. All countries remain visible.":{"ro":"Evidențiate: {countries}. Toate țările rămân vizibile.","ar":"التركيز على: {countries}. تبقى جميع البلدان ظاهرة."},"Showing only: {countries}.":{"ro":"Sunt afișate doar: {countries}.","ar":"يُعرض فقط: {countries}."},"Choose countries from the legend to filter the chart.":{"ro":"Alege țări din legendă pentru a filtra graficul.","ar":"اختر بلدانًا من مفتاح الرسم لتصفية المخطط."},"Select {country}":{"ro":"Selectează {country}","ar":"حدد {country}"},"From a question":{"ro":"De la o întrebare","ar":"من سؤال"},"to a":{"ro":"la un","ar":"إلى"},"working system.":{"ro":"sistem funcțional.","ar":"نظام يعمل."},"How I am turning my questions about Iraq into a careful study and an application I can explain, test and keep developing.":{"ro":"Cum transform întrebările mele despre Irak într-un studiu atent și o aplicație pe care o pot explica, testa și dezvolta în continuare.","ar":"كيف أحول أسئلتي عن العراق إلى دراسة دقيقة وتطبيق أستطيع شرحه واختباره ومواصلة تطويره."},"CASE STUDY":{"ro":"STUDIU DE CAZ","ar":"دراسة الحالة"},"Iraq since 2003":{"ro":"Irakul din 2003","ar":"العراق منذ عام 2003"},"SOFTWARE":{"ro":"SOFTWARE","ar":"البرنامج"},"An economic analysis system":{"ro":"Un sistem de analiză economică","ar":"نظام للتحليل الاقتصادي"},"CURRENT STATUS":{"ro":"STADIUL ACTUAL","ar":"الحالة الحالية"},"Provisional title · coordinator agreed":{"ro":"Titlu provizoriu · coordonator confirmat","ar":"عنوان حالي · موافقة المشرف على الإشراف"},"Professor Uscatu has agreed to coordinate my thesis. The revised title and final scope still need his confirmation.":{"ro":"Profesorul Uscatu a acceptat să îmi coordoneze lucrarea. Titlul revizuit și delimitarea finală necesită încă acordul său.","ar":"وافق الأستاذ Uscatu على الإشراف على مشروع تخرجي. ما زال العنوان المعدل والنطاق النهائي بحاجة إلى تأكيده."},"See the data and try the saved results.":{"ro":"Vezi datele și încearcă rezultatele salvate.","ar":"اطّلع على البيانات وجرّب النتائج المحفوظة."},"HOBBIES":{"ro":"PASIUNI","ar":"الهوايات"},"Why I value my professors' guidance":{"ro":"De ce apreciez îndrumarea profesorilor mei","ar":"لماذا أقدّر توجيه أساتذتي"},"Professor Uscatu and Professor Davidescu have both agreed to work with me on this project. I respect them greatly, and I look forward to learning from them and building something I can be proud of.":{"ro":"Profesorul Uscatu și profesoara Davidescu au acceptat amândoi să lucreze cu mine la acest proiect. Îi respect foarte mult și abia aștept să învăț de la ei și să construiesc ceva de care pot fi mândru.","ar":"وافق الأستاذ Uscatu والأستاذة Davidescu على العمل معي في هذا المشروع. أحترمهما كثيرًا، وأتطلع إلى التعلم منهما وبناء عمل أستطيع أن أفخر به."},"I look forward to Professor Uscatu's guidance on the software: clear modules, sensible storage, reliable algorithms and an application that runs smoothly. I want to understand the code well enough to explain and defend it myself.":{"ro":"Aștept cu interes îndrumarea profesorului Uscatu pentru partea software: module clare, stocare potrivită, algoritmi fiabili și o aplicație care funcționează fluent. Vreau să înțeleg codul suficient de bine pentru a-l explica și susține singur.","ar":"أتطلع إلى توجيه الأستاذ Uscatu في الجانب البرمجي: وحدات واضحة وتخزين مناسب وخوارزميات موثوقة وتطبيق يعمل بسلاسة. أريد فهم الكود بما يكفي لشرحه ومناقشته بنفسي."},"I look forward to Professor Davidescu's insight into the data, statistical methods and interpretation. Her guidance will help me ask stronger questions, review the models carefully and understand what the results really mean.":{"ro":"Aștept cu interes perspectiva profesoarei Davidescu asupra datelor, metodelor statistice și interpretării. Îndrumarea ei mă va ajuta să formulez întrebări mai bune, să verific modelele atent și să înțeleg ce înseamnă cu adevărat rezultatele.","ar":"أتطلع إلى رؤى الأستاذة Davidescu حول البيانات والأساليب الإحصائية والتفسير. سيساعدني توجيهها على طرح أسئلة أقوى ومراجعة النماذج بعناية وفهم المعنى الحقيقي للنتائج."},"I want their advice to challenge my ideas and help me grow as a programmer and researcher. The title and final scope will be refined with Professor Uscatu as the project develops.":{"ro":"Vreau ca sfaturile lor să îmi pună ideile la încercare și să mă ajute să cresc ca programator și cercetător. Titlul și delimitarea finală vor fi rafinate cu profesorul Uscatu pe măsură ce proiectul evoluează.","ar":"أريد أن تختبر نصائحهما أفكاري وتساعدني على التطور كمبرمج وباحث. سأراجع العنوان والنطاق النهائي مع الأستاذ Uscatu مع تطور المشروع."},"The foundation is in place: checked data processing, monthly analysis and forecast comparisons, yearly development context, clear scenarios and a working Python application.":{"ro":"Baza este pregătită: procesare verificată a datelor, analiză lunară și comparații ale prognozelor, context anual al dezvoltării, scenarii clare și o aplicație Python funcțională.","ar":"الأساس جاهز: معالجة بيانات مُراجعة، وتحليل شهري ومقارنة تنبؤات، وسياق سنوي للتنمية، وسيناريوهات واضحة، وتطبيق Python يعمل."},"Next, I want to review the data warnings and model checks, improve the database and application, and investigate spending categories where comparable records are available. I will keep the thesis focused enough to finish and understand it properly, while leaving room for the program to grow.":{"ro":"În continuare vreau să revizuiesc avertismentele datelor și verificările modelelor, să îmbunătățesc baza de date și aplicația și să investighez categoriile de cheltuieli cu evidențe comparabile. Voi păstra lucrarea suficient de concentrată pentru a o finaliza și înțelege bine, lăsând loc programului să crească.","ar":"أريد بعد ذلك مراجعة تنبيهات البيانات وفحوص النماذج وتحسين قاعدة البيانات والتطبيق ودراسة فئات الإنفاق التي تتوفر لها سجلات قابلة للمقارنة. سأحافظ على نطاق يسمح بإكمال البحث وفهمه جيدًا، مع ترك مجال لتوسع البرنامج."},"I can't wait to see what my teachers cook up for me: ideas to add, questions to explore and ways to make this work better. The sky is the limit for where I hope to take it. I will put all the passion I have into making this a useful tool for anyone interested in understanding a country's economy, just as I am trying to understand my own.":{"ro":"Abia aștept să văd ce idei vor pregăti profesorii mei pentru mine: lucruri de adăugat, întrebări de explorat și moduri de a îmbunătăți proiectul. Cerul este limita pentru ceea ce sper să devină. Îmi voi pune toată pasiunea în a-l transforma într-un instrument util oricui vrea să înțeleagă economia unei țări, așa cum încerc eu să o înțeleg pe a mea.","ar":"لا أطيق الانتظار لأرى ما سيحضّره أساتذتي لي من أفكار أضيفها وأسئلة أستكشفها وطرق أحسّن بها هذا العمل. السماء هي الحد لما أطمح أن أصل إليه. سأضع كل شغفي في جعله أداة مفيدة لكل من يهتم بفهم اقتصاد بلد، كما أحاول أنا فهم اقتصاد بلدي."},"0 · Excluded":{"ro":"0 · Exclus","ar":"0 · مستبعد"},"3 · Most weight":{"ro":"3 · Pondere maximă","ar":"3 · أعلى وزن"},"Reset weights":{"ro":"Resetează ponderile","ar":"إعادة ضبط الأوزان"},"Reset assumptions":{"ro":"Resetează ipotezele","ar":"إعادة ضبط الافتراضات"},"Browse the presentation I prepared for my thesis proposal.":{"ro":"Răsfoiește prezentarea pregătită pentru propunerea mea de licență.","ar":"تصفح العرض الذي أعددته لمقترح مشروع تخرجي."},"VIEW MY PITCH ↓":{"ro":"VEZI PREZENTAREA MEA ↓","ar":"شاهد عرض المقترح ↓"},"THE POWERPOINT · INSIDE THE PAGE":{"ro":"PREZENTAREA POWERPOINT · ÎN PAGINĂ","ar":"عرض POWERPOINT · داخل الصفحة"},"Browse my thesis pitch.":{"ro":"Răsfoiește prezentarea lucrării mele.","ar":"تصفح عرض مقترح مشروع تخرجي."},"Use previous and next, or the arrow keys, to browse the slides.":{"ro":"Folosește butoanele anterior și următor sau săgețile tastaturii pentru a răsfoi diapozitivele.","ar":"استخدم زري السابق والتالي أو مفاتيح الأسهم لتصفح الشرائح."},"Original proposal slides · English":{"ro":"Diapozitivele propunerii inițiale · Engleză","ar":"شرائح المقترح الأصلي · بالإنجليزية"},"Go to the previous slide":{"ro":"Mergi la diapozitivul anterior","ar":"انتقل إلى الشريحة السابقة"},"Go to the next slide":{"ro":"Mergi la diapozitivul următor","ar":"انتقل إلى الشريحة التالية"},"Slides viewed":{"ro":"Diapozitive vizualizate","ar":"الشرائح المعروضة"},"PREVIOUS":{"ro":"ANTERIOR","ar":"السابق"},"NEXT":{"ro":"URMĂTOR","ar":"التالي"},"MY THESIS PITCH":{"ro":"PREZENTAREA LUCRĂRII MELE","ar":"عرض مقترح مشروع تخرجي"},"KEEP OR PRESENT THE ORIGINAL DECK":{"ro":"SALVEAZĂ SAU PREZINTĂ FIȘIERUL ORIGINAL","ar":"احفظ العرض الأصلي أو قدمه"},"DOWNLOAD THE POWERPOINT ↓":{"ro":"DESCARCĂ POWERPOINT ↓","ar":"تحميل POWERPOINT ↓"},"DOWNLOAD THE PDF ↓":{"ro":"DESCARCĂ PDF ↓","ar":"تحميل PDF ↓"},"Iraq, oil and the budget":{"ro":"Irakul, petrolul și bugetul","ar":"العراق والنفط والموازنة"},"My original proposal for a Python application and research into Iraq’s economy.":{"ro":"Propunerea mea inițială pentru o aplicație Python și un studiu al economiei Irakului.","ar":"مقترحي الأصلي لتطبيق Python وبحث في اقتصاد العراق."},"Why this matters to me":{"ro":"De ce contează pentru mine","ar":"لماذا يهمني هذا الموضوع"},"I grew up in Iraq and want to understand what its economic data can tell me.":{"ro":"Am crescut în Irak și vreau să înțeleg ce îmi pot spune datele economice.","ar":"نشأت في العراق وأريد أن أفهم ما تكشفه بياناته الاقتصادية."},"What happens when oil income changes?":{"ro":"Ce se întâmplă când veniturile din petrol se schimbă?","ar":"ماذا يحدث عندما يتغير الدخل النفطي؟"},"The project follows the links between oil income, public revenue and budget pressure.":{"ro":"Proiectul urmărește legăturile dintre veniturile din petrol, veniturile publice și presiunea asupra bugetului.","ar":"يتتبع المشروع الروابط بين الدخل النفطي والإيرادات العامة والضغط على الموازنة."},"I have annual history and a monthly fiscal core":{"ro":"Am un istoric anual și un nucleu fiscal lunar","ar":"لدي تاريخ سنوي وقاعدة بيانات مالية شهرية"},"The source overview separates annual development data, monthly fiscal records and projections.":{"ro":"Privirea de ansamblu separă datele anuale de dezvoltare, evidențele fiscale lunare și proiecțiile.","ar":"تفصل نظرة المصادر بين بيانات التنمية السنوية والسجلات المالية الشهرية والتوقعات."},"The budget moved from surplus to deficit":{"ro":"Bugetul a trecut de la excedent la deficit","ar":"انتقلت الموازنة من فائض إلى عجز"},"Recorded budget balances show changing fiscal conditions across the observed years.":{"ro":"Soldurile bugetare înregistrate arată schimbarea condițiilor fiscale în anii observați.","ar":"تبين أرصدة الموازنة المسجلة تغير الأوضاع المالية خلال السنوات المرصودة."},"I can track oil-related revenue each month":{"ro":"Pot urmări lunar veniturile legate de petrol","ar":"أستطيع تتبع الإيرادات المرتبطة بالنفط كل شهر"},"Monthly observations help me inspect how oil-related and other revenue develop.":{"ro":"Observațiile lunare mă ajută să analizez evoluția veniturilor legate de petrol și a celorlalte venituri.","ar":"تساعدني الملاحظات الشهرية في فحص تطور الإيرادات النفطية والإيرادات الأخرى."},"I also want to look beyond the budget":{"ro":"Vreau să privesc și dincolo de buget","ar":"أريد أيضًا أن أنظر إلى ما وراء الموازنة"},"Real GDP per person and manufacturing add a broader view of development.":{"ro":"PIB-ul real pe locuitor și industria prelucrătoare oferă o perspectivă mai largă asupra dezvoltării.","ar":"يضيف الناتج الحقيقي للفرد والصناعات التحويلية نظرة أوسع إلى التنمية."},"My Python application turns inputs into results":{"ro":"Aplicația mea Python transformă intrările în rezultate","ar":"يحول تطبيقي بلغة Python المدخلات إلى نتائج"},"The prototype connects adjustable assumptions with calculations, charts and exports.":{"ro":"Prototipul leagă ipotezele ajustabile de calcule, grafice și exporturi.","ar":"يربط النموذج الأولي الافتراضات القابلة للتعديل بالحسابات والرسوم والتصدير."},"My monthly fiscal view is already working":{"ro":"Vizualizarea fiscală lunară funcționează deja","ar":"تعمل بالفعل واجهة البيانات المالية الشهرية"},"The application keeps the original totals and shows how monthly values are derived.":{"ro":"Aplicația păstrează totalurile originale și arată cum sunt obținute valorile lunare.","ar":"يحفظ التطبيق المجاميع الأصلية ويوضح كيفية اشتقاق القيم الشهرية."},"I can explain how the comparisons work":{"ro":"Pot explica modul de calcul al comparațiilor","ar":"أستطيع شرح كيفية عمل المقارنات"},"Country comparisons use defined features and make the calculation visible.":{"ro":"Comparațiile între țări folosesc caracteristici definite și fac calculul vizibil.","ar":"تستخدم مقارنات الدول خصائص محددة وتجعل طريقة الحساب واضحة."},"The software is part of the research":{"ro":"Software-ul face parte din cercetare","ar":"البرنامج جزء من البحث"},"The system covers source checks, storage, analysis and a working interface.":{"ro":"Sistemul include verificarea surselor, stocarea, analiza și o interfață funcțională.","ar":"يشمل النظام فحص المصادر والتخزين والتحليل وواجهة تعمل فعليًا."},"Monthly forecasts I have tested":{"ro":"Prognozele lunare pe care le-am testat","ar":"التنبؤات الشهرية التي اختبرتها"},"The saved experiment compares prediction errors across methods on shared historical targets.":{"ro":"Experimentul salvat compară erorile de predicție ale metodelor pe aceleași observații istorice.","ar":"تقارن التجربة المحفوظة أخطاء التنبؤ بين الطرق باستخدام أهداف تاريخية مشتركة."},"What if oil prices fall by 10%?":{"ro":"Ce se întâmplă dacă prețul petrolului scade cu 10%?","ar":"ماذا لو انخفضت أسعار النفط بنسبة 10%؟"},"This example changes an oil-price assumption while keeping other inputs fixed.":{"ro":"Acest exemplu modifică o ipoteză despre prețul petrolului, păstrând celelalte intrări constante.","ar":"يغير هذا المثال افتراض سعر النفط مع تثبيت المدخلات الأخرى."},"What I have ready, and what comes next":{"ro":"Ce am pregătit și ce urmează","ar":"ما أنجزته وما يأتي بعده"},"The proposal separates the working foundation from the remaining research and software work.":{"ro":"Propunerea separă baza funcțională de activitățile de cercetare și dezvoltare rămase.","ar":"يفصل المقترح الأساس العامل عن أعمال البحث والبرمجة المتبقية."},"The guidance I would like from you":{"ro":"Îndrumarea pe care mi-o doresc","ar":"التوجيه الذي أتطلع إليه"},"My original pitch describes the guidance I hoped to receive. Both professors have since agreed to work with me.":{"ro":"Prezentarea inițială descrie îndrumarea pe care o speram. Între timp, ambii profesori au acceptat să lucreze cu mine.","ar":"يصف عرضي الأصلي التوجيه الذي كنت أتطلع إليه. وقد وافق الأستاذان منذ ذلك الحين على العمل معي."},"Could we develop this into my bachelor thesis?":{"ro":"Am putea dezvolta acest proiect ca lucrare de licență?","ar":"هل يمكن أن نطور هذا إلى مشروع تخرجي؟"},"The original proposal includes an earlier working title. My current thesis title appears at the top of this page.":{"ro":"Propunerea inițială include un titlu de lucru anterior. Titlul actual al lucrării apare în partea de sus a acestei pagini.","ar":"يتضمن المقترح الأصلي عنوانًا سابقًا. يظهر عنوان مشروع تخرجي الحالي في أعلى هذه الصفحة."},"Sources I used for this proposal":{"ro":"Sursele folosite pentru această propunere","ar":"المصادر التي استخدمتها لهذا المقترح"},"The source slide records the data providers and photograph credits used in the proposal.":{"ro":"Diapozitivul cu surse menționează furnizorii datelor și autorii fotografiilor folosite în propunere.","ar":"تذكر شريحة المصادر مزودي البيانات وأصحاب الصور المستخدمة في المقترح."},"The limits I need to keep visible":{"ro":"Limitele pe care trebuie să le păstrez vizibile","ar":"الحدود التي يجب أن أوضحها"},"Definitions, gaps, uncertainty and the distinction between observations and assumptions remain visible.":{"ro":"Definițiile, lipsurile, incertitudinea și diferența dintre observații și ipoteze rămân vizibile.","ar":"تبقى التعريفات والفجوات وعدم اليقين والفرق بين الملاحظات والافتراضات واضحة."},"Thank you for considering my proposal.":{"ro":"Vă mulțumesc pentru analizarea propunerii mele.","ar":"شكرًا للنظر في مقترحي."},"The original proposal closes with an invitation for feedback and guidance.":{"ro":"Propunerea inițială se încheie cu o invitație la feedback și îndrumare.","ar":"يختتم المقترح الأصلي بدعوة للملاحظات والتوجيه."},"Seasonal ARIMA":{"ro":"ARIMA sezonier","ar":"ARIMA موسمي"},"The full model specification appears in the chart legend.":{"ro":"Specificația completă a modelului apare în legenda graficului.","ar":"تظهر مواصفات النموذج الكاملة في مفتاح الرسم البياني."},"IRAQ AT A GLANCE":{"ro":"IRAK PE SCURT","ar":"العراق في لمحة"},"RESULTS OVERVIEW":{"ro":"REZULTATE PE SCURT","ar":"نظرة على النتائج"},"NATIONAL ECONOMIC PORTRAIT":{"ro":"PROFIL ECONOMIC NAȚIONAL","ar":"الصورة الاقتصادية الوطنية"},"DATED DATA / CLEAR UNITS":{"ro":"DATE PRECIZATE / UNITĂȚI CLARE","ar":"بيانات مؤرخة / وحدات واضحة"},"at a glance.":{"ro":"pe scurt.","ar":"في لمحة."},"The national picture, with the date and source kept beside every number.":{"ro":"Imaginea națională, cu data și sursa alături de fiecare număr.","ar":"الصورة الوطنية، مع تاريخ كل رقم ومصدره بجواره."},"IRAQ / NATIONAL INDICATORS":{"ro":"IRAK / INDICATORI NAȚIONALI","ar":"العراق / مؤشرات وطنية"},"National outline of Iraq":{"ro":"Conturul național al Irakului","ar":"الحدود الوطنية للعراق"},"National totals, shown with a country outline.":{"ro":"Date naționale, prezentate alături de conturul țării.","ar":"قيم وطنية مع خريطة لحدود البلد."},"Outline: Natural Earth ↗":{"ro":"Contur: Natural Earth ↗","ar":"الحدود: Natural Earth ↗"},"World Bank WDI · saved October 2026. Published national series can include estimates. Each card uses its own latest available year.":{"ro":"WDI, Banca Mondială · salvate în octombrie 2026. Seriile naționale publicate pot include estimări. Fiecare card folosește ultimul an disponibil pentru indicatorul său.","ar":"مؤشرات التنمية العالمية للبنك الدولي · محفوظة في أكتوبر 2026. قد تتضمن السلاسل الوطنية المنشورة تقديرات. تستخدم كل بطاقة آخر سنة متاحة لمؤشرها."},"RESULTS DASHBOARD":{"ro":"PANOU DE REZULTATE","ar":"لوحة النتائج"},"HISTORY / OUTLOOK / MODELS / SCENARIOS":{"ro":"ISTORIC / PERSPECTIVE / MODELE / SCENARII","ar":"سجل / آفاق / نماذج / سيناريوهات"},"The results,":{"ro":"Rezultatele,","ar":"النتائج،"},"together.":{"ro":"împreună.","ar":"في مكان واحد."},"A quick route into the evidence, saved model results and assumptions I can change.":{"ro":"O cale rapidă spre date, rezultatele salvate ale modelelor și ipotezele pe care le pot schimba.","ar":"مدخل سريع إلى الأدلة ونتائج النماذج المحفوظة والافتراضات التي يمكنني تغييرها."},"INTERNATIONAL SOURCE PROJECTIONS":{"ro":"PROIECȚII DIN SURSE INTERNAȚIONALE","ar":"توقعات من مصادر دولية"},"The IMF outlook for Iraq":{"ro":"Perspectivele FMI pentru Irak","ar":"آفاق العراق بحسب صندوق النقد الدولي"},"IMF WEO · April 2026 ↗":{"ro":"FMI WEO · aprilie 2026 ↗","ar":"آفاق الاقتصاد العالمي لصندوق النقد الدولي · أبريل 2026 ↗"},"IMF WEO · April 2026":{"ro":"FMI WEO · aprilie 2026","ar":"آفاق الاقتصاد العالمي لصندوق النقد الدولي · أبريل 2026"},"These are the saved April 2026 projections. This release stays labelled so the original results can be reproduced.":{"ro":"Acestea sunt proiecțiile salvate din aprilie 2026. Păstrez ediția indicată pentru ca rezultatele originale să poată fi reproduse.","ar":"هذه توقعات أبريل 2026 المحفوظة. أبقي اسم الإصدار ظاهرًا لإتاحة إعادة إنتاج النتائج الأصلية."},"International indicator":{"ro":"Indicator internațional","ar":"المؤشر الدولي"},"Projection year":{"ro":"Anul proiecției","ar":"سنة التوقع"},"Average consumer-price inflation":{"ro":"Inflația medie a prețurilor de consum","ar":"متوسط تضخم أسعار المستهلك"},"Government gross debt":{"ro":"Datoria publică brută","ar":"الدين الحكومي الإجمالي"},"Government budget balance":{"ro":"Soldul bugetului public","ar":"رصيد الموازنة الحكومية"},"Current account balance":{"ro":"Soldul contului curent","ar":"رصيد الحساب الجاري"},"Solid lines show historical or estimated IMF values; dashed lines show source projections. These are separate from my saved monthly revenue forecasts and user-selected budget scenarios.":{"ro":"Liniile continue arată valori istorice sau estimate de FMI; cele întrerupte arată proiecțiile sursei. Acestea sunt distincte de prognozele mele lunare salvate pentru venituri și de scenariile bugetare alese de utilizator.","ar":"تعرض الخطوط المتصلة قيم صندوق النقد التاريخية أو المقدرة، والخطوط المتقطعة توقعاته. وهي مستقلة عن تنبؤاتي الشهرية المحفوظة للإيرادات وسيناريوهات الموازنة التي يختارها المستخدم."},"Start year":{"ro":"Anul de început","ar":"سنة البداية"},"End year":{"ro":"Anul de sfârșit","ar":"سنة النهاية"},"Reported data":{"ro":"Date raportate","ar":"بيانات منشورة"},"Comparison":{"ro":"Comparație","ar":"مقارنة"},"Scenario calculation":{"ro":"Calcul de scenariu","ar":"حساب سيناريو"},"Saved model result":{"ro":"Rezultat salvat al modelului","ar":"نتيجة نموذج محفوظة"},"Data availability":{"ro":"Disponibilitatea datelor","ar":"توفر البيانات"},"Limits and calculation details":{"ro":"Limite și detaliile calculului","ar":"الحدود وتفاصيل الحساب"},"Calculation record (JSON)":{"ro":"Înregistrarea calculului (JSON)","ar":"سجل الحساب (JSON)"},"What this selection shows":{"ro":"Ce arată această selecție","ar":"ما يوضحه هذا الاختيار"},"Calculated from the current selection.":{"ro":"Calculat din selecția curentă.","ar":"محسوب من الاختيار الحالي."},"More notes ({count})":{"ro":"Alte observații ({count})","ar":"ملاحظات أخرى ({count})"},"Download these notes":{"ro":"Descarcă aceste observații","ar":"تنزيل هذه الملاحظات"},"{label}, {start}–{end}, {units}":{"ro":"{label}, {start}–{end}, {units}","ar":"{label}، {start}–{end}، {units}"},"Reported / estimated":{"ro":"Raportat / estimat","ar":"منشور / مقدر"},"Inspect history":{"ro":"Examinează istoricul","ar":"استعرض السجل"},"Monthly revenue forecast":{"ro":"Prognoza veniturilor lunare","ar":"تنبؤ الإيرادات الشهرية"},"{model} · {months} saved one-month-ahead test targets. History ends in {origin}.":{"ro":"{model} · {months} ținte salvate, evaluate cu o lună înainte. Istoricul se încheie în {origin}.","ar":"{model} · {months} شهرًا محفوظًا للاختبار بتنبؤ لشهر واحد مقدمًا. ينتهي السجل في {origin}."},"Inspect the saved models":{"ro":"Examinează modelele salvate","ar":"استعرض النماذج المحفوظة"},"Budget balance under my assumptions":{"ro":"Soldul bugetar sub ipotezele mele","ar":"رصيد الموازنة وفق افتراضاتي"},"Oil-price change {price}%; sensitive revenue share {share}%. The baseline balance is {baseline}%.":{"ro":"Schimbarea prețului petrolului: {price}%; ponderea veniturilor sensibile: {share}%. Soldul de referință este {baseline}%.","ar":"تغير سعر النفط {price}%؛ حصة الإيرادات الحساسة {share}%. رصيد المسار المرجعي {baseline}%."},"Change the assumptions":{"ro":"Schimbă ipotezele","ar":"غيّر الافتراضات"},"Nearest baseline match":{"ro":"Cel mai apropiat profil de referință","ar":"أقرب ملف في الفترة المرجعية"},"Distance {distance} · unitless":{"ro":"Distanță {distance} · fără unitate","ar":"المسافة {distance} · دون وحدة"},"Choose at least one positive weight":{"ro":"Alege cel puțin o pondere pozitivă","ar":"اختر وزنًا موجبًا واحدًا على الأقل"},"The comparison uses the fixed 2003–2007 baseline and the weights currently selected.":{"ro":"Comparația folosește perioada fixă 2003–2007 și ponderile selectate acum.","ar":"تستخدم المقارنة الفترة المرجعية الثابتة 2003–2007 والأوزان المختارة حاليًا."},"Inspect the comparison":{"ro":"Examinează comparația","ar":"استعرض المقارنة"},"Research in progress":{"ro":"Cercetare în curs","ar":"بحث قيد التطوير"},"Growth-model investigation":{"ro":"Studiul unui model de creștere","ar":"دراسة نموذج للنمو"},"Dataset and model checks":{"ro":"Verificarea datelor și a modelului","ar":"فحوص البيانات والنموذج"},"I am investigating a multivariate growth model. A longer, consistent GDP dataset and model diagnostics come first.":{"ro":"Investighez un model de creștere cu mai multe variabile. Mai întâi sunt necesare o serie PIB mai lungă și consistentă și verificările modelului.","ar":"أدرس نموذج نمو متعدد المتغيرات. تأتي أولًا بيانات متسقة وأطول للناتج المحلي الإجمالي وفحوص النموذج."},"IMF projection":{"ro":"Proiecție FMI","ar":"توقع صندوق النقد الدولي"},"Historical / estimated":{"ro":"Istoric / estimat","ar":"تاريخي / مقدر"},"IMF projections · April 2026":{"ro":"Proiecții FMI · aprilie 2026","ar":"توقعات صندوق النقد الدولي · أبريل 2026"},"rose":{"ro":"a crescut","ar":"ارتفع"},"fell":{"ro":"a scăzut","ar":"انخفض"},"was unchanged":{"ro":"a rămas neschimbat","ar":"لم يتغير"},"oil rents":{"ro":"rentele petroliere","ar":"الريع النفطي"},"log real GDP per person":{"ro":"logaritmul PIB real pe persoană","ar":"لوغاريتم الناتج الحقيقي للفرد"},"manufacturing share":{"ro":"ponderea industriei prelucrătoare","ar":"حصة الصناعة التحويلية"},"A positive growth rate means output grew in that year; a falling positive rate means slower growth, not necessarily falling output.":{"ro":"O rată pozitivă arată creșterea producției în acel an; o rată pozitivă mai mică înseamnă creștere mai lentă, nu neapărat scăderea producției.","ar":"يعني معدل النمو الموجب أن الإنتاج نما في تلك السنة؛ وانخفاض معدل موجب يعني تباطؤ النمو، وليس بالضرورة انخفاض الإنتاج."},"This is output per person after allowing for price changes. It is not the income of a typical household.":{"ro":"Aceasta este producția pe persoană, ajustată pentru prețuri. Nu reprezintă venitul unei gospodării obișnuite.","ar":"هذا إنتاج للفرد بعد تعديل تغير الأسعار، وليس دخل الأسرة المعتادة."},"This is a share of GDP. A falling share does not by itself establish that manufacturing output fell.":{"ro":"Aceasta este o pondere în PIB. Scăderea ponderii nu dovedește singură scăderea producției industriei prelucrătoare.","ar":"هذه حصة من الناتج المحلي الإجمالي. لا يثبت انخفاض الحصة وحده انخفاض إنتاج الصناعة التحويلية."},"Oil rents estimate the value of oil production after production costs. They are not government oil revenue or the oil sector’s share of GDP.":{"ro":"Rentele petroliere estimează valoarea producției de petrol după costurile de producție. Nu sunt venituri petroliere ale guvernului și nici ponderea sectorului petrolier în PIB.","ar":"يقدر الريع النفطي قيمة إنتاج النفط بعد تكاليف الإنتاج. وهو ليس إيرادات الحكومة النفطية أو حصة قطاع النفط من الناتج المحلي الإجمالي."},"This describes the selected data. It does not establish a cause or a statistically significant difference.":{"ro":"Aceasta descrie datele selectate. Nu stabilește o cauză sau o diferență semnificativă statistic.","ar":"هذا وصف للبيانات المختارة، ولا يثبت سببًا أو فرقًا ذا دلالة إحصائية."},"No {label} values for {country}":{"ro":"Nu există valori pentru {label} în {country}","ar":"لا تتوفر قيم {label} لـ{country}"},"No values are available for {start}–{end}. Choose another period or indicator.":{"ro":"Nu există valori disponibile pentru {start}–{end}. Alege altă perioadă sau alt indicator.","ar":"لا تتوفر قيم للفترة {start}–{end}. اختر فترة أو مؤشرًا آخر."},"Missing years stay missing. The dates in this note are the available endpoints.":{"ro":"Anii lipsă rămân lipsă. Datele din această observație sunt capetele disponibile ale perioadei.","ar":"تبقى السنوات المفقودة مفقودة. والتواريخ في هذه الملاحظة هي نهايتا الفترة المتاحتان."},"One value for {country}":{"ro":"O singură valoare pentru {country}","ar":"قيمة واحدة لـ{country}"},"{label} was {value} {units} in {year}. One value cannot show a change over time.":{"ro":"{label} a fost {value} {units} în {year}. O singură valoare nu poate arăta o schimbare în timp.","ar":"بلغ {label} مقدار {value} {units} في {year}. لا تكفي قيمة واحدة لإظهار تغير عبر الزمن."},"{country}: {label} {direction}":{"ro":"{country}: {label} {direction}","ar":"{country}: {direction} {label}"},"From {start} to {end}, the value went from {first} to {last} {units}. The change is {change} {change_units}. {count} of {expected} selected annual values are available.":{"ro":"Între {start} și {end}, valoarea a trecut de la {first} la {last} {units}. Schimbarea este {change} {change_units}. Sunt disponibile {count} din {expected} valori anuale selectate.","ar":"بين {start} و{end}، انتقلت القيمة من {first} إلى {last} {units}. التغير {change} {change_units}. تتوفر {count} من أصل {expected} قيمة سنوية مختارة."},"The final growth rate is negative: output contracted in that year, even if the rate improved.":{"ro":"Rata finală de creștere este negativă: producția s-a redus în acel an, chiar dacă rata s-a îmbunătățit.","ar":"معدل النمو الأخير سالب: انخفض الإنتاج في تلك السنة حتى لو تحسن المعدل."},"{country}: the largest available one-year move":{"ro":"{country}: cea mai mare schimbare anuală disponibilă","ar":"{country}: أكبر تغير سنوي متاح"},"Between {start} and {end}, the change was {change} {change_units}. This compares consecutive available years within your selection.":{"ro":"Între {start} și {end}, schimbarea a fost {change} {change_units}. Sunt comparați ani consecutivi disponibili din selecția ta.","ar":"بين {start} و{end}، بلغ التغير {change} {change_units}. تقارن هذه الملاحظة سنوات متتالية متاحة ضمن اختيارك."},"These two countries moved in different directions":{"ro":"Aceste două țări au evoluat în direcții diferite","ar":"تحرك هذان البلدان في اتجاهين مختلفين"},"Using the same available endpoint years, {start}–{end}, {label} {first_direction} in {first_country} and {second_direction} in {second_country}. This is a difference to investigate, not an explanation of its cause.":{"ro":"Folosind aceiași ani disponibili de început și sfârșit, {start}–{end}, {label} {first_direction} în {first_country} și {second_direction} în {second_country}. Diferența merită investigată, dar nu explică singură cauza.","ar":"باستخدام سنتي البداية والنهاية المتاحتين نفسيهما، {start}–{end}، {first_direction} {label} في {first_country} و{second_direction} في {second_country}. هذا فرق يستحق الدراسة، ولا يفسر سببه."},"This is a calculation under the selected assumptions, not a forecast or an assigned probability.":{"ro":"Acesta este un calcul sub ipotezele selectate, nu o prognoză sau o probabilitate atribuită.","ar":"هذا حساب وفق الافتراضات المختارة، وليس تنبؤًا أو احتمالًا محددًا."},"Baseline GDP and the exchange rate stay fixed. This model does not simulate government responses, financing or debt dynamics.":{"ro":"PIB-ul de referință și cursul de schimb rămân fixe. Modelul nu simulează răspunsul guvernului, finanțarea sau dinamica datoriei.","ar":"يبقى الناتج المحلي المرجعي وسعر الصرف ثابتين. لا يحاكي النموذج استجابات الحكومة أو التمويل أو ديناميكيات الدين."},"How this selection changes the budget balance":{"ro":"Cum schimbă această selecție soldul bugetar","ar":"كيف يغير هذا الاختيار رصيد الموازنة"},"In {year}, the baseline balance is {baseline}% of GDP and the scenario balance is {scenario}%. The difference is {change} percentage points.":{"ro":"În {year}, soldul de referință este {baseline}% din PIB, iar soldul scenariului este {scenario}%. Diferența este de {change} puncte procentuale.","ar":"في {year}، يبلغ الرصيد المرجعي {baseline}% من الناتج المحلي، ورصيد السيناريو {scenario}%. الفرق {change} نقطة مئوية."},"Why the number changes":{"ro":"De ce se schimbă numărul","ar":"لماذا يتغير الرقم"},"The oil-price control has no effect because the selected price-sensitive revenue share is zero.":{"ro":"Controlul prețului petrolului nu are efect deoarece ponderea selectată a veniturilor sensibile la preț este zero.","ar":"لا يؤثر تغيير سعر النفط لأن حصة الإيرادات الحساسة للسعر المختارة تساوي صفرًا."},"Oil prices change by {price}%, and the assumed sensitive revenue share is {share}%. These assumptions multiply baseline revenue by {factor}; spending stays fixed.":{"ro":"Prețul petrolului se schimbă cu {price}%, iar ponderea presupusă a veniturilor sensibile este {share}%. Ipotezele înmulțesc venitul de referință cu {factor}; cheltuielile rămân fixe.","ar":"يتغير سعر النفط بمقدار {price}%، وتبلغ حصة الإيرادات الحساسة المفترضة {share}%. تضرب هذه الافتراضات الإيرادات المرجعية في {factor}؛ وتبقى النفقات ثابتة."},"How this method performed in the saved experiment":{"ro":"Cum s-a comportat metoda în experimentul salvat","ar":"أداء هذه الطريقة في التجربة المحفوظة"},"{model} has MAE {mae} and RMSE {rmse} trillion IQD across {months} test months. {best_mae} has the lowest MAE; {best_rmse} has the lowest RMSE in this saved comparison.":{"ro":"{model} are MAE {mae} și RMSE {rmse} trilioane IQD pentru {months} luni de test. {best_mae} are cel mai mic MAE; {best_rmse} are cel mai mic RMSE în această comparație salvată.","ar":"تبلغ MAE للطريقة {model} مقدار {mae} وRMSE مقدار {rmse} تريليون دينار عراقي عبر {months} شهرًا للاختبار. تسجل {best_mae} أقل MAE، وتسجل {best_rmse} أقل RMSE في هذه المقارنة المحفوظة."},"These are revised-data test results. They do not establish the best method for future unseen data.":{"ro":"Acestea sunt rezultate de test pe date revizuite. Nu stabilesc cea mai bună metodă pentru date viitoare necunoscute.","ar":"هذه نتائج اختبار على بيانات منقحة، ولا تحدد أفضل طريقة للبيانات المستقبلية غير المعروفة."},"These error scores need a comparability check":{"ro":"Scorurile de eroare necesită verificarea comparabilității","ar":"تحتاج درجات الخطأ إلى فحص قابلية المقارنة"},"The methods do not all have complete forecasts for the same number of targets. I will not declare a winner from this table.":{"ro":"Nu toate metodele au prognoze complete pentru același număr de ținte. Nu voi declara un câștigător pe baza acestui tabel.","ar":"لا تملك جميع الطرق تنبؤات مكتملة للعدد نفسه من الأهداف. لن أعلن طريقة فائزة من هذا الجدول."},"Read the prediction together with its uncertainty":{"ro":"Citește prognoza împreună cu incertitudinea ei","ar":"اقرأ التنبؤ مع عدم اليقين فيه"},"The saved {model} prediction for {target} is {prediction} trillion IQD, with a conditional 95% interval from {low} to {high}. Its history ends in {origin}.":{"ro":"Prognoza salvată {model} pentru {target} este {prediction} trilioane IQD, cu un interval condiționat de 95% între {low} și {high}. Istoricul folosit se încheie în {origin}.","ar":"يبلغ التنبؤ المحفوظ للطريقة {model} لفترة {target} مقدار {prediction} تريليون دينار عراقي، مع فاصل شرطي بنسبة 95% من {low} إلى {high}. ينتهي السجل المستخدم في {origin}."},"This is a saved model prediction, not an observed result or a freshly updated forecast.":{"ro":"Aceasta este o prognoză salvată a modelului, nu o observație sau o prognoză actualizată acum.","ar":"هذا تنبؤ نموذج محفوظ، وليس نتيجة مشاهدة أو تنبؤًا محدثًا الآن."},"The interval depends on model assumptions and does not capture every structural shock or source revision.":{"ro":"Intervalul depinde de ipotezele modelului și nu include fiecare șoc structural sau revizuire a sursei.","ar":"يعتمد الفاصل على افتراضات النموذج، ولا يشمل كل صدمة هيكلية أو مراجعة للمصدر."},"The interval extends below zero because this model is unconstrained.":{"ro":"Intervalul ajunge sub zero deoarece modelul nu este constrâns.","ar":"يمتد الفاصل إلى أقل من الصفر لأن هذا النموذج غير مقيد."},"Choose what similarity should mean":{"ro":"Alege cum definești similitudinea","ar":"اختر كيف تعرف التشابه"},"At least one feature needs a positive weight before I can rank the countries.":{"ro":"Cel puțin o caracteristică trebuie să aibă o pondere pozitivă înainte de a ordona țările.","ar":"يحتاج مؤشر واحد على الأقل إلى وزن موجب لترتيب البلدان."},"How the selected weights shape the nearest match":{"ro":"Cum influențează ponderile alese cel mai apropiat profil","ar":"كيف تحدد الأوزان المختارة أقرب ملف"},"{country} is the nearest loaded country, with distance {distance}. {feature} contributes {contribution}% of its squared distance. The comparison baseline remains 2003–2007.":{"ro":"{country} este cea mai apropiată țară din set, cu distanța {distance}. {feature} contribuie cu {contribution}% la distanța sa pătratică. Perioada de referință rămâne 2003–2007.","ar":"{country} هو أقرب بلد ضمن المجموعة، بمسافة {distance}. يسهم {feature} بمقدار {contribution}% من مربع المسافة. تبقى فترة المقارنة المرجعية 2003–2007."},"{country} matches Iraq's measured baseline features at this numerical precision.":{"ro":"{country} corespunde caracteristicilor măsurate ale Irakului la această precizie numerică.","ar":"تطابق خصائص {country} خصائص العراق المقاسة في الفترة المرجعية عند هذه الدقة العددية."},"Features are standardized before their distances are weighted.":{"ro":"Caracteristicile sunt standardizate înainte de ponderarea distanțelor.","ar":"توضع المؤشرات على مقياس موحد قبل ترجيح مسافاتها."},"Nearest in this selected set does not mean a causal control country or an explanation of development differences.":{"ro":"Cea mai apropiată țară din acest set nu este automat un control cauzal și nu explică diferențele de dezvoltare.","ar":"لا يعني أقرب بلد في هذه المجموعة أنه بلد ضابط سببي أو أنه يفسر فروق التنمية."},"Saved {model} · MAE {mae} over {months} test months. History ends in {origin}.":{"ro":"{model} salvat · MAE {mae} pentru {months} luni de test. Istoricul se încheie în {origin}.","ar":"نموذج {model} محفوظ · MAE بقيمة {mae} عبر {months} شهرًا للاختبار. ينتهي السجل في {origin}."},"Inflation":{"ro":"Inflație","ar":"التضخم"},"Government debt":{"ro":"Datoria publică","ar":"الدين الحكومي"},"Budget balance":{"ro":"Soldul bugetar","ar":"رصيد الموازنة"},"Selected projection year: {year}":{"ro":"Anul proiecției selectate: {year}","ar":"سنة التوقع المختارة: {year}"},"% of employment within each group · 2021 survey":{"ro":"% din ocuparea fiecărui grup · ancheta din 2021","ar":"% من العاملين داخل كل فئة · مسح 2021"},"1 month ahead":{"ro":"La o lună înainte","ar":"بعد شهر واحد"},"2016 spring":{"ro":"primăvara 2016","ar":"ربيع 2016"},"2022 spring":{"ro":"primăvara 2022","ar":"ربيع 2022"},"3 months ahead":{"ro":"La trei luni înainte","ar":"بعد ثلاثة أشهر"},"6 months ahead":{"ro":"La șase luni înainte","ar":"بعد ستة أشهر"},"A change in expenditure, with baseline GDP held fixed.":{"ro":"O modificare a cheltuielilor, cu PIB-ul de bază menținut fix.","ar":"تغيير الإنفاق مع تثبيت الناتج المحلي الإجمالي الأساسي."},"A discrepancy is a question to check, not an audit finding":{"ro":"O diferență este o întrebare de verificat, nu o constatare de audit","ar":"الفرق يستدعي التحقق، وليس نتيجة تدقيق"},"A measurement framework does not supply an Iraq monthly shadow-economy dataset. The existing app cannot derive hidden production from a budget residual.":{"ro":"Un cadru de măsurare nu oferă o serie lunară a economiei ascunse din Irak. Aplicația nu poate deduce producția ascunsă dintr-un reziduu bugetar.","ar":"إطار القياس لا يوفر بيانات شهرية للاقتصاد الخفي في العراق. لا يمكن للتطبيق استنتاج الإنتاج الخفي من فرق في الحسابات المالية."},"A model I can":{"ro":"Un model pe care îl pot","ar":"نموذج أستطيع"},"A separate change in the revenue outside the sensitive share.":{"ro":"O modificare separată a veniturilor din afara ponderii sensibile.","ar":"تغيير منفصل في الإيرادات خارج الحصة الحساسة."},"ANNUAL GDP MODEL":{"ro":"MODEL ANUAL AL PIB-ULUI","ar":"نموذج سنوي للناتج المحلي الإجمالي"},"Agriculture":{"ro":"Agricultură","ar":"الزراعة"},"All employed persons":{"ro":"Toate persoanele ocupate","ar":"جميع العاملين"},"Amount":{"ro":"Valoare","ar":"القيمة"},"An IMF working paper compares survey and national-account approaches with indirect currency-demand and MIMIC methods for estimating the shadow economy.":{"ro":"Un document de lucru al FMI compară anchetele și conturile naționale cu metode indirecte bazate pe cererea de numerar și MIMIC pentru estimarea economiei ascunse.","ar":"تقارن ورقة عمل لصندوق النقد الدولي المسوح والحسابات القومية بالطرق غير المباشرة، ومنها الطلب على النقد وMIMIC، لتقدير الاقتصاد الخفي."},"Annual pattern checks":{"ro":"Verificarea tiparelor anuale","ar":"فحص الأنماط السنوية"},"April 2026":{"ro":"Aprilie 2026","ar":"أبريل 2026"},"CBI monthly statistical bulletin, fiscal sheet 6-1":{"ro":"Buletinul statistic lunar CBI, foaia fiscală 6-1","ar":"النشرة الإحصائية الشهرية للبنك المركزي العراقي، الجدول المالي 6-1"},"CHOSEN ON VALIDATION":{"ro":"ALES PE VALIDARE","ar":"اختير على بيانات التحقق"},"Capital / investment spending":{"ro":"Cheltuieli de capital / investiții","ar":"الإنفاق الرأسمالي / الاستثماري"},"Central Bank of Iraq":{"ro":"Banca Centrală a Irakului","ar":"البنك المركزي العراقي"},"Chapter 4, Table 9 and Figure 11 · printed pages 27–28.":{"ro":"Capitolul 4, Tabelul 9 și Figura 11 · paginile tipărite 27–28.","ar":"الفصل 4، الجدول 9 والشكل 11 · الصفحتان المطبوعتان 27–28."},"Children minus published parent: {amount} trillion IQD. Published rounding is shown without changing the source values.":{"ro":"Suma componentelor minus totalul publicat: {amount} trilioane IQD. Rotunjirea rămâne vizibilă, fără modificarea valorilor sursei.","ar":"مجموع المكونات ناقص الإجمالي المنشور: {amount} تريليون دينار. يظهر أثر التقريب دون تعديل قيم المصدر."},"Choose a source release or compare revisions. These are IMF projections, separate from my models and the April scenario baseline.":{"ro":"Alege o ediție a sursei sau compară revizuirile. Acestea sunt proiecții FMI, separate de modelele mele și de baza scenariilor din aprilie.","ar":"اختر إصدار المصدر أو قارن المراجعات. هذه توقعات صندوق النقد الدولي، منفصلة عن نماذجي وخط أساس سيناريوهات أبريل."},"Compare releases":{"ro":"Compară edițiile","ar":"مقارنة الإصدارين"},"Completed account year":{"ro":"Anul complet al conturilor","ar":"السنة المكتملة للحسابات"},"Component":{"ro":"Componentă","ar":"المكوّن"},"Conditional coefficients · HAC lag 1 intervals":{"ro":"Coeficienți condiționali · intervale HAC cu lag 1","ar":"معاملات مشروطة · فترات HAC بإبطاء واحد"},"Context for 2021, reported in 2022. Estimates and projections in the same report must retain their different status.":{"ro":"Context pentru 2021, raportat în 2022. Estimările și proiecțiile din același raport își păstrează statutul distinct.","ar":"هذا سياق عام 2021 ورد في تقرير 2022. تظل التقديرات والتوقعات في التقرير متميزة في نوعها."},"Current spending":{"ro":"Cheltuieli curente","ar":"الإنفاق الجاري"},"DEFINITIONS / DATED EVIDENCE":{"ro":"DEFINIȚII / DOVEZI DATATE","ar":"تعريفات / أدلة مؤرخة"},"Different transaction rates are not interchangeable. This announcement supplies no continuous parallel-market series and does not establish the effect on any selected chart.":{"ro":"Ratele pentru tranzacții diferite nu sunt interschimbabile. Anunțul nu oferă o serie continuă a pieței paralele și nu stabilește efectul asupra graficului selectat.","ar":"لا يمكن استبدال أسعار المعاملات المختلفة بعضها ببعض. الإعلان لا يوفر سلسلة مستمرة للسوق الموازية ولا يثبت أثرًا على الرسم المختار."},"EVIDENCE CONTEXT":{"ro":"CONTEXT ȘI DOVEZI","ar":"السياق والأدلة"},"Earlier validation":{"ro":"Validare anterioară","ar":"تحقق سابق"},"Economic activity":{"ro":"Activitate economică","ar":"النشاط الاقتصادي"},"Estimate":{"ro":"Estimare","ar":"التقدير"},"Evaluation stage":{"ro":"Etapa evaluării","ar":"مرحلة التقييم"},"Export-quantity change":{"ro":"Modificarea cantității exportate","ar":"تغير كمية الصادرات"},"Female":{"ro":"Femei","ar":"الإناث"},"Fiscal expansion starting in 2023":{"ro":"Expansiunea fiscală începută în 2023","ar":"التوسع المالي الذي بدأ في 2023"},"Forecast horizon":{"ro":"Orizontul prognozei","ar":"أفق التنبؤ"},"Four completed CBI years, 2022–2025. The 2024 and 2025 totals use December cumulative accounts. These preliminary, revisable figures stay separate from the IMF perimeter and projections.":{"ro":"Patru ani CBI încheiați, 2022–2025. Totalurile din 2024 și 2025 folosesc conturile cumulative din decembrie. Aceste valori preliminare și revizuibile rămân separate de perimetrul și proiecțiile FMI.","ar":"أربع سنوات مكتملة من حسابات البنك المركزي، 2022–2025. تستخدم قيمتا 2024 و2025 حسابات ديسمبر التراكمية. هذه أرقام أولية قابلة للمراجعة، منفصلة عن نطاق حسابات الصندوق وتوقعاته."},"GROWTH MODEL":{"ro":"MODELUL DE CREȘTERE","ar":"نموذج النمو"},"Goods and services":{"ro":"Bunuri și servicii","ar":"السلع والخدمات"},"Group comparison":{"ro":"Comparația grupurilor","ar":"مقارنة الفئات"},"Held-out test":{"ro":"Test separat","ar":"اختبار منفصل"},"How certain is this?":{"ro":"Cât de sigur este rezultatul?","ar":"ما درجة اليقين؟"},"How researchers estimate hidden economic activity":{"ro":"Cum estimează cercetătorii activitatea economică ascunsă","ar":"كيف يقدّر الباحثون النشاط الاقتصادي الخفي"},"IMF Article IV 2025, Table 2. Select one level of the hierarchy; parent totals are not additional spending.":{"ro":"Raportul FMI Articolul IV 2025, Tabelul 2. Alege un singur nivel al ierarhiei; totalurile părinte nu reprezintă cheltuieli suplimentare.","ar":"تقرير مشاورات المادة الرابعة للصندوق لعام 2025، الجدول 2. اختر مستوى واحدًا من التصنيف؛ الإجماليات الأعلى ليست إنفاقًا إضافيًا."},"IMF WEO":{"ro":"FMI WEO","ar":"آفاق الاقتصاد العالمي للصندوق"},"Industry":{"ro":"Industrie","ar":"الصناعة"},"Informal employment":{"ro":"Ocupare informală","ar":"العمالة غير المنظمة"},"Informal work, unpaid obligations and measurement methods have different sources and definitions.":{"ro":"Munca informală, obligațiile neachitate și metodele de măsurare au surse și definiții diferite.","ar":"العمل غير المنظم والالتزامات غير المدفوعة وطرق القياس لها مصادر وتعريفات مختلفة."},"Informal work: the 2021 survey":{"ro":"Munca informală: ancheta din 2021","ar":"العمل غير المنظم: مسح 2021"},"Informal-sector employment":{"ro":"Ocupare în sectorul informal","ar":"العمالة في القطاع غير المنظم"},"Inspect the growth model":{"ro":"Examinează modelul de creștere","ar":"فحص نموذج النمو"},"Interest payments":{"ro":"Plăți de dobânzi","ar":"مدفوعات الفائدة"},"International Monetary Fund":{"ro":"Fondul Monetar Internațional","ar":"صندوق النقد الدولي"},"Jobs and economic production need different measurements":{"ro":"Locurile de muncă și producția economică cer măsurători diferite","ar":"الوظائف والإنتاج الاقتصادي يحتاجان إلى مقاييس مختلفة"},"MEASUREMENTS AND CONTEXT":{"ro":"MĂSURĂTORI ȘI CONTEXT","ar":"القياسات والسياق"},"METHOD / BENCHMARKS / LIMITS":{"ro":"METODĂ / REPERE / LIMITE","ar":"الطريقة / المقارنات المرجعية / الحدود"},"Male":{"ro":"Bărbați","ar":"الذكور"},"Meaning, next checks and confidence":{"ro":"Sens, verificări următoare și încredere","ar":"المعنى والتحقق التالي ودرجة الثقة"},"Method, coefficients and model assessment":{"ro":"Metodă, coeficienți și evaluarea modelului","ar":"الطريقة والمعاملات وتقييم النموذج"},"Model MAE in percentage points. The expanding-mean benchmark has MAE {mae}; the multivariate model did not beat it.":{"ro":"MAE al modelului, în puncte procentuale. Reperul bazat pe media cumulativă are MAE {mae}; modelul multivariat nu l-a depășit.","ar":"متوسط الخطأ المطلق للنموذج بالنقاط المئوية. للمقارنة المرجعية القائمة على المتوسط المتوسع خطأ قدره {mae}؛ لم يتفوق عليها النموذج متعدد المتغيرات."},"New official dollar rates take effect":{"ro":"Intră în vigoare noile cursuri oficiale ale dolarului","ar":"بدء العمل بأسعار الدولار الرسمية الجديدة"},"No numerical Iraq shadow-economy series has been validated or imported into this application. This reference explains methods; it is not a corruption detector or a monthly measure.":{"ro":"Nicio serie numerică a economiei ascunse din Irak nu a fost validată sau importată. Referința explică metode, nu detectează corupția și nu oferă o măsură lunară.","ar":"لم تُعتمد أو تُستورد سلسلة رقمية للاقتصاد الخفي في العراق. المرجع يشرح طرق القياس، ولا يكشف الفساد ولا يقدم قياسًا شهريًا."},"Non-oil investment spending":{"ro":"Investiții în afara sectorului petrolier","ar":"الإنفاق الاستثماري غير النفطي"},"October 2026":{"ro":"Octombrie 2026","ar":"أكتوبر 2026"},"October minus April: {change} percentage points.":{"ro":"Octombrie minus aprilie: {change} puncte procentuale.","ar":"أكتوبر ناقص أبريل: {change} نقطة مئوية."},"Oil and security shocks in the second half of 2014":{"ro":"Șocuri petroliere și de securitate în a doua jumătate a lui 2014","ar":"صدمات النفط والأمن في النصف الثاني من 2014"},"Oil channels in the full Python application":{"ro":"Canalele petroliere în aplicația Python completă","ar":"مسارات النفط في تطبيق Python الكامل"},"Oil investment spending":{"ro":"Investiții în sectorul petrolier","ar":"الإنفاق الاستثماري النفطي"},"Other-revenue change":{"ro":"Modificarea altor venituri","ar":"تغير الإيرادات الأخرى"},"Pandemic and oil-revenue shock in 2020":{"ro":"Pandemia și șocul veniturilor petroliere din 2020","ar":"الجائحة وصدمة الإيرادات النفطية في 2020"},"Parent and child rows must not be added together. State-enterprise transfers are an of-which subset. Spending does not measure completed infrastructure or effectiveness.":{"ro":"Nu aduna totalurile părinte cu componentele lor. Transferurile către întreprinderile de stat sunt un subgrup. Cheltuielile nu măsoară infrastructura finalizată sau eficiența.","ar":"لا تجمع الإجماليات العليا مع مكوناتها. تحويلات الشركات الحكومية جزء من التحويلات. الإنفاق لا يقيس البنية التحتية المكتملة أو الفاعلية."},"Pensions":{"ro":"Pensii","ar":"المعاشات"},"Printed page 26; PDF page 31. The accounting perimeter differs from the CBI totals.":{"ro":"Pagina tipărită 26; pagina PDF 31. Perimetrul contabil diferă de totalurile CBI.","ar":"الصفحة المطبوعة 26؛ صفحة PDF 31. يختلف النطاق المحاسبي عن إجماليات البنك المركزي."},"Published parent total":{"ro":"Totalul părinte publicat","ar":"الإجمالي الأعلى المنشور"},"Quarterly publications are being reconciled. Four comparable 2025 quarters are not a continuous accepted model dataset.":{"ro":"Publicațiile trimestriale sunt în curs de reconciliere. Patru trimestre comparabile din 2025 nu formează o serie continuă acceptată pentru model.","ar":"تجري مطابقة المنشورات الفصلية. أربعة فصول قابلة للمقارنة لعام 2025 لا تشكل سلسلة مستمرة معتمدة للنموذج."},"Recorded revenue":{"ro":"Venituri înregistrate","ar":"الإيرادات المسجلة"},"Recorded spending":{"ro":"Cheltuieli înregistrate","ar":"الإنفاق المسجل"},"Recovery and higher oil revenue in 2021":{"ro":"Redresare și venituri petroliere mai mari în 2021","ar":"التعافي وارتفاع الإيرادات النفطية في 2021"},"Revenue − spending = balance. A shortfall is not an amount of stolen money. These accounts can be revised.":{"ro":"Venituri − cheltuieli = sold. Un deficit nu reprezintă o sumă furată. Aceste conturi pot fi revizuite.","ar":"الإيرادات − الإنفاق = الرصيد. العجز ليس مبلغًا مسروقًا. يمكن مراجعة هذه الحسابات."},"Salaries":{"ro":"Salarii","ar":"الرواتب"},"Salaries and pensions":{"ro":"Salarii și pensii","ar":"الرواتب والمعاشات"},"Same eight test years · 2018–2025":{"ro":"Aceiași opt ani de test · 2018–2025","ar":"نفس سنوات الاختبار الثماني · 2018–2025"},"Saved 2026 estimate · conditional":{"ro":"Estimare salvată pentru 2026 · condițională","ar":"تقدير محفوظ لعام 2026 · مشروط"},"Saved conditional estimate":{"ro":"Estimare condițională salvată","ar":"تقدير مشروط محفوظ"},"Scenario year":{"ro":"Anul scenariului","ar":"سنة السيناريو"},"Selected annual government accounts":{"ro":"Conturi anuale guvernamentale selectate","ar":"حسابات حكومية سنوية مختارة"},"Selected annual money flow":{"ro":"Fluxul monetar anual selectat","ar":"التدفق المالي السنوي المختار"},"Selected on earlier validation: {model}. This table shows {stage} targets {start}–{end}.":{"ro":"Ales pe validarea anterioară: {model}. Tabelul arată ținte pentru {stage}, {start}–{end}.","ar":"اختير على التحقق السابق: {model}. يعرض الجدول أهداف {stage}، {start}–{end}."},"Separate from the monthly revenue experiment and the IMF source outlook.":{"ro":"Separat de experimentul lunar privind veniturile și de perspectiva FMI.","ar":"منفصل عن تجربة الإيرادات الشهرية وتوقعات الصندوق."},"Services":{"ro":"Servicii","ar":"الخدمات"},"Sex":{"ro":"Sex","ar":"الجنس"},"Share of selected total":{"ro":"Pondere în totalul selectat","ar":"الحصة من الإجمالي المختار"},"Source and limits":{"ro":"Sursă și limite","ar":"المصدر والحدود"},"Source published: {period}":{"ro":"Sursă publicată: {period}","ar":"تاريخ نشر المصدر: {period}"},"Source release":{"ro":"Ediția sursei","ar":"إصدار المصدر"},"Source year":{"ro":"Anul sursei","ar":"سنة المصدر"},"Spending change":{"ro":"Modificarea cheltuielilor","ar":"تغير الإنفاق"},"Spending level":{"ro":"Nivelul cheltuielilor","ar":"مستوى تصنيف الإنفاق"},"Spending recorded in cash can miss unpaid obligations":{"ro":"Cheltuielile înregistrate în numerar pot omite obligațiile neachitate","ar":"الإنفاق النقدي المسجل قد لا يشمل الالتزامات غير المدفوعة"},"Survey measure":{"ro":"Indicatorul anchetei","ar":"مقياس المسح"},"Target year {year} · conditional 95% interval {low}% to {high}%.":{"ro":"An-țintă {year} · interval condițional de 95%: {low}% până la {high}%.","ar":"السنة المستهدفة {year} · فترة مشروطة 95% من {low}% إلى {high}%."},"Term":{"ro":"Termen","ar":"المتغير"},"The CBI announcement dated 7 February 2023 says the new rates apply from 8 February: 1300 IQD/USD for Ministry of Finance purchases, 1310 for platform sales to banks and 1320 for end users.":{"ro":"Anunțul CBI din 7 februarie 2023 precizează că noile cursuri se aplică din 8 februarie: 1300 IQD/USD pentru cumpărările Ministerului Finanțelor, 1310 pentru vânzările pe platformă către bănci și 1320 pentru utilizatorii finali.","ar":"ينص إعلان البنك المركزي في 7 فبراير 2023 على سريان الأسعار الجديدة من 8 فبراير: 1300 دينار للدولار لمشتريات وزارة المالية، و1310 لمبيعات المنصة إلى البنوك، و1320 للمستخدمين النهائيين."},"The IMF passage is an account of authorities' views, not an individual audit finding. A residual can reflect timing, definitions, revisions, missing accounts or unpaid obligations. This application cannot identify theft or a recipient from aggregate accounts.":{"ro":"Pasajul FMI redă opiniile autorităților, nu o constatare individuală de audit. Un reziduu poate reflecta momentul înregistrării, definiții, revizuiri, conturi lipsă sau obligații neachitate. Aplicația nu poate identifica furtul ori un beneficiar din conturi agregate.","ar":"يعرض نص الصندوق آراء السلطات، وليس نتيجة تدقيق فردية. قد تعكس الفروق التوقيت أو التعريفات أو المراجعات أو حسابات ناقصة أو التزامات غير مدفوعة. لا يستطيع التطبيق تحديد سرقة أو مستفيد من حسابات إجمالية."},"The IMF report records authorities' discussion of stronger public-financial management, audits and enforcement. This app currently contains no individual audited loss or theft finding.":{"ro":"Raportul FMI consemnează discuțiile autorităților despre consolidarea gestiunii finanțelor publice, audituri și aplicarea regulilor. Aplicația nu conține constatări individuale de audit privind pierderi sau furt.","ar":"يسجل تقرير الصندوق مناقشة السلطات لتعزيز إدارة المال العام والتدقيق وإنفاذ القواعد. لا يتضمن التطبيق نتائج تدقيق فردية بشأن خسائر أو سرقة."},"The IMF's 2020 consultation, published in February 2021, describes pandemic pressures and a sharp decline in oil revenues during 2020.":{"ro":"Consultarea FMI pentru 2020, publicată în februarie 2021, descrie presiunile pandemiei și scăderea puternică a veniturilor petroliere în 2020.","ar":"تصف مشاورات الصندوق لعام 2020، المنشورة في فبراير 2021، ضغوط الجائحة والانخفاض الحاد في الإيرادات النفطية خلال 2020."},"The IMF's 2021 measurement paper proposes a framework for informal production that is consistent with national-account concepts.":{"ro":"Documentul FMI din 2021 propune un cadru de măsurare a producției informale compatibil cu conceptele conturilor naționale.","ar":"تقترح ورقة الصندوق لعام 2021 إطارًا لقياس الإنتاج غير المنظم متوافقًا مع مفاهيم الحسابات القومية."},"The IMF's 2024 consultation describes a large fiscal expansion starting in 2023 under Iraq's three-year budget.":{"ro":"Consultarea FMI din 2024 descrie o expansiune fiscală amplă începută în 2023, în cadrul bugetului pe trei ani al Irakului.","ar":"تصف مشاورات الصندوق لعام 2024 توسعًا ماليًا كبيرًا بدأ في 2023 ضمن موازنة العراق لثلاث سنوات."},"The IMF's 2025 report discusses arrears accumulation in 2024 and financing and budget-execution constraints.":{"ro":"Raportul FMI din 2025 discută acumularea arieratelor în 2024 și constrângerile de finanțare și execuție bugetară.","ar":"يناقش تقرير الصندوق لعام 2025 تراكم المتأخرات في 2024 وقيود التمويل وتنفيذ الموازنة."},"The IMF's 2025 report says Iraq accumulated substantial domestic arrears in 2024, including obligations for fuel, electricity and capital expenditure, amid financing constraints.":{"ro":"Raportul FMI din 2025 arată că Irakul a acumulat arierate interne importante în 2024, inclusiv obligații pentru combustibil, electricitate și investiții, pe fondul constrângerilor de finanțare.","ar":"يفيد تقرير الصندوق لعام 2025 بأن العراق راكم متأخرات محلية كبيرة في 2024، منها التزامات للوقود والكهرباء والإنفاق الرأسمالي، وسط قيود التمويل."},"The World Bank's Spring 2016 outlook describes simultaneous oil-price and ISIS-related shocks beginning in the second half of 2014.":{"ro":"Perspectiva Băncii Mondiale din primăvara 2016 descrie șocuri simultane legate de prețul petrolului și de ISIS, începând din a doua jumătate a lui 2014.","ar":"تصف توقعات البنك الدولي لربيع 2016 صدمات متزامنة لأسعار النفط وللأوضاع المرتبطة بداعش، بدأت في النصف الثاني من 2014."},"The World Bank's Spring 2022 monitor describes a 2021 recovery with eased movement restrictions, changing oil-production conditions and higher oil revenue.":{"ro":"Monitorul Băncii Mondiale din primăvara 2022 descrie redresarea din 2021, relaxarea restricțiilor de circulație, schimbarea condițiilor producției petroliere și creșterea veniturilor din petrol.","ar":"يصف تقرير البنك الدولي لربيع 2022 تعافي 2021 مع تخفيف قيود الحركة وتغير ظروف إنتاج النفط وارتفاع الإيرادات النفطية."},"The annual period contains several shocks. A February 2021 assessment must not be treated as information known throughout 2020.":{"ro":"Perioada anuală cuprinde mai multe șocuri. O evaluare din februarie 2021 nu trebuie tratată ca informație disponibilă pe tot parcursul lui 2020.","ar":"تشمل السنة عدة صدمات. لا يجوز اعتبار تقييم فبراير 2021 معلومات كانت متاحة طوال عام 2020."},"The assumed quantity change in the affected oil revenue.":{"ro":"Modificarea presupusă a cantității pentru veniturile petroliere afectate.","ar":"التغير المفترض في الكمية المرتبطة بالإيرادات النفطية المتأثرة."},"The assumptions describe an accounting scenario, not its likelihood. The balancing threshold solves the same equation; it does not predict a market oil price.":{"ro":"Ipotezele descriu un scenariu contabil, nu probabilitatea lui. Pragul de echilibrare rezolvă aceeași ecuație; nu prezice un preț de piață al petrolului.","ar":"تصف الافتراضات سيناريو محاسبيًا، وليس احتماله. يحل حد التوازن المعادلة نفسها؛ ولا يتنبأ بسعر النفط في السوق."},"The candidate has only 18 complete annual level rows, sensitive integration and cointegration checks, and unresolved source comparability. It failed the current model gates; this does not establish that VECM is impossible for Iraq.":{"ro":"Candidatul are doar 18 observații anuale complete de nivel, teste sensibile de integrare și cointegrare și comparabilitate nerezolvată a surselor. Nu a trecut criteriile curente; aceasta nu dovedește că VECM este imposibil pentru Irak.","ar":"للنموذج المرشح 18 مشاهدة سنوية مكتملة فقط، مع فحوص حساسة للتكامل والتكامل المشترك ومقارنة مصادر غير محسومة. لم يجتز الشروط الحالية؛ وهذا لا يثبت استحالة VECM للعراق."},"The detailed survey text gives 54.8%; its executive summary gives 54.9%. This view preserves the detailed figure and locator.":{"ro":"Textul detaliat al anchetei indică 54,8%, iar rezumatul executiv 54,9%. Această vizualizare păstrează valoarea detaliată și referința exactă.","ar":"يعطي النص التفصيلي للمسح 54.8%، بينما يعطي الملخص التنفيذي 54.9%. يحافظ هذا العرض على الرقم التفصيلي وموضعه في المصدر."},"The fixed annual model uses previous real GDP growth, previous price-adjusted spending-proxy growth and previous world-oil-price growth. The spending proxy is not real government consumption; the oil price is not Iraq’s realised export price.":{"ro":"Modelul anual fix folosește creșterea reală a PIB-ului, creșterea unui indicator aproximativ al cheltuielilor ajustate la prețuri și creșterea prețului mondial al petrolului din anul anterior. Indicatorul cheltuielilor nu este consumul public real; prețul mondial nu este prețul efectiv al exporturilor irakiene.","ar":"يستخدم النموذج السنوي الثابت نمو الناتج الحقيقي ونمو مؤشر تقريبي للإنفاق المعدّل بالأسعار ونمو سعر النفط العالمي من السنة السابقة. مؤشر الإنفاق ليس الاستهلاك الحكومي الحقيقي؛ والسعر العالمي ليس سعر صادرات العراق الفعلي."},"The full Python application separates oil price, export barrels, gross USD value and IQD receipts. Its SOMO coverage is January–April 2026. The browser does not import that raw dataset or assume a validated long-run conversion to government receipts.":{"ro":"Aplicația Python completă separă prețul petrolului, barilii exportați, valoarea brută în USD și încasările în IQD. Acoperirea SOMO este ianuarie–aprilie 2026. Browserul nu importă datele brute și nu presupune o conversie de lungă durată validată către încasări guvernamentale.","ar":"يفصل تطبيق Python الكامل سعر النفط وبراميل التصدير والقيمة الإجمالية بالدولار والإيرادات بالدينار. تغطية سومو هي يناير–أبريل 2026. لا يستورد المتصفح البيانات الخام ولا يفترض تحويلًا طويل الأجل معتمدًا إلى إيرادات الحكومة."},"The methods share 19 origins in each evaluation stage. Selection uses earlier validation MAE; held-out results are reported separately. Multi-month errors can be dependent. The chart uses a saved June 2026 origin.":{"ro":"Metodele au aceleași 19 momente de origine în fiecare etapă. Alegerea folosește MAE pe validarea anterioară; rezultatele testului sunt separate. Erorile la mai multe luni pot fi dependente. Graficul folosește originea salvată din iunie 2026.","ar":"تشترك الطرق في 19 نقطة انطلاق بكل مرحلة تقييم. يعتمد الاختيار على خطأ التحقق السابق؛ وتُعرض نتائج الاختبار منفصلة. قد تعتمد أخطاء الآفاق المتعددة بعضها على بعض. يستخدم الرسم نقطة انطلاق محفوظة في يونيو 2026."},"The multivariate model did not beat the expanding-mean benchmark. Read the evaluation and limits.":{"ro":"Modelul multivariat nu a depășit reperul bazat pe media cumulativă. Citește evaluarea și limitele.","ar":"لم يتفوق النموذج متعدد المتغيرات على المقارنة المرجعية بالمتوسط المتوسع. اقرأ التقييم والحدود."},"The published spending breakdown":{"ro":"Structura publicată a cheltuielilor","ar":"التفصيل المنشور للإنفاق"},"The saved origin ends in June 2026; it is not a fresh forecast. Shaded ranges are conditional model intervals. Simple benchmarks have no supplied intervals, which does not mean zero uncertainty.":{"ro":"Originea salvată se încheie în iunie 2026; nu este o prognoză nouă. Benzile sunt intervale condiționale ale modelului. Reperele simple nu au intervale furnizate, ceea ce nu înseamnă incertitudine zero.","ar":"تنتهي بيانات نقطة الانطلاق المحفوظة في يونيو 2026؛ فهذا ليس تنبؤًا جديدًا. النطاقات فترات مشروطة للنموذج. لا توفر المقارنات البسيطة فترات تنبؤ، وهذا لا يعني انعدام عدم اليقين."},"The scenario keeps the IMF April 2026 baseline.":{"ro":"Scenariul păstrează baza FMI din aprilie 2026.","ar":"يحافظ السيناريو على خط أساس الصندوق من أبريل 2026."},"The sensitive share is an assumption. Price and quantity multiply together; other revenue and spending have separate controls. GDP and the exchange rate remain fixed.":{"ro":"Ponderea sensibilă este o ipoteză. Prețul și cantitatea se înmulțesc; alte venituri și cheltuielile au controale separate. PIB-ul și cursul de schimb rămân fixe.","ar":"الحصة الحساسة افتراض. يُضرب أثر السعر في أثر الكمية؛ وللإيرادات الأخرى والإنفاق ضوابط منفصلة. يظل الناتج وسعر الصرف ثابتين."},"The source describes obligations and financing constraints. It does not identify theft. IMF definitions and estimates must not be silently substituted for CBI cash-account figures.":{"ro":"Sursa descrie obligații și constrângeri de finanțare, nu identifică furtul. Definițiile și estimările FMI nu trebuie substituite implicit cifrelor contabile de numerar ale CBI.","ar":"يصف المصدر التزامات وقيود تمويل، ولا يحدد سرقة. لا ينبغي استبدال أرقام حسابات البنك المركزي النقدية بتعريفات الصندوق وتقديراته دون توضيح."},"These are survey estimates, not GDP shares, lost tax revenue or current monthly conditions. Group differences are not significance tests.":{"ro":"Acestea sunt estimări dintr-o anchetă, nu ponderi în PIB, taxe pierdute sau condiții lunare curente. Diferențele dintre grupuri nu sunt teste de semnificație.","ar":"هذه تقديرات مسح، وليست حصصًا من الناتج أو ضرائب مفقودة أو ظروفًا شهرية راهنة. الفروق بين الفئات ليست اختبارات دلالة إحصائية."},"This entry refers to the year expansion began, not an exact budget-adoption date. Approved allocations must be distinguished from recorded execution.":{"ro":"Intrarea se referă la anul începerii expansiunii, nu la data exactă a adoptării bugetului. Alocările aprobate trebuie separate de execuția înregistrată.","ar":"تشير البطاقة إلى سنة بدء التوسع، لا إلى تاريخ إقرار الموازنة بدقة. يجب تمييز التخصيصات المعتمدة عن التنفيذ المسجل."},"This is a published assessment of 2024, not a finding produced from the selected chart. Different perimeters and accounting bases must remain separate. Arrears do not establish theft.":{"ro":"Este o evaluare publicată despre 2024, nu un rezultat produs din graficul selectat. Perimetrele și bazele contabile diferite rămân separate. Arieratele nu dovedesc furtul.","ar":"هذا تقييم منشور لعام 2024، وليس نتيجة مستخرجة من الرسم المختار. تظل النطاقات والأسس المحاسبية المختلفة منفصلة. المتأخرات لا تثبت سرقة."},"This is a reconstruction saved in October 2026 using later-released 2025 inputs. It could not have been issued at the end of 2025 with these inputs.":{"ro":"Această reconstrucție a fost salvată în octombrie 2026, folosind date pentru 2025 publicate ulterior. Nu putea fi emisă la sfârșitul lui 2025 cu aceste date.","ar":"هذه إعادة بناء حُفظت في أكتوبر 2026 باستخدام بيانات 2025 التي نُشرت لاحقًا. لم يكن ممكنًا إصدارها في نهاية 2025 بهذه المدخلات."},"This is the source's assessment of several overlapping developments, not a causal result produced by this program. The half-year boundaries are a display window, not exact shock dates.":{"ro":"Este evaluarea sursei asupra unor evoluții suprapuse, nu un rezultat cauzal al programului. Limitele semestriale sunt o fereastră de afișare, nu date exacte ale șocurilor.","ar":"هذا تقييم المصدر لتطورات متداخلة، وليس نتيجة سببية للبرنامج. حدود النصف السنوي نافذة عرض وليست تواريخ دقيقة للصدمات."},"Total expenditure":{"ro":"Cheltuieli totale","ar":"إجمالي الإنفاق"},"Transfers":{"ro":"Transferuri","ar":"التحويلات"},"Transfers to state-owned enterprises":{"ro":"Transferuri către întreprinderile de stat","ar":"التحويلات إلى الشركات الحكومية"},"Twenty annual fit observations, 2006–2025. Coefficients describe associations; the non-intercept intervals include zero. Small samples, breaks, proxies and revisions limit interpretation.":{"ro":"Douăzeci de observații anuale pentru estimare, 2006–2025. Coeficienții descriu asocieri; intervalele termenilor fără intercept includ zero. Eșantionul mic, rupturile, indicatorii aproximativi și revizuirile limitează interpretarea.","ar":"عشرون مشاهدة سنوية للتقدير، 2006–2025. تصف المعاملات ارتباطات؛ وتشمل فترات المعاملات غير الثابتة الصفر. تحد العينة الصغيرة والتحولات والمؤشرات التقريبية والمراجعات من التفسير."},"Unpaid obligations discussed for 2024":{"ro":"Obligații neachitate discutate pentru 2024","ar":"الالتزامات غير المدفوعة التي نوقشت لعام 2024"},"VECM: assessed, not accepted":{"ro":"VECM: evaluat, neacceptat","ar":"VECM: خضع للتقييم ولم يُعتمد"},"War reparations":{"ro":"Despăgubiri de război","ar":"تعويضات الحرب"},"What changed?":{"ro":"Ce s-a schimbat?","ar":"ما الذي تغير؟"},"What does it mean?":{"ro":"Ce înseamnă?","ar":"ماذا يعني ذلك؟"},"What should I look into?":{"ro":"Ce ar trebui să verific?","ar":"ما الذي ينبغي أن أفحصه؟"},"What the evidence":{"ro":"Ce îmi pot spune","ar":"ما الذي يمكن"},"World Bank":{"ro":"Banca Mondială","ar":"البنك الدولي"},"World Bank WDI: GDP deflator":{"ro":"WDI Banca Mondială: deflatorul PIB","ar":"مؤشرات البنك الدولي: معامل انكماش الناتج"},"World Bank WDI: total real GDP":{"ro":"WDI Banca Mondială: PIB real total","ar":"مؤشرات البنك الدولي: إجمالي الناتج الحقيقي"},"World Bank world commodity-price snapshot":{"ro":"Seria Băncii Mondiale a prețurilor mondiale ale mărfurilor","ar":"بيانات البنك الدولي لأسعار السلع العالمية"},"can tell me.":{"ro":"dovezile.","ar":"أن تخبرني به الأدلة."},"const":{"ro":"Constantă","ar":"الثابت"},"evaluate.":{"ro":"evalua.","ar":"تقييمه."},"lag_gdp_growth":{"ro":"Creșterea PIB-ului în anul anterior","ar":"نمو الناتج في السنة السابقة"},"lag_real_spending_proxy_growth":{"ro":"Creșterea indicatorului cheltuielilor reale în anul anterior","ar":"نمو مؤشر الإنفاق الحقيقي في السنة السابقة"},"lag_world_oil_growth":{"ro":"Creșterea prețului mondial al petrolului în anul anterior","ar":"نمو سعر النفط العالمي في السنة السابقة"},"trillion IQD":{"ro":"trilioane IQD","ar":"تريليون دينار عراقي"},"Coverage gaps: {country}":{"ro":"Lacune de acoperire: {country}","ar":"فجوات التغطية: {country}"},"{count} selected annual values are unavailable. Gaps break runs and comparisons.":{"ro":"{count} valori anuale selectate nu sunt disponibile. Lacunele întrerup seriile consecutive și comparațiile.","ar":"لا تتوفر {count} قيم سنوية مختارة. تقطع الفجوات التسلسلات والمقارنات."},"A descriptive calculation is not a significance test, a causal finding or a guarantee.":{"ro":"Un calcul descriptiv nu este un test de semnificație, o concluzie cauzală sau o garanție.","ar":"الحساب الوصفي ليس اختبار دلالة أو استنتاجًا سببيًا أو ضمانًا."},"Rules use consecutive observations, break at gaps and compare unusual changes with earlier years only.":{"ro":"Regulile folosesc observații consecutive, se opresc la lacune și compară mișcările neobișnuite doar cu anii anteriori.","ar":"تستخدم القواعد مشاهدات متتالية وتتوقف عند الفجوات وتقارن التغيرات غير المعتادة بالسنوات السابقة فقط."},"A share can change because manufacturing output or total GDP changes. The two amounts need separate checks.":{"ro":"O pondere se poate schimba din cauza producției manufacturiere sau a PIB-ului total. Cele două valori trebuie verificate separat.","ar":"قد تتغير الحصة بسبب إنتاج الصناعة التحويلية أو إجمالي الناتج. يحتاج المقداران إلى فحص منفصل."},"Compare related indicators, common dates and source revisions. Missing years have not been filled.":{"ro":"Compară indicatori înrudiți, date comune și revizuirile sursei. Anii lipsă nu au fost completați.","ar":"قارن المؤشرات المرتبطة والفترات المشتركة ومراجعات المصدر. لم تُملأ السنوات الناقصة."},"A movement to inspect: {country}":{"ro":"O mișcare de verificat: {country}","ar":"تغير يستحق الفحص: {country}"},"In {year}, the annual change was {change} {units}. It stands out against {count} earlier changes under the declared rule.":{"ro":"În {year}, modificarea anuală a fost {change} {units}. Se diferențiază de {count} schimbări anterioare conform regulii declarate.","ar":"في {year} بلغ التغير السنوي {change} {units}. يختلف عن {count} تغيرات سابقة وفق القاعدة المعلنة."},"A direction change: {country}":{"ro":"O schimbare de direcție: {country}","ar":"تغير في الاتجاه: {country}"},"The indicator changed direction in {year}, after two annual changes in the opposite direction. One reversal does not establish a new trend.":{"ro":"Indicatorul și-a schimbat direcția în {year}, după două modificări anuale în sens opus. O singură inversare nu stabilește o tendință nouă.","ar":"تغير اتجاه المؤشر في {year} بعد تغيرين سنويين بالاتجاه المقابل. انعكاس واحد لا يثبت اتجاهًا جديدًا."},"A sustained direction: {country}":{"ro":"O direcție susținută: {country}","ar":"اتجاه مستمر: {country}"},"From {start} to {end}, {count} consecutive annual changes moved in one direction. The total change was {change} {units}.":{"ro":"Între {start} și {end}, {count} modificări anuale consecutive au avut aceeași direcție. Schimbarea totală a fost {change} {units}.","ar":"بين {start} و{end} تحركت {count} تغيرات سنوية متتالية في اتجاه واحد. بلغ التغير الكلي {change} {units}."},"A growth rate describes the change in total real output. A lower positive rate means slower growth; a negative rate means contraction.":{"ro":"Rata de creștere descrie schimbarea producției reale totale. O rată pozitivă mai mică înseamnă încetinire; o rată negativă înseamnă contracție.","ar":"يصف معدل النمو تغير إجمالي الإنتاج الحقيقي. المعدل الموجب الأقل يعني تباطؤًا، والمعدل السالب يعني انكماشًا."},"Oil rents estimate production value less production costs. They are different from government oil receipts.":{"ro":"Rentele petroliere estimează valoarea producției minus costurile de producție. Sunt diferite de încasările guvernamentale din petrol.","ar":"تقدّر الريوع النفطية قيمة الإنتاج ناقص تكاليفه. وهي مختلفة عن الإيرادات النفطية للحكومة."},"Real GDP per person adjusts for prices and population. It is not a typical household income.":{"ro":"PIB-ul real pe persoană ține cont de prețuri și populație. Nu este venitul unei gospodării tipice.","ar":"يراعي الناتج الحقيقي للفرد الأسعار والسكان. ولا يمثل دخل الأسرة النموذجية."},"How these assumptions change the balance":{"ro":"Cum modifică ipotezele soldul","ar":"كيف تغير الافتراضات الرصيد"},"In {year}, the balance moves from {baseline}% to {scenario}% of fixed GDP: {change} percentage points.":{"ro":"În {year}, soldul trece de la {baseline}% la {scenario}% din PIB-ul fix: {change} puncte procentuale.","ar":"في {year} ينتقل الرصيد من {baseline}% إلى {scenario}% من الناتج الثابت: {change} نقطة مئوية."},"This is conditional accounting, not a forecast. GDP, exchange rates, financing and debt dynamics are not simulated.":{"ro":"Acesta este un calcul contabil condițional, nu o prognoză. PIB-ul, cursul de schimb, finanțarea și dinamica datoriei nu sunt simulate.","ar":"هذا حساب محاسبي مشروط، وليس تنبؤًا. لا تُحاكى ديناميكيات الناتج أو سعر الصرف أو التمويل أو الدين."},"A negative budget balance is a shortfall; a positive balance is a surplus. GDP and the exchange rate remain fixed.":{"ro":"Un sold bugetar negativ este un deficit; unul pozitiv este un excedent. PIB-ul și cursul de schimb rămân fixe.","ar":"الرصيد المالي السالب عجز، والموجب فائض. يظل الناتج وسعر الصرف ثابتين."},"Change one assumption at a time, then compare price and quantity together. Review the sensitive revenue share.":{"ro":"Modifică o ipoteză pe rând, apoi compară prețul și cantitatea împreună. Verifică ponderea veniturilor sensibile.","ar":"غيّر افتراضًا واحدًا في كل مرة، ثم قارن السعر والكمية معًا. راجع حصة الإيرادات الحساسة."},"Price and quantity work together":{"ro":"Prețul și cantitatea acționează împreună","ar":"السعر والكمية يعملان معًا"},"The affected revenue factor is (1 + price change) × (1 + quantity change) = {factor}. Other revenue and spending have their own assumptions.":{"ro":"Factorul veniturilor afectate este (1 + modificarea prețului) × (1 + modificarea cantității) = {factor}. Alte venituri și cheltuielile au ipoteze separate.","ar":"معامل الإيرادات المتأثرة هو (1 + تغير السعر) × (1 + تغير الكمية) = {factor}. للإيرادات الأخرى والإنفاق افتراضات منفصلة."},"The sensitive share is an assumption. Gross oil value and recorded government receipts are different measurements.":{"ro":"Ponderea sensibilă este o ipoteză. Valoarea brută a petrolului și încasările guvernamentale înregistrate sunt măsuri diferite.","ar":"الحصة الحساسة افتراض. القيمة الإجمالية للنفط وإيرادات الحكومة المسجلة قياسان مختلفان."},"The price change that balances this budget":{"ro":"Modificarea prețului care echilibrează bugetul","ar":"تغير السعر الذي يوازن الموازنة"},"Under the other selected assumptions, an oil-price change of {price}% would make revenue equal spending.":{"ro":"Cu celelalte ipoteze selectate, o modificare a prețului petrolului de {price}% ar egaliza veniturile și cheltuielile.","ar":"مع بقية الافتراضات المختارة، يساوي تغير سعر النفط بمقدار {price}% بين الإيرادات والإنفاق."},"This is an algebraic threshold, not a market-price prediction or a probability.":{"ro":"Acesta este un prag algebric, nu o predicție a prețului de piață sau o probabilitate.","ar":"هذا حد جبري، وليس توقعًا لسعر السوق أو احتمالًا."},"Changing the oil price cannot balance this budget under the selected assumptions.":{"ro":"Modificarea prețului petrolului nu poate echilibra bugetul cu ipotezele selectate.","ar":"لا يمكن لتغير سعر النفط أن يوازن الموازنة ضمن الافتراضات المختارة."},"A separated forecast evaluation":{"ro":"O evaluare separată a prognozelor","ar":"تقييم منفصل للتنبؤات"},"{model} · {horizon_label}: MAE {mae}, RMSE {rmse} trillion IQD over {count} targets ({start}–{end}). Earlier validation selected {chosen}.":{"ro":"{model} · {horizon_label}: MAE {mae}, RMSE {rmse} trilioane IQD pentru {count} ținte ({start}–{end}). Validarea anterioară a ales {chosen}.","ar":"{model} · {horizon_label}: خطأ مطلق متوسط {mae} وجذر متوسط مربع الخطأ {rmse} تريليون دينار، على {count} أهداف ({start}–{end}). اختار التحقق السابق {chosen}."},"The method is selected on earlier validation data. The held-out table is not used to choose it again.":{"ro":"Metoda este aleasă pe validarea anterioară. Tabelul testului separat nu este folosit pentru a o alege din nou.","ar":"تُختار الطريقة على بيانات التحقق السابقة. لا يُستخدم جدول الاختبار المنفصل لإعادة اختيارها."},"Tests use revised source values and dependent errors. Nineteen targets do not establish future accuracy.":{"ro":"Testele folosesc valori revizuite și erori dependente. Nouăsprezece ținte nu stabilesc precizia viitoare.","ar":"تستخدم الاختبارات قيمًا مراجعة وأخطاء مترابطة. تسعة عشر هدفًا لا تثبت الدقة المستقبلية."},"MAE measures the average size of past errors. RMSE gives large errors more weight. A model interval is conditional uncertainty.":{"ro":"MAE măsoară mărimea medie a erorilor anterioare. RMSE acordă mai multă greutate erorilor mari. Intervalul modelului reprezintă incertitudine condițională.","ar":"يقيس متوسط الخطأ المطلق حجم الأخطاء السابقة. يعطي جذر متوسط مربع الخطأ وزنًا أكبر للأخطاء الكبيرة. فترة النموذج تعبر عن عدم يقين مشروط."},"Compare methods on the same held-out dates, then inspect coverage, residual checks and the saved origin.":{"ro":"Compară metodele pe aceleași date de test separat, apoi verifică acoperirea intervalelor, diagnosticele reziduurilor și originea salvată.","ar":"قارن الطرق على أهداف الاختبار المنفصل نفسها، ثم افحص تغطية الفترات والبواقي ونقطة الانطلاق المحفوظة."},"A dated, conditional estimate":{"ro":"O estimare datată și condițională","ar":"تقدير مؤرخ ومشروط"},"The saved benchmark prediction for {target} is {prediction} trillion IQD. No prediction interval is supplied for this benchmark; this does not mean zero uncertainty.":{"ro":"Predicția salvată a reperului pentru {target} este {prediction} trilioane IQD. Reperul nu are un interval furnizat; aceasta nu înseamnă incertitudine zero.","ar":"التنبؤ المرجعي المحفوظ للفترة {target} هو {prediction} تريليون دينار. لا يوفر المرجع فترة تنبؤ؛ وهذا لا يعني انعدام عدم اليقين."},"This saved origin is not a fresh forecast. The latest actual monthly revenue in the snapshot is June 2026.":{"ro":"Această origine salvată nu este o prognoză nouă. Ultimele venituri lunare observate în instantaneu sunt din iunie 2026.","ar":"نقطة الانطلاق المحفوظة ليست تنبؤًا جديدًا. آخر إيراد شهري مسجل في البيانات هو يونيو 2026."},"Model intervals can extend below zero and omit structural shocks, source revisions and model uncertainty.":{"ro":"Intervalele pot coborî sub zero și omit șocuri structurale, revizuiri ale sursei și incertitudinea modelului.","ar":"قد تمتد الفترات دون الصفر ولا تشمل الصدمات الهيكلية ومراجعات المصادر وعدم يقين اختيار النموذج."},"The saved prediction for {target} is {prediction} trillion IQD, with a conditional 95% interval {low}–{high}. History ends in {origin}.":{"ro":"Predicția salvată pentru {target} este {prediction} trilioane IQD, cu interval condițional de 95% {low}–{high}. Istoricul se încheie în {origin}.","ar":"التنبؤ المحفوظ للفترة {target} هو {prediction} تريليون دينار، بفترة مشروطة 95% من {low} إلى {high}. ينتهي التاريخ في {origin}."},"A scaled, weighted distance is descriptive similarity. It does not make a country a causal control.":{"ro":"Distanța scalată și ponderată reprezintă o similitudine descriptivă. Nu transformă o țară într-un control cauzal.","ar":"المسافة المعيارية الموزونة تشابه وصفي. ولا تجعل البلد مجموعة ضبط سببية."},"Change one weight at a time and inspect its contribution. Read country context separately.":{"ro":"Modifică o pondere pe rând și examinează contribuția sa. Citește separat contextul fiecărei țări.","ar":"غيّر وزنًا واحدًا في كل مرة وافحص مساهمته. اقرأ سياق كل بلد بصورة منفصلة."},"Earlier changes have too little spread: {country}":{"ro":"Modificările anterioare au prea puțină variație: {country}","ar":"التغيرات السابقة قليلة التشتت: {country}"},"A reliable unusual-change score cannot be calculated when the reference spread is zero.":{"ro":"Nu se poate calcula un scor fiabil al mișcării neobișnuite când variația de referință este zero.","ar":"لا يمكن حساب درجة موثوقة لتغير غير معتاد عندما يكون تشتت المرجع صفرًا."},"The budget is already balanced without a price effect.":{"ro":"Bugetul este deja echilibrat fără un efect de preț.","ar":"الموازنة متوازنة بالفعل دون أثر للسعر."},"Observed interval coverage":{"ro":"Acoperirea observată a intervalului","ar":"التغطية المرصودة للفترة"},"The nominal 95% interval covered {covered} of {count} values, with mean total width {width} trillion IQD.":{"ro":"Intervalul nominal de 95% a cuprins {covered} din {count} valori, cu lățime totală medie de {width} trilioane IQD.","ar":"شملت الفترة الاسمية 95% عدد {covered} من {count} قيم، بمتوسط عرض كلي {width} تريليون دينار."},"Coverage in a short saved sample does not validate future 95% coverage.":{"ro":"Acoperirea într-un eșantion salvat scurt nu validează o acoperire viitoare de 95%.","ar":"التغطية في عينة محفوظة قصيرة لا تثبت تغطية مستقبلية بنسبة 95%."},"A saved residual check":{"ro":"O verificare salvată a reziduurilor","ar":"فحص محفوظ للبواقي"},"The 12-lag Ljung–Box check at the saved origin has p-value {value}. This check does not certify the model.":{"ro":"Testul Ljung–Box cu 12 laguri, la originea salvată, are valoarea p {value}. Testul nu certifică modelul.","ar":"لفحص Ljung–Box بإبطاء 12 عند نقطة الانطلاق المحفوظة قيمة احتمالية {value}. هذا الفحص لا يصادق على صحة النموذج."},"Residual checks are conditional diagnostics. Review sample size, source revisions and structural breaks too.":{"ro":"Verificările reziduurilor sunt diagnostice condiționale. Verifică și mărimea eșantionului, revizuirile sursei și rupturile structurale.","ar":"فحوص البواقي تشخيصات مشروطة. راجع أيضًا حجم العينة ومراجعات المصدر والتحولات الهيكلية."},"Annual GDP growth model":{"ro":"Model anual al creșterii PIB-ului","ar":"نموذج سنوي لنمو الناتج المحلي"},"Price {price}%; quantity {volume}%; other revenue {other}%; spending {spending}%. Baseline balance {baseline}%.":{"ro":"Preț {price}%; cantitate {volume}%; alte venituri {other}%; cheltuieli {spending}%. Sold de bază {baseline}%.","ar":"السعر {price}%؛ الكمية {volume}%؛ الإيرادات الأخرى {other}%؛ الإنفاق {spending}%. الرصيد الأساسي {baseline}%."},"Informal employment describes jobs and their formal protection. Informal jobs can exist in formal enterprises.":{"ro":"Ocuparea informală descrie locurile de muncă și protecția lor formală. Locuri de muncă informale pot exista în întreprinderi formale.","ar":"تصف العمالة غير المنظمة الوظائف وحمايتها الرسمية. قد توجد وظائف غير منظمة داخل مؤسسات رسمية."},"Informal-sector employment describes the production unit, using the survey’s enterprise definition.":{"ro":"Ocuparea în sectorul informal descrie unitatea de producție, conform definiției întreprinderii din anchetă.","ar":"تصف العمالة في القطاع غير المنظم وحدة الإنتاج وفق تعريف المنشأة في المسح."},"2024 is explicitly an IMF estimate.":{"ro":"Valoarea pentru 2024 este explicit o estimare FMI.","ar":"بيانات 2024 موسومة صراحة كتقدير للصندوق."},"2023 is historical as published, not a final audited outcome.":{"ro":"Valoarea pentru 2023 este istorică așa cum a fost publicată, nu un rezultat final auditat.","ar":"بيانات 2023 تاريخية كما نُشرت، وليست نتيجة نهائية مدققة."},"Recorded shortfall":{"ro":"Deficit înregistrat","ar":"العجز المسجل"},"Recorded surplus":{"ro":"Excedent înregistrat","ar":"الفائض المسجل"},"IMF Article IV · Table 2":{"ro":"FMI Articolul IV · Tabelul 2","ar":"مشاورات المادة الرابعة للصندوق · الجدول 2"},"Iraq Labour Force Survey 2021":{"ro":"Ancheta forței de muncă din Irak 2021","ar":"مسح القوى العاملة في العراق 2021"},"Read the source":{"ro":"Citește sursa","ar":"قراءة المصدر"},"SOMO source":{"ro":"Sursa SOMO","ar":"مصدر سومو"},"so far.":{"ro":"de până acum.","ar":"حتى الآن."},"The results, so far.":{"ro":"Rezultatele de până acum.","ar":"النتائج حتى الآن."},"01 / WHAT I WANT TO UNDERSTAND":{"ro":"01 / CE VREAU SĂ ÎNȚELEG","ar":"01 / ما أريد فهمه"},"Source-backed context in this period":{"ro":"Context documentat pentru această perioadă","ar":"سياق موثق لهذه الفترة"},"These dated events provide context. Their timing does not establish the cause of a change in the chart.":{"ro":"Aceste evenimente datate oferă context. Momentul lor nu dovedește cauza unei schimbări din grafic.","ar":"توفر هذه الأحداث المؤرخة سياقاً. ولا يثبت توقيتها سبب التغير في الرسم."},"I use Python to check the inputs, prepare the observations and run the experiments. The interface helps me inspect the results and export their evidence. This is just a small taste of what the full application will be able to do.":{"ro":"Folosesc Python pentru a verifica datele, a pregăti observațiile și a rula experimentele. Interfața mă ajută să examinez rezultatele și să export dovezile. Acesta este doar un mic exemplu din ceea ce va putea face aplicația completă.","ar":"أستخدم Python للتحقق من المدخلات وإعداد المشاهدات وتشغيل التجارب. تساعدني الواجهة على فحص النتائج وتصدير أدلتها. وهذه مجرد لمحة بسيطة عما سيتمكن التطبيق الكامل من فعله."},"Try the Python application":{"ro":"Încearcă aplicația Python","ar":"جرّب تطبيق Python"},"Public access coming later.":{"ro":"Accesul public va fi disponibil ulterior.","ar":"سيتاح الوصول العام لاحقاً."},"Public download coming later":{"ro":"Descărcarea publică va fi disponibilă ulterior","ar":"سيتاح التنزيل العام لاحقاً"},"The Python application is not available to the public yet.":{"ro":"Aplicația Python nu este încă disponibilă publicului.","ar":"تطبيق Python غير متاح للجمهور بعد."},"Browse my":{"ro":"Răsfoiește","ar":"تصفح"},"thesis pitch.":{"ro":"prezentarea lucrării mele.","ar":"عرض مشروع تخرجي."},"Choose slide":{"ro":"Alege diapozitivul","ar":"اختر الشريحة"},"My approved thesis title":{"ro":"Titlul aprobat al lucrării mele","ar":"عنوان مشروع تخرجي المعتمد"},"Approved title · coordinator agreed":{"ro":"Titlu aprobat · coordonator confirmat","ar":"عنوان معتمد · موافقة المشرف"},"My thesis title is approved. I will continue refining the methods and scope with my professors.":{"ro":"Titlul lucrării mele este aprobat. Voi continua să îmbunătățesc metodele și domeniul cercetării împreună cu profesorii mei.","ar":"عنوان مشروع تخرجي معتمد. سأواصل تطوير الأساليب ونطاق البحث مع أساتذتي."},"This is a reconstruction saved in October 2026 using later-released 2025 inputs. It could not have been issued at the end of 2025 with these inputs, and does not incorporate new developments during 2026.":{"ro":"Aceasta este o reconstrucție salvată în octombrie 2026, folosind date pentru 2025 publicate ulterior. Nu putea fi emisă la sfârșitul lui 2025 cu aceste date și nu include evoluțiile noi din 2026.","ar":"هذه إعادة بناء حُفظت في أكتوبر 2026 باستخدام مدخلات لعام 2025 صدرت لاحقاً. لم يكن من الممكن إصدارها بنهاية 2025 بهذه المدخلات، وهي لا تتضمن التطورات الجديدة خلال 2026."},"Revised 2025 inputs, saved October 2026; new 2026 developments are not included. Conditional 95% interval {low}% to {high}%. The model did not beat the mean benchmark.":{"ro":"Date revizuite pentru 2025, salvate în octombrie 2026; evoluțiile noi din 2026 nu sunt incluse. Interval condiționat de 95%: {low}%–{high}%. Modelul nu a depășit reperul bazat pe medie.","ar":"مدخلات 2025 منقحة، حُفظت في أكتوبر 2026؛ لا تشمل التطورات الجديدة في 2026. المجال المشروط بنسبة 95% من {low}% إلى {high}%. لم يتفوق النموذج على معيار المتوسط."},"My thesis title is approved: Iraq’s Economic Outlook: Building an Economic Analysis System with Iraq as a Case Study. Professor Uscatu is coordinating the thesis, and I look forward to refining the work with my professors.":{"ro":"Titlul lucrării mele este aprobat: Perspectivele economice ale Irakului: construirea unui sistem de analiză economică având Irakul drept studiu de caz. Profesorul Uscatu coordonează lucrarea și aștept cu interes să o dezvolt împreună cu profesorii mei.","ar":"عنوان مشروع تخرجي معتمد: الآفاق الاقتصادية للعراق: بناء نظام للتحليل الاقتصادي باستخدام العراق كدراسة حالة. يشرف الأستاذ Uscatu على المشروع، وأتطلع إلى تطوير العمل مع أساتذتي."},"My approved thesis title is":{"ro":"Titlul aprobat al lucrării mele este","ar":"عنوان مشروع تخرجي المعتمد هو"},". I confirmed that the full title is approved on 13 October 2026. I am studying Economic Informatics at ASE Bucharest, and I plan to defend in July 2027. The final econometric specification and detailed scope remain for discussion with my professors.":{"ro":". Am confirmat aprobarea titlului complet la 13 octombrie 2026. Studiez Informatică Economică la ASE București și plănuiesc să susțin lucrarea în iulie 2027. Specificația econometrică finală și domeniul detaliat vor fi discutate cu profesorii mei.","ar":". أكدت اعتماد العنوان الكامل في 13 أكتوبر 2026. أدرس المعلوماتية الاقتصادية في أكاديمية الدراسات الاقتصادية في بوخارست، وأخطط للمناقشة في يوليو 2027. سأناقش المواصفات الاقتصادية القياسية النهائية والنطاق التفصيلي مع أساتذتي."},"Following Professor Davidescu's feedback, I have added a more visible national picture of Iraq, international-source projections and a dashboard bringing the results together. I keep separate April and October 2026 IMF releases. The new annual multivariate growth experiment uses previous GDP growth, a previous price-adjusted spending-growth proxy and previous world oil-price growth. It fits 2006–2025 after transformations and lags, within the wider study starting in 2003. It does not outperform the simple expanding-mean benchmark over eight common test years; I show that result and the uncertainty.":{"ro":"În urma feedbackului profesoarei Davidescu, am adăugat o imagine națională mai vizibilă a Irakului, proiecții din surse internaționale și un tablou de bord care reunește rezultatele. Păstrez separat edițiile IMF din aprilie și octombrie 2026. Noul experiment anual multivariat folosește creșterea anterioară a PIB-ului, creșterea anterioară a unui proxy pentru cheltuieli ajustat la prețuri și creșterea anterioară a prețului mondial al petrolului. Estimează perioada 2006–2025 după transformări și decalaje, în cadrul studiului care începe în 2003. Nu depășește reperul simplu bazat pe media cumulativă în opt ani de test comuni; arăt acest rezultat și incertitudinea.","ar":"بعد ملاحظات الأستاذة Davidescu، أضفت صورة وطنية أوضح للعراق وتوقعات من مصادر دولية ولوحة تجمع النتائج. أفصل بين إصداري صندوق النقد الدولي في أبريل وأكتوبر 2026. تستخدم التجربة السنوية متعددة المتغيرات نمو الناتج المحلي السابق ونمو مؤشر تقريبي للإنفاق معدّل بالأسعار ونمو سعر النفط العالمي السابق. تُقدّر الفترة 2006–2025 بعد التحويلات والإبطاءات ضمن الدراسة التي تبدأ في 2003. لم تتفوق على معيار المتوسط التراكمي البسيط خلال ثماني سنوات اختبار مشتركة؛ وأعرض هذه النتيجة وعدم اليقين."},"I also investigated the suggested VECM. The reviewed annual level candidate has only 18 complete years, with inconsistent integration screens and sensitive rank results. The quarterly source investigation found substantial date coverage, but unresolved revisions, mapping and valuation differences. I have documented those problems and guarded the VECM interface rather than presenting an unsupported fit. A harmonised quarterly series and a reviewed specification remain the next requirements for that method.":{"ro":"Am investigat și VECM-ul sugerat. Candidatul anual verificat are numai 18 ani compleți, teste de integrare neuniforme și rezultate sensibile pentru rang. Cercetarea surselor trimestriale a găsit o acoperire mare a datelor, dar și revizuiri și diferențe de mapare și evaluare nerezolvate. Am documentat problemele și am protejat interfața VECM în loc să prezint o estimare nejustificată. O serie trimestrială armonizată și o specificație revizuită rămân următoarele cerințe.","ar":"درست أيضاً نموذج VECM المقترح. تحتوي البيانات السنوية المرشحة التي راجعتها على 18 سنة كاملة فقط، مع اختبارات تكامل غير متسقة ونتائج رتبة حساسة. وجدت الدراسة الفصلية تغطية زمنية واسعة، لكن بقيت مشاكل في التنقيحات والمطابقة والتقييم. وثقت هذه المشاكل وقيّدت واجهة VECM بدلاً من عرض تقدير غير مدعوم. ولا تزال السلسلة الفصلية الموحدة والمواصفات المراجعة متطلبين للخطوة التالية."},"My own explanation idea is now implemented with four questions: what changed, what it means, what to investigate and how certain it is. The dashboard connects reviewed events, declared patterns, account reconciliation, separate spending classifications, the 2021 informal-work survey, price/quantity calculations and one/three/six-month forecast evaluation. This adds useful software behaviour without treating nearby events as causes or accounting discrepancies as theft. My demonstration guide explains the implemented version and its limits.":{"ro":"Ideea mea de explicație este acum implementată prin patru întrebări: ce s-a schimbat, ce înseamnă, ce trebuie investigat și cât de sigur este. Tabloul de bord conectează evenimente verificate, reguli declarate pentru tipare, reconcilierea conturilor, clasificări separate ale cheltuielilor, ancheta din 2021 despre munca informală, calcule preț/cantitate și evaluări ale prognozelor la una, trei și șase luni. Acest lucru adaugă funcții utile fără a trata evenimentele apropiate drept cauze sau discrepanțele contabile drept furt. Ghidul demonstrativ explică versiunea implementată și limitele sale.","ar":"طبقت الآن فكرتي للتفسير عبر أربعة أسئلة: ما الذي تغير، وما معناه، وما الذي يجب بحثه، وما درجة اليقين. تربط اللوحة الأحداث المراجعة وقواعد الأنماط المعلنة وتسوية الحسابات وتصنيفات الإنفاق المنفصلة ومسح العمل غير الرسمي لعام 2021 وحسابات السعر والكمية وتقييم التوقعات لشهر وثلاثة وستة أشهر. يضيف ذلك وظائف مفيدة دون اعتبار الأحداث القريبة أسباباً أو الفروق المحاسبية سرقة. يشرح دليل العرض النسخة المنفذة وحدودها."},", with separate April and October 2026 editions. The labour view uses the":{"ro":", cu ediții separate din aprilie și octombrie 2026. Pentru piața muncii folosesc","ar":"، بإصدارين منفصلين لأبريل وأكتوبر 2026. ويستخدم عرض العمل"},", and spending classifications use the":{"ro":", iar clasificările cheltuielilor folosesc","ar":"، وتستخدم تصنيفات الإنفاق"},"IMF's July 2025 Iraq report":{"ro":"Raportul IMF despre Irak din iulie 2025","ar":"تقرير صندوق النقد الدولي عن العراق في يوليو 2025"},". Exact file links, pages, units and source checks are kept in the project's data inventory.":{"ro":". Linkurile exacte, paginile, unitățile și verificările surselor sunt păstrate în inventarul de date al proiectului.","ar":" . تُحفظ روابط الملفات الدقيقة والصفحات والوحدات وفحوص المصادر في سجل بيانات المشروع."},"International-source outlook":{"ro":"Perspective din surse internaționale","ar":"آفاق من مصادر دولية"},"{release} projects {label} at {value}% for {year}.":{"ro":"{release} estimează {label} la {value}% pentru {year}.","ar":"يتوقع إصدار {release} أن يكون {label} عند {value}% في {year}."},"Debt is a stock relative to annual GDP. Budget and current-account balances are flows; these percentages are not interchangeable.":{"ro":"Datoria este un stoc raportat la PIB-ul anual. Soldurile bugetului și contului curent sunt fluxuri; aceste procente nu sunt interschimbabile.","ar":"الدين رصيد مقارنة بالناتج السنوي. أما رصيدا الموازنة والحساب الجاري فهما تدفقات؛ وهذه النسب ليست قابلة للتبادل."},"Inflation measures the change in prices. Lower positive inflation still means prices are rising.":{"ro":"Inflația măsoară schimbarea prețurilor. O inflație pozitivă mai mică înseamnă tot creșterea prețurilor.","ar":"يقيس التضخم تغير الأسعار. وانخفاض التضخم الموجب لا يزال يعني ارتفاع الأسعار."},"Real GDP growth describes changes in total output adjusted for prices.":{"ro":"Creșterea PIB-ului real descrie schimbarea producției totale ajustate la prețuri.","ar":"يصف نمو الناتج المحلي الحقيقي تغير الإنتاج الكلي بعد تعديل الأسعار."},"A budget balance compares government revenue and expenditure. Negative values indicate a shortfall.":{"ro":"Soldul bugetar compară veniturile și cheltuielile guvernului. Valorile negative indică un deficit.","ar":"يقارن رصيد الموازنة الإيرادات الحكومية والإنفاق. وتشير القيم السالبة إلى عجز."},"The current-account balance summarises transactions with the rest of the world. It is not the government budget.":{"ro":"Soldul contului curent rezumă tranzacțiile cu restul lumii. Nu reprezintă bugetul guvernului.","ar":"يلخص رصيد الحساب الجاري المعاملات مع بقية العالم. وهو ليس الموازنة الحكومية."},"IMF projections are source estimates, not forecasts fitted by this application. Vintage revisions can change the outlook.":{"ro":"Proiecțiile IMF sunt estimări ale sursei, nu prognoze estimate de această aplicație. Revizuirile între ediții pot schimba perspectivele.","ar":"توقعات صندوق النقد الدولي تقديرات من المصدر وليست توقعات قدّرها هذا التطبيق. وقد تغير تنقيحات الإصدارات هذه الآفاق."},"Selected annual accounts":{"ro":"Conturi anuale selectate","ar":"حسابات سنوية مختارة"},"In {year}, recorded revenue is {revenue} and spending is {spending} trillion IQD; balance {balance}.":{"ro":"În {year}, veniturile înregistrate sunt {revenue}, iar cheltuielile {spending} trilioane IQD; soldul este {balance}.","ar":"في {year}، الإيرادات المسجلة {revenue} والإنفاق {spending} تريليون دينار عراقي؛ والرصيد {balance}."},"Revenue minus expenditure is an accounting balance. A shortfall does not identify missing or stolen money.":{"ro":"Venituri minus cheltuieli reprezintă un sold contabil. Un deficit nu identifică bani lipsă sau furați.","ar":"الإيرادات ناقص الإنفاق هي رصيد محاسبي. ولا يحدد العجز أموالاً مفقودة أو مسروقة."},"CBI totals are preliminary and revisable. Their accounting perimeter differs from the IMF classification.":{"ro":"Totalurile CBI sunt preliminare și revizuibile. Perimetrul lor contabil diferă de clasificarea IMF.","ar":"إجماليات البنك المركزي العراقي أولية وقابلة للتنقيح. ويختلف نطاقها المحاسبي عن تصنيف صندوق النقد الدولي."},"Selected spending classification":{"ro":"Clasificarea selectată a cheltuielilor","ar":"تصنيف الإنفاق المختار"},"In {year}, {label} totals {value} trillion IQD.":{"ro":"În {year}, {label} însumează {value} trilioane IQD.","ar":"في {year}، يبلغ إجمالي {label} نحو {value} تريليون دينار عراقي."},"The selected parent total contains its child categories. Adding parent and child amounts double counts spending.":{"ro":"Totalul categoriei părinte include subcategoriile sale. Adunarea lor dublează cheltuielile.","ar":"يحتوي إجمالي الفئة الرئيسية المختارة على فئاتها الفرعية. وجمع مبالغها معاً يحسب الإنفاق مرتين."},"The 2024 values are IMF estimates. Classification does not establish effectiveness or completed infrastructure.":{"ro":"Valorile pentru 2024 sunt estimări IMF. Clasificarea nu dovedește eficacitatea sau infrastructura finalizată.","ar":"قيم 2024 تقديرات لصندوق النقد الدولي. ولا يثبت التصنيف الفعالية أو اكتمال البنية التحتية."},"Selected labour-survey measure":{"ro":"Indicatorul selectat al anchetei muncii","ar":"مقياس مسح العمل المختار"},"In the 2021 survey, {label} accounts for {value}% of employment.":{"ro":"În ancheta din 2021, {label} reprezintă {value}% din ocupare.","ar":"في مسح 2021، يمثل {label} نسبة {value}% من العمالة."},"Informal employment describes the job and its protection, including jobs within formal enterprises.":{"ro":"Ocuparea informală descrie locul de muncă și protecția sa, inclusiv locuri din întreprinderi formale.","ar":"تصف العمالة غير الرسمية الوظيفة وحمايتها، بما فيها الوظائف داخل المنشآت الرسمية."},"Informal-sector employment describes the enterprise or production unit, rather than the protection of each job.":{"ro":"Ocuparea în sectorul informal descrie întreprinderea sau unitatea de producție, nu protecția fiecărui loc de muncă.","ar":"تصف عمالة القطاع غير الرسمي المنشأة أو وحدة الإنتاج، بدلاً من حماية كل وظيفة."},"These are 2021 survey estimates within each group, not shares of GDP or current conditions. Group differences are not significance tests.":{"ro":"Acestea sunt estimări ale anchetei din 2021 pentru fiecare grup, nu ponderi în PIB sau condiții actuale. Diferențele între grupuri nu sunt teste de semnificație.","ar":"هذه تقديرات مسح 2021 داخل كل مجموعة، وليست حصصاً من الناتج أو ظروفاً حالية. والفروق بين المجموعات ليست اختبارات دلالة إحصائية."},"Inspect the source, units and nearby periods before suggesting an explanation.":{"ro":"Verifică sursa, unitățile și perioadele apropiate înainte de a sugera o explicație.","ar":"تحقق من المصدر والوحدات والفترات القريبة قبل اقتراح تفسير."},"Download this analysis ↓":{"ar":"تنزيل هذا التحليل ↓","ro":"Descarcă această analiză ↓"},"Outline source: Natural Earth ↗":{"ar":"مصدر المخطط: Natural Earth ↗","ro":"Sursa conturului: Natural Earth ↗"},"I compare five methods on the same 24 monthly total-revenue increments, from July 2024 to June 2026, in nominal trillion IQD. The models do not forecast the monthly budget balance. A three-month horizon predicts the single third target month, not a three-month sum. MAE is the average size of the errors; RMSE gives bigger mistakes more weight.":{"ar":"أقارن خمس طرق على الزيادات الشهرية نفسها في إجمالي الإيرادات خلال 24 شهراً، من يوليو 2024 إلى يونيو 2026، بوحدة تريليون دينار عراقي اسمي. لا تتنبأ النماذج برصيد الموازنة الشهري. أفق الثلاثة أشهر يتنبأ بالشهر المستهدف الثالث وحده، وليس بمجموع ثلاثة أشهر. يقيس MAE متوسط حجم الأخطاء، بينما يمنح RMSE الأخطاء الكبيرة وزناً أكبر.","ro":"Compar cinci metode pentru aceleași 24 de variații lunare ale veniturilor totale, din iulie 2024 până în iunie 2026, în trilioane IQD nominale. Modelele nu prognozează soldul bugetar lunar. Un orizont de trei luni estimează doar luna-țintă a treia, nu suma pe trei luni. MAE este mărimea medie a erorilor; RMSE acordă o pondere mai mare erorilor mari."},"ACCEPTED MODEL INPUT":{"ar":"مدخلات النموذج المعتمدة","ro":"INTRĂRI ACCEPTATE ÎN MODEL"},"126 months":{"ar":"126 شهراً","ro":"126 de luni"},"January 2016–June 2026 in the continuous fiscal sample used by the saved monthly experiment.":{"ar":"من يناير 2016 إلى يونيو 2026 ضمن العينة المالية المتصلة المستخدمة في التجربة الشهرية المحفوظة.","ro":"Ianuarie 2016–iunie 2026 în eșantionul fiscal continuu folosit de experimentul lunar salvat."},"SOURCE CATALOGUE":{"ar":"فهرس المصادر","ro":"CATALOGUL SURSELOR"},"55 panels":{"ar":"55 جدولاً","ro":"55 de tabele"},"A mixed catalogue of source tables and series with different periods, definitions and units. The count is not a combined dataset.":{"ar":"فهرس متنوع لجداول وسلاسل مصدرية بفترات وتعريفات ووحدات مختلفة. ولا يمثل العدد مجموعة بيانات موحدة.","ro":"Un catalog mixt de tabele și serii-sursă cu perioade, definiții și unități diferite. Numărul nu reprezintă un set de date combinat."},"REVIEW CANDIDATES":{"ar":"سجلات قيد المراجعة","ro":"ÎN CURS DE REVIZUIRE"},"39 records":{"ar":"39 سجلاً","ro":"39 de înregistrări"},"Earlier CBI records remain candidates for source review. They are kept outside the accepted model sample and are not used to extend it.":{"ar":"تظل سجلات البنك المركزي العراقي الأقدم مرشحة لمراجعة المصدر. وهي خارج عينة النموذج المعتمدة ولا تُستخدم لتوسيعها.","ro":"Înregistrările CBI mai vechi rămân candidate pentru verificarea sursei. Sunt păstrate în afara eșantionului acceptat și nu îl extind."},"Main finding":{"ar":"النتيجة الرئيسية","ro":"Concluzia principală"},"Calculation details and exact evidence":{"ar":"تفاصيل الحساب والأدلة الدقيقة","ro":"Detalii de calcul și dovezi exacte"},"The record below contains the selected values, units, dates and comparison inputs used for this explanation.":{"ar":"يتضمن السجل أدناه القيم والوحدات والتواريخ ومدخلات المقارنة المحددة المستخدمة في هذا التفسير.","ro":"Înregistrarea de mai jos conține valorile selectate, unitățile, datele și intrările de comparație folosite în această explicație."},"View forecast score table":{"ro":"Vezi tabelul scorurilor prognozei","ar":"عرض جدول درجات التنبؤ"},"Iraq’s Economic Outlook — {section}":{"ro":"Perspectivele economice ale Irakului — {section}","ar":"الآفاق الاقتصادية للعراق — {section}"},"Research analysis":{"ro":"Analiză de cercetare","ar":"تحليل بحثي"},"Website source revision: {commit}":{"ro":"Revizia sursei site-ului: {commit}","ar":"مراجعة مصدر الموقع: {commit}"},"Source snapshot dates: {dates}":{"ro":"Datele instantaneelor surselor: {dates}","ar":"تواريخ نسخ المصادر: {dates}"},"Selected source subset SHA-256: {hash}":{"ro":"SHA-256 al subsetului de surse selectat: {hash}","ar":"بصمة SHA-256 لمجموعة المصادر المحددة: {hash}"},"Research analysis · Iraq":{"ro":"Analiză de cercetare · Irak","ar":"تحليل بحثي · العراق"},"Research browser preview · Explanations and evidence reflect the controls shown in this report. Source links require internet access.":{"ro":"Previzualizare de cercetare în browser · Explicațiile și dovezile reflectă setările afișate în acest raport. Linkurile surselor necesită internet.","ar":"معاينة بحثية في المتصفح · تعكس التفسيرات والأدلة عناصر التحكم الظاهرة في هذا التقرير. تتطلب روابط المصادر اتصالاً بالإنترنت."},"How the project data is organised":{"ar":"كيفية تنظيم بيانات المشروع","ro":"Cum sunt organizate datele proiectului"},"Country paths and oil-rent exposure":{"ro":"Traiectorii economice și expunerea la rente petroliere","ar":"المسارات الاقتصادية والتعرض للريع النفطي"},"Select the countries you want to compare. The view starts with all twelve.":{"ro":"Selectează țările pe care vrei să le compari. Vizualizarea începe cu toate cele douăsprezece.","ar":"اختر البلدان التي تريد مقارنتها. يبدأ العرض بالبلدان الاثني عشر كلها."},"Select all":{"ro":"Selectează toate","ar":"تحديد الكل"},"Clear":{"ro":"Șterge selecția","ar":"مسح التحديد"},"Countries shown in the comparison chart":{"ro":"Țările afișate în graficul comparativ","ar":"البلدان الظاهرة في الرسم المقارن"},"Annual indicator":{"ro":"Indicator anual","ar":"المؤشر السنوي"},"Each line keeps its original unit. Select a tag or line to focus a country; the legend colors stay consistent between the list and plot.":{"ro":"Fiecare linie păstrează unitatea originală. Selectează eticheta sau linia pentru a evidenția o țară; culorile din legendă rămân aceleași ca în listă.","ar":"يحتفظ كل خط بوحدته الأصلية. اختر الوسم أو الخط للتركيز على بلد؛ وتبقى ألوان وسيلة الإيضاح متطابقة مع القائمة."},"Oil-rent exposure and growth volatility":{"ro":"Expunerea la rente petroliere și volatilitatea creșterii","ar":"التعرض للريع النفطي وتقلب النمو"},"Each point summarizes the available 2003–2021 annual observations for one country: mean oil rents on the horizontal axis and sample standard deviation of GDP growth on the vertical axis. This descriptive comparison does not identify a cause.":{"ro":"Fiecare punct rezumă observațiile anuale disponibile pentru o țară în perioada 2003–2021: media rentelor petroliere pe axa orizontală și abaterea standard eșantională a creșterii PIB pe axa verticală. Comparația este descriptivă și nu identifică o cauză.","ar":"تلخص كل نقطة المشاهدات السنوية المتاحة لبلد خلال 2003–2021: متوسط الريع النفطي على المحور الأفقي والانحراف المعياري للعينة لنمو الناتج على المحور العمودي. هذه مقارنة وصفية ولا تحدد سبباً."},"Mean oil rents · % of GDP":{"ro":"Media rentelor petroliere · % din PIB","ar":"متوسط الريع النفطي · % من الناتج"},"Each point is one country. The horizontal axis is mean oil rents as percent of GDP; the vertical axis is the sample standard deviation of annual real GDP growth, in percentage points.":{"ro":"Fiecare punct reprezintă o țară. Axa orizontală arată media rentelor petroliere ca procent din PIB; axa verticală arată abaterea standard eșantională a creșterii anuale reale a PIB, în puncte procentuale.","ar":"تمثل كل نقطة بلداً واحداً. يعرض المحور الأفقي متوسط الريع النفطي كنسبة من الناتج، ويعرض المحور العمودي الانحراف المعياري لعينة النمو السنوي الحقيقي للناتج، بالنقاط المئوية."},"Country":{"ro":"Țara","ar":"البلد"},"Growth volatility · percentage points":{"ro":"Volatilitatea creșterii · puncte procentuale","ar":"تقلب النمو · نقاط مئوية"},"Paired years":{"ro":"Ani observați în pereche","ar":"سنوات المشاهدات المزدوجة"},"No countries have enough paired observations for this plot.":{"ro":"Nicio țară nu are suficiente observații pereche pentru acest grafic.","ar":"لا تتوفر لأي بلد مشاهدات مزدوجة كافية لهذا الرسم."},"{label} by country":{"ro":"{label} pe țară","ar":"{label} حسب البلد"},"{country}: mean oil rents {oil} percent of GDP; growth volatility {sd} percentage points; {count} years":{"ro":"{country}: media rentelor petroliere {oil}% din PIB; volatilitatea creșterii {sd} puncte procentuale; {count} ani","ar":"{country}: متوسط الريع النفطي {oil}% من الناتج؛ تقلب النمو {sd} نقطة مئوية؛ {count} سنة"},"Skip to the application":{"ro":"Salt la aplicație","ar":"انتقل إلى التطبيق"},"MY THESIS / PYTHON APPLICATION":{"ro":"LICENȚĂ / APLICAȚIE PYTHON","ar":"أطروحتي / تطبيق بايثون"},"Explore my Python application.":{"ro":"Explorează aplicația mea Python.","ar":"استكشف تطبيق بايثون الخاص بي."},"A full-size workspace for exploring the public version of my Iraq Economic Observatory.":{"ro":"Un spațiu de lucru pe tot ecranul pentru versiunea publică a Observatorului Economic al Irakului.","ar":"مساحة عمل كاملة لاستكشاف النسخة العامة من مرصد العراق الاقتصادي."},"Application controls":{"ro":"Controalele aplicației","ar":"عناصر التحكم بالتطبيق"},"OPEN APP DIRECTLY":{"ro":"DESCHIDE APLICAȚIA DIRECT","ar":"افتح التطبيق مباشرة"},"Enter full screen":{"ro":"Intră în modul ecran complet","ar":"الدخول إلى وضع ملء الشاشة"},"Exit full screen":{"ro":"Ieși din modul ecran complet","ar":"الخروج من وضع ملء الشاشة"},"Full screen":{"ro":"Ecran complet","ar":"ملء الشاشة"},"If the embedded application does not load in your browser,":{"ro":"Dacă aplicația încorporată nu se încarcă în browser,","ar":"إذا لم يتم تحميل التطبيق المضمن في متصفحك،"},"open the application directly ↗":{"ro":"deschide aplicația direct ↗","ar":"افتح التطبيق مباشرة ↗"},"BACK TO THESIS":{"ro":"ÎNAPOI LA LUCRARE","ar":"العودة إلى الأطروحة"},"My Python application | Nooruldeen":{"ro":"Aplicația mea Python | Nooruldeen","ar":"تطبيق بايثون الخاص بي | نورالدين"},"Open my Iraq Economic Observatory Python application in a dedicated workspace.":{"ro":"Deschide aplicația Observatorul Economic al Irakului într-un spațiu de lucru dedicat.","ar":"افتح تطبيق مرصد العراق الاقتصادي في مساحة عمل مخصصة."},"Iraq Economic Observatory Python application":{"ro":"Aplicația Python Observatorul Economic al Irakului","ar":"تطبيق مرصد العراق الاقتصادي بلغة بايثون"},"Open the full-size workspace in my website.":{"ro":"Deschide spațiul de lucru pe tot ecranul pe site-ul meu.","ar":"افتح مساحة العمل الكاملة على موقعي."},"Open the public application in its full-size workspace.":{"ro":"Deschide aplicația publică în spațiul de lucru pe tot ecranul.","ar":"افتح التطبيق العام في مساحة العمل الكاملة."},"THE FULL APPLICATION / PYTHON":{"ro":"APLICAȚIA COMPLETĂ / PYTHON","ar":"التطبيق الكامل / Python"},"Open the live workspace.":{"ro":"Deschide spațiul de lucru activ.","ar":"افتح مساحة العمل الحالية."},"Explore the application page to try the current public workbench and inspect the project tools.":{"ro":"Deschide pagina aplicației pentru a încerca spațiul public de lucru actual și a explora instrumentele proiectului.","ar":"افتح صفحة التطبيق لتجربة مساحة العمل العامة الحالية واستكشاف أدوات المشروع."},"TRY THE APPLICATION ↗":{"ro":"ÎNCEARCĂ APLICAȚIA ↗","ar":"جرّب التطبيق ↗"}};
  const languages = ["en", "ro", "ar"], storageKey = "nooruldeen-language";
  const normalize = value => String(value).replace(/\s+/g, " ").trim();
  let language = "en";
  const nodes = [], attributes = [], links = [];
  const title = document.title, description = document.querySelector('meta[name="description"]');
  const descriptionSource = description?.content;
  function translate(source, values = {}) {
    const key = normalize(source);
    let value = language === "en" ? key : (catalog[key]?.[language] ?? key);
    // Publication dates change at build time; they do not require a new translation.
    const publication = key.match(/^Published (\d{4}-\d{2}-\d{2}) · (.*)$/);
    if (publication && language !== "en") {
      value = (language === "ro" ? "Publicat la " : "نُشر في ") + publication[1] + " · " +
        (language === "ro" ? "Datele fiscale lunare se încheie în iunie 2026 · Surse salvate: 10 și 12 octombrie 2026" : "تنتهي بيانات المالية الشهرية في يونيو 2026 · نسخ المصادر: 10 و12 أكتوبر 2026");
    }
    return value.replace(/\{([a-z_]+)\}/g, (_, name) => String(values[name] ?? "{" + name + "}"));
  }
  function initial() {
    const query = new URLSearchParams(location.search).get("lang");
    if (languages.includes(query)) return query;
    try { const saved = localStorage.getItem(storageKey); if (languages.includes(saved)) return saved; } catch (_) {}
    return "en";
  }
  function collect() {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) {
      const node = walker.currentNode;
      if (node.parentElement.closest("script, style, .language-switcher") || !node.textContent.trim()) continue;
      nodes.push([node, node.textContent]);
    }
    document.querySelectorAll("[aria-label], [alt], [title]").forEach(element => {
      for (const name of ["aria-label", "alt", "title"]) {
        if (element.hasAttribute(name)) attributes.push([element, name, element.getAttribute(name)]);
      }
    });
    document.querySelectorAll("a[href]").forEach(link => {
      const source = link.getAttribute("href"), url = new URL(source, location.href);
      if (url.origin === location.origin && !source.startsWith("#")) links.push([link, source]);
    });
  }
  function arabicFont() {
    if (document.getElementById("thesis-arabic-font")) return;
    const link = document.createElement("link"); link.id = "thesis-arabic-font"; link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Noto+Sans+Arabic:wght@400;500;600;700&display=swap";
    document.head.appendChild(link);
  }
  function setLanguage(next, updateUrl = true) {
    if (!languages.includes(next)) return;
    language = next; document.documentElement.lang = next; document.documentElement.dir = next === "ar" ? "rtl" : "ltr";
    if (next === "ar") arabicFont();
    nodes.forEach(([node, source]) => {
      const leading = source.match(/^\s*/)[0], trailing = source.match(/\s*$/)[0];
      node.textContent = leading + translate(source) + trailing;
    });
    attributes.forEach(([element, name, source]) => element.setAttribute(name, translate(source)));
    document.title = translate(title); if (description) description.content = translate(descriptionSource);
    links.forEach(([link, source]) => { const url = new URL(source, location.href); url.searchParams.set("lang", next); link.href = url.pathname + url.search + url.hash; });
    document.querySelectorAll("[data-thesis-lang]").forEach(button => {
      button.setAttribute("aria-pressed", String(button.dataset.thesisLang === next)); button.title = translate(button.dataset.languageName);
    });
    document.querySelector(".language-switcher").setAttribute("aria-label", translate("Select language"));
    try { localStorage.setItem(storageKey, next); } catch (_) {}
    if (updateUrl) { const url = new URL(location.href); url.searchParams.set("lang", next); history.replaceState(null, "", url.pathname + url.search + url.hash); }
    window.dispatchEvent(new Event("noor-thesis-language"));
  }
  const switcher = document.createElement("div"); switcher.className = "language-switcher"; switcher.setAttribute("role", "group");
  [["en", "EN", "English"], ["ro", "RO", "Romanian"], ["ar", "عربي", "Arabic"]].forEach(([code, label, name]) => {
    const button = document.createElement("button"); button.type = "button"; button.textContent = label; button.lang = code;
    button.dataset.thesisLang = code; button.dataset.languageName = name; button.addEventListener("click", () => setLanguage(code)); switcher.appendChild(button);
  });
  const header = document.querySelector(".topline"); header.insertBefore(switcher, header.querySelector(".topline-contact"));
  collect();
  const contents = document.querySelector(".plan-toc");
  if (contents && window.matchMedia("(max-width:900px)").matches) contents.open = false;
  window.noorThesisI18n = {t:translate, get language() { return language; }, get locale() { return {en:"en-GB", ro:"ro-RO", ar:"ar-IQ-u-nu-latn"}[language]; }};
  setLanguage(initial(), false);
  window.addEventListener("popstate", () => setLanguage(initial(), false));
})();
